css:
/* Team chat. Re-theme with --apc-team-bg, -ink, -accent and -hot (and -h for height). */
.apc-team {
  --apc-team-bg: oklch(0.986 0.005 100);
  --apc-team-ink: oklch(0.255 0.022 168);
  --apc-team-accent: oklch(0.52 0.105 160);
  --apc-team-hot: oklch(0.6 0.19 31);

  --apc-team-side: color-mix(in oklch, var(--apc-team-accent) 6%, color-mix(in oklch, var(--apc-team-ink) 3%, var(--apc-team-bg)));
  --apc-team-line: color-mix(in oklch, var(--apc-team-ink) 10%, transparent);
  --apc-team-line2: color-mix(in oklch, var(--apc-team-ink) 17%, transparent);
  --apc-team-muted: color-mix(in oklch, var(--apc-team-ink) 64%, var(--apc-team-bg));
  --apc-team-faint: color-mix(in oklch, var(--apc-team-ink) 44%, var(--apc-team-bg));
  --apc-team-hover: color-mix(in oklch, var(--apc-team-ink) 4.5%, transparent);
  --apc-team-tint: color-mix(in oklch, var(--apc-team-accent) 11%, var(--apc-team-bg));
  --apc-team-deep: color-mix(in oklch, var(--apc-team-accent) 78%, var(--apc-team-ink));
  --apc-team-warn: color-mix(in oklab, oklch(0.84 0.15 88) 22%, var(--apc-team-bg));
  --apc-team-ease: cubic-bezier(.2, .8, .2, 1);
  --apc-team-out: cubic-bezier(.32, .72, 0, 1);
  --apc-team-spring: linear(0, 0.06 2.5%, 0.25 6%, 0.6 12.5%, 0.86 19%, 1.01 26%, 1.05 32%, 1.04 39%, 1.01 50%, 0.997 66%, 1);

  position: relative;
  isolation: isolate;
  width: 100%;
  height: var(--apc-team-h, 680px);
  container-type: inline-size;
  overflow: hidden;
  overflow: clip;
  border-radius: 14px;
  background: var(--apc-team-bg);
  color: var(--apc-team-ink);
  font: 400 14px/1.5 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  -webkit-font-smoothing: antialiased;
  color-scheme: light;
  accent-color: var(--apc-team-accent);
  box-shadow: inset 0 0 0 1px var(--apc-team-line);
}
:where(.apc-team) *, :where(.apc-team) *::before, :where(.apc-team) *::after { box-sizing: border-box; }
:where(.apc-team) :is(button, input, textarea) { font: inherit; color: inherit; }
:where(.apc-team) button { background: none; border: 0; padding: 0; cursor: pointer; }
:where(.apc-team) :is(ol, ul) { list-style: none; margin: 0; padding: 0; }
:where(.apc-team) :is(h2, h3, p) { margin: 0; }
:where(.apc-team) svg { width: 18px; height: 18px; fill: none; stroke: currentColor; stroke-width: 1.75; stroke-linecap: round; stroke-linejoin: round; flex: none; }
:where(.apc-team) :focus-visible { outline: 2px solid var(--apc-team-accent); outline-offset: 2px; border-radius: 6px; }
.apc-team [hidden] { display: none !important; }
.apc-team__kbd {
  display: inline-grid; place-items: center; min-width: 18px; height: 18px; padding: 0 4px; border-radius: 4px;
  font: 600 10.5px/1 ui-monospace, Menlo, monospace; color: var(--apc-team-muted);
  background: var(--apc-team-bg); box-shadow: inset 0 -1px 0 var(--apc-team-line2), 0 0 0 1px var(--apc-team-line2);
}

/* ---------- shell: the thread column is driven entirely by :has() ---------- */
.apc-team__app {
  position: relative;
  display: grid; height: 100%;
  grid-template-columns: 252px minmax(0, 1fr) 0px;
  grid-template-areas: "side chan thread";
  transition: grid-template-columns .55s var(--apc-team-spring);
}
.apc-team:has(.apc-team__thread[data-open]) .apc-team__app { grid-template-columns: 252px minmax(0, 1fr) 372px; }
.apc-team__side { grid-area: side; }
.apc-team__chan { grid-area: chan; }
.apc-team__thread { grid-area: thread; }

/* ---------- sidebar ---------- */
.apc-team__side {
  display: grid; grid-template-columns: minmax(0, 1fr); grid-template-rows: auto auto minmax(0, 1fr) auto; min-height: 0;
  background: var(--apc-team-side); border-right: 1px solid var(--apc-team-line);
}
.apc-team__ws { display: flex; align-items: center; gap: 10px; padding: 16px 16px 12px; }
.apc-team__logo { display: grid; place-items: center; width: 34px; height: 34px; border-radius: 10px; background: var(--apc-team-deep); color: var(--apc-team-bg); flex: none; }
.apc-team__logo svg { width: 20px; height: 20px; stroke-width: 1.9; }
.apc-team__wsname { display: grid; line-height: 1.2; min-width: 0; }
.apc-team__wsname b { font-size: 15px; font-weight: 750; letter-spacing: -0.015em; }
.apc-team__wsname small { font-size: 11.5px; color: var(--apc-team-faint); white-space: nowrap; }
.apc-team__jump {
  margin: 0 12px 10px; display: flex; align-items: center; gap: 8px; height: 34px; padding: 0 8px 0 10px; border-radius: 9px;
  background: var(--apc-team-bg); box-shadow: 0 0 0 1px var(--apc-team-line2), 0 1px 2px var(--apc-team-line);
  color: var(--apc-team-faint); font-size: 13px; transition: box-shadow .2s, color .2s;
}
.apc-team__jump:hover { color: var(--apc-team-ink); box-shadow: 0 0 0 1px color-mix(in oklch, var(--apc-team-accent) 45%, transparent), 0 2px 8px -2px var(--apc-team-line2); }
.apc-team__jump span { flex: 1; text-align: left; }
.apc-team__jump svg { width: 15px; height: 15px; }
.apc-team__nav { overflow: auto; padding: 4px 8px 12px; scrollbar-width: thin; overscroll-behavior: contain; }
.apc-team__sec + .apc-team__sec { margin-top: 10px; }
.apc-team__sechead {
  display: flex; align-items: center; gap: 4px; width: 100%; height: 28px; padding: 0 8px; border-radius: 6px;
  font-size: 11px; font-weight: 700; letter-spacing: .08em; text-transform: uppercase; color: var(--apc-team-faint);
}
.apc-team__sechead:hover { color: var(--apc-team-ink); }
.apc-team__sechead svg { width: 13px; height: 13px; stroke-width: 2.2; transition: rotate .3s var(--apc-team-ease); }
.apc-team__sechead[aria-expanded="false"] svg { rotate: -90deg; }
.apc-team__fold { display: grid; grid-template-rows: 1fr; transition: grid-template-rows .35s var(--apc-team-out); }
.apc-team__fold > ul { min-height: 0; overflow: hidden; }
.apc-team__sechead[aria-expanded="false"] + .apc-team__fold { grid-template-rows: 0fr; }
.apc-team__item {
  position: relative; display: flex; align-items: center; gap: 9px; width: 100%; height: 31px; padding: 0 8px; border-radius: 7px;
  font-size: 14px; color: var(--apc-team-muted); text-align: left; transition: background-color .18s, color .18s;
}
.apc-team__item:hover { background: var(--apc-team-hover); color: var(--apc-team-ink); }
.apc-team__item > svg { width: 15px; height: 15px; color: var(--apc-team-faint); }
.apc-team__item > span:not(.apc-team__av) { flex: 1; min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.apc-team__item[data-unread] { color: var(--apc-team-ink); font-weight: 680; }
.apc-team__item[data-unread] > svg { color: var(--apc-team-ink); }
.apc-team__item[aria-current="page"] { background: var(--apc-team-deep); color: var(--apc-team-bg); font-weight: 600; }
.apc-team__item[aria-current="page"] > svg { color: color-mix(in oklch, var(--apc-team-bg) 80%, transparent); }
.apc-team__item .apc-team__av { --s: 20px; font-size: 9px; border-radius: 6px; }
.apc-team__badge {
  min-width: 20px; height: 18px; padding: 0 6px; border-radius: 9px; display: grid; place-items: center;
  font-size: 11px; font-weight: 750; font-variant-numeric: tabular-nums; color: white; background: var(--apc-team-hot);
  animation: apc-team-pop .45s var(--apc-team-spring) both;
}
.apc-team__badge[data-soft] { background: color-mix(in oklch, var(--apc-team-ink) 14%, transparent); color: var(--apc-team-ink); }
.apc-team__me { padding: 10px; border-top: 1px solid var(--apc-team-line); }
.apc-team__status { display: flex; align-items: center; gap: 10px; width: 100%; padding: 6px; border-radius: 9px; text-align: left; }
.apc-team__status:hover { background: var(--apc-team-hover); }
.apc-team__melbl { display: grid; line-height: 1.25; min-width: 0; }
.apc-team__melbl b { font-size: 13.5px; font-weight: 650; }
.apc-team__melbl small { font-size: 11.5px; color: var(--apc-team-faint); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }

/* avatars: hue from the name, soft fill, presence dot */
.apc-team__av {
  --s: 36px; position: relative; display: inline-grid; place-items: center; width: var(--s); height: var(--s); flex: none;
  border-radius: 10px; font-size: 12.5px; font-weight: 700; letter-spacing: .02em;
  background: oklch(0.9 0.055 var(--h)); color: oklch(0.36 0.09 var(--h));
}
.apc-team__av[data-presence]::after {
  content: ""; position: absolute; right: -3px; bottom: -3px; width: 10px; height: 10px; border-radius: 50%;
  background: var(--apc-team-faint); box-shadow: 0 0 0 2.5px var(--apc-team-side);
}
.apc-team__av[data-presence="active"]::after { background: oklch(0.66 0.16 150); }
.apc-team__av[data-presence="away"]::after { background: var(--apc-team-side); box-shadow: 0 0 0 2.5px var(--apc-team-side), inset 0 0 0 2px var(--apc-team-faint); }
.apc-team__av[data-bot] { background: var(--apc-team-ink); color: var(--apc-team-bg); }
.apc-team__av[data-bot] svg { width: 60%; height: 60%; }

/* ---------- channel ---------- */
.apc-team__chan { position: relative; display: grid; grid-template-columns: minmax(0, 1fr); grid-template-rows: auto minmax(0, 1fr) auto auto; min-width: 0; min-height: 0; }
.apc-team__head { display: flex; align-items: center; gap: 12px; min-height: 60px; padding: 10px 20px; border-bottom: 1px solid var(--apc-team-line); }
.apc-team__back { display: none; place-items: center; width: 32px; height: 32px; border-radius: 8px; margin-left: -8px; }
.apc-team__back:hover { background: var(--apc-team-hover); }
.apc-team__title { min-width: 0; flex: 1; }
.apc-team__title h2 { display: flex; align-items: center; gap: 6px; font-size: 16px; font-weight: 760; letter-spacing: -0.02em; text-wrap: balance; }
.apc-team__title h2 svg { width: 16px; height: 16px; stroke-width: 2.2; color: var(--apc-team-faint); }
.apc-team__title p { font-size: 12.5px; color: var(--apc-team-faint); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.apc-team__members { display: flex; align-items: center; padding: 3px 10px 3px 4px; border-radius: 9px; box-shadow: 0 0 0 1px var(--apc-team-line2); font-size: 12.5px; font-weight: 650; font-variant-numeric: tabular-nums; color: var(--apc-team-muted); flex: none; }
.apc-team__members .apc-team__av { --s: 24px; font-size: 9px; border-radius: 50%; box-shadow: 0 0 0 2px var(--apc-team-bg); }
.apc-team__members .apc-team__av + .apc-team__av { margin-left: -6px; }
.apc-team__members b { margin-left: 7px; font-weight: 650; }

.apc-team__scroll { overflow: auto; overscroll-behavior: contain; scrollbar-width: thin; outline: none; }
.apc-team__msgs { display: flex; flex-direction: column; justify-content: flex-end; min-height: 100%; padding: 8px 0 14px; }
.apc-team__day { position: sticky; top: 0; z-index: 3; display: grid; place-items: center; height: 34px; margin: 6px 0 2px; pointer-events: none; }
.apc-team__day::before { content: ""; position: absolute; inset: 50% 0 auto; border-top: 1px solid var(--apc-team-line); }
.apc-team__day span {
  position: relative; padding: 3px 12px; border-radius: 99px; font-size: 12px; font-weight: 650; color: var(--apc-team-muted);
  background: var(--apc-team-bg); box-shadow: 0 0 0 1px var(--apc-team-line2), 0 2px 6px -2px var(--apc-team-line2);
}
.apc-team__new { position: relative; height: 18px; margin: 6px 20px 2px 68px; }
.apc-team__new::before { content: ""; position: absolute; inset: 50% 0 auto; border-top: 1px solid var(--apc-team-hot); }
.apc-team__new span { position: absolute; right: 0; top: 50%; translate: 0 -50%; padding: 0 6px; font-size: 10.5px; font-weight: 800; letter-spacing: .08em; text-transform: uppercase; color: var(--apc-team-hot); background: var(--apc-team-bg); }

.apc-team__msg {
  position: relative; display: grid; grid-template-columns: 36px minmax(0, 1fr); column-gap: 12px;
  padding: 7px 20px 5px 20px; transition: background-color .2s;
}
.apc-team__msg[data-cont] { padding-top: 1px; }
.apc-team__msg:is(:hover, :focus-within) { background: var(--apc-team-hover); }
.apc-team__msg[data-mention] { background: var(--apc-team-warn); box-shadow: inset 3px 0 oklch(0.78 0.15 80); }
.apc-team__msg[data-flash] { animation: apc-team-flash 1.6s var(--apc-team-ease); }
.apc-team__gut { padding-top: 2px; }
.apc-team__gut time { display: block; padding-top: 2px; font-size: 10.5px; color: var(--apc-team-faint); text-align: right; font-variant-numeric: tabular-nums; opacity: 0; transition: opacity .15s; }
.apc-team__msg:is(:hover, :focus-within) .apc-team__gut time { opacity: 1; }
.apc-team__meta { display: flex; align-items: baseline; gap: 8px; line-height: 1.3; }
.apc-team__meta b { font-size: 14.5px; font-weight: 720; letter-spacing: -0.01em; }
.apc-team__meta time { font-size: 11.5px; color: var(--apc-team-faint); font-variant-numeric: tabular-nums; }
.apc-team__app-tag { padding: 0 4px; border-radius: 4px; font-size: 9.5px; font-weight: 800; letter-spacing: .06em; color: var(--apc-team-muted); background: color-mix(in oklch, var(--apc-team-ink) 9%, transparent); }
.apc-team__text { font-size: 14.5px; line-height: 1.52; text-wrap: pretty; overflow-wrap: anywhere; white-space: pre-wrap; }
.apc-team__text code { padding: 1px 5px; border-radius: 5px; font: 500 12.5px/1.4 ui-monospace, Menlo, monospace; color: var(--apc-team-hot); background: color-mix(in oklch, var(--apc-team-hot) 8%, var(--apc-team-bg)); box-shadow: 0 0 0 1px color-mix(in oklch, var(--apc-team-hot) 15%, transparent); }
.apc-team__text b { font-weight: 700; }
.apc-team__text small { font-size: 11.5px; color: var(--apc-team-faint); }
.apc-team__at { padding: 0 3px; border-radius: 4px; font-weight: 600; color: var(--apc-team-deep); background: color-mix(in oklch, var(--apc-team-accent) 13%, transparent); }
.apc-team__at[data-me] { color: oklch(0.42 0.12 70); background: color-mix(in oklch, oklch(0.84 0.15 88) 45%, transparent); }
.apc-team__edit { display: grid; gap: 6px; margin: 4px 0 2px; }
.apc-team__edit textarea { width: 100%; min-height: 40px; padding: 8px 10px; border-radius: 9px; border: 0; resize: none; field-sizing: content; max-height: 140px; background: var(--apc-team-bg); box-shadow: 0 0 0 1.5px var(--apc-team-accent), 0 0 0 5px color-mix(in oklch, var(--apc-team-accent) 14%, transparent); outline: none; line-height: 1.5; }
.apc-team__edit p { font-size: 12px; color: var(--apc-team-faint); }

.apc-team__reacts { display: flex; flex-wrap: wrap; gap: 5px; margin-top: 5px; }
.apc-team__reacts:empty { display: none; }
.apc-team__react {
  display: inline-flex; align-items: center; gap: 5px; height: 25px; padding: 0 8px 0 6px; border-radius: 99px;
  font-size: 12px; font-weight: 650; font-variant-numeric: tabular-nums; color: var(--apc-team-muted);
  background: var(--apc-team-bg); box-shadow: 0 0 0 1px var(--apc-team-line2);
  transition: box-shadow .2s, background-color .2s, color .2s, scale .25s var(--apc-team-spring);
}
.apc-team__react:hover { box-shadow: 0 0 0 1px var(--apc-team-faint); color: var(--apc-team-ink); }
.apc-team__react:active { scale: .92; }
.apc-team__react svg { width: 15px; height: 15px; color: var(--c); stroke-width: 2; }
.apc-team__react[aria-pressed="true"] { color: var(--apc-team-deep); background: var(--apc-team-tint); box-shadow: 0 0 0 1.5px color-mix(in oklch, var(--apc-team-accent) 60%, transparent); }
.apc-team__react[aria-pressed="true"] svg { fill: color-mix(in oklch, var(--c) 28%, transparent); }
.apc-team__react[data-bump] { animation: apc-team-bump .5s var(--apc-team-spring); }
.apc-team__react b { display: inline-block; font-weight: 700; }
.apc-team__react[data-bump] b { animation: apc-team-roll .35s var(--apc-team-out); }
.apc-team__react--add { padding: 0 6px; color: var(--apc-team-faint); opacity: 0; transition: opacity .15s; }
.apc-team__msg:is(:hover, :focus-within) .apc-team__react--add { opacity: 1; }

.apc-team__replies {
  display: flex; align-items: center; gap: 8px; margin-top: 6px; padding: 4px 8px 4px 4px; margin-left: -4px; border-radius: 8px; max-width: 100%;
  font-size: 12.5px; transition: background-color .18s, box-shadow .18s;
}
.apc-team__replies:hover { background: var(--apc-team-bg); box-shadow: 0 0 0 1px var(--apc-team-line2); }
.apc-team__replies .apc-team__av { --s: 22px; font-size: 8.5px; border-radius: 6px; }
.apc-team__replies b { color: var(--apc-team-deep); font-weight: 700; white-space: nowrap; }
.apc-team__replies span { color: var(--apc-team-faint); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; font-variant-numeric: tabular-nums; }
.apc-team__replies i { font-style: normal; color: var(--apc-team-faint); display: none; white-space: nowrap; }
.apc-team__replies:hover span { display: none; }
.apc-team__replies:hover i { display: inline; }

.apc-team__tools {
  position: absolute; top: -14px; right: 18px; z-index: 4; display: flex; padding: 2px; border-radius: 9px;
  background: var(--apc-team-bg); box-shadow: 0 0 0 1px var(--apc-team-line2), 0 6px 16px -6px color-mix(in oklch, var(--apc-team-ink) 30%, transparent);
  opacity: 0; translate: 0 4px; pointer-events: none; transition: opacity .16s, translate .25s var(--apc-team-out);
}
.apc-team__msg:is(:hover, :focus-within) .apc-team__tools { opacity: 1; translate: 0 0; pointer-events: auto; }
.apc-team__tools button { display: grid; place-items: center; width: 30px; height: 28px; border-radius: 7px; color: var(--apc-team-muted); }
.apc-team__tools button:hover { background: var(--apc-team-hover); color: var(--apc-team-ink); }
.apc-team__tools button[data-act="delete"]:hover { color: var(--apc-team-hot); }
.apc-team__tools svg { width: 16px; height: 16px; }

/* entry motion: staggered on channel switch, single rise for new posts */
.apc-team__msgs[data-enter] > li { animation: apc-team-rise .42s var(--apc-team-out) both; animation-delay: calc(var(--i, 0) * 26ms); }
.apc-team__msg[data-new] { animation: apc-team-rise .45s var(--apc-team-spring) both; }
.apc-team__msg[data-leaving] { animation: apc-team-leave .32s var(--apc-team-ease) forwards; pointer-events: none; }

.apc-team__jumpnew {
  position: absolute; left: 50%; bottom: 132px; z-index: 5; translate: -50% 0; display: flex; align-items: center; gap: 6px; height: 30px; padding: 0 12px 0 10px; border-radius: 99px;
  font-size: 12.5px; font-weight: 650; color: var(--apc-team-bg); background: var(--apc-team-deep); box-shadow: 0 8px 20px -8px color-mix(in oklch, var(--apc-team-ink) 50%, transparent);
  transition: translate .35s var(--apc-team-spring), opacity .2s;
  @starting-style { translate: -50% 10px; opacity: 0; }
}
.apc-team__jumpnew svg { width: 14px; height: 14px; stroke-width: 2.2; }

.apc-team__typing { height: 20px; padding: 0 22px; font-size: 12px; color: var(--apc-team-faint); display: flex; align-items: center; gap: 6px; white-space: nowrap; overflow: hidden; }
.apc-team__typing b { color: var(--apc-team-muted); font-weight: 650; }
.apc-team__dots { display: inline-flex; gap: 3px; }
.apc-team__dots i { width: 5px; height: 5px; border-radius: 50%; background: var(--apc-team-faint); animation: apc-team-dot 1.1s var(--apc-team-ease) infinite; animation-delay: calc(var(--i) * 140ms); }

/* ---------- composer ---------- */
.apc-team__composer { padding: 0 16px 14px; }
.apc-team__box {
  border-radius: 12px; background: var(--apc-team-bg); box-shadow: 0 0 0 1px var(--apc-team-line2), 0 1px 3px var(--apc-team-line);
  transition: box-shadow .2s;
}
.apc-team__box:focus-within { box-shadow: 0 0 0 1.5px color-mix(in oklch, var(--apc-team-accent) 70%, transparent), 0 0 0 5px color-mix(in oklch, var(--apc-team-accent) 12%, transparent); }
.apc-team__box textarea {
  display: block; width: 100%; min-height: 44px; max-height: 150px; padding: 12px 14px 4px; border: 0; resize: none; background: none; outline: none;
  field-sizing: content; line-height: 1.5; font-size: 14.5px;
}
.apc-team__box textarea::placeholder { color: var(--apc-team-faint); }
.apc-team__bar { display: flex; align-items: center; gap: 2px; padding: 4px 6px 6px; }
.apc-team__bar > button:not(.apc-team__send) { display: grid; place-items: center; width: 30px; height: 30px; border-radius: 7px; color: var(--apc-team-faint); }
.apc-team__bar > button:not(.apc-team__send):hover { background: var(--apc-team-hover); color: var(--apc-team-ink); }
.apc-team__bar > button svg { width: 16px; height: 16px; }
.apc-team__hint { flex: 1; display: flex; align-items: center; justify-content: flex-end; gap: 5px; padding-right: 10px; font-size: 11.5px; color: var(--apc-team-faint); white-space: nowrap; overflow: hidden; }
.apc-team__hint .apc-team__kbd:not(:first-child) { margin-left: 8px; }
.apc-team__send {
  display: grid; place-items: center; width: 34px; height: 30px; border-radius: 8px; margin-left: auto;
  color: var(--apc-team-bg); background: var(--apc-team-deep); transition: background-color .2s, opacity .2s, scale .3s var(--apc-team-spring);
}
.apc-team__send svg { width: 16px; height: 16px; }
.apc-team__send:disabled { background: color-mix(in oklch, var(--apc-team-ink) 10%, transparent); color: var(--apc-team-faint); cursor: default; }
.apc-team__send:not(:disabled):active { scale: .9; }
.apc-team__also { display: flex; align-items: center; gap: 6px; padding-left: 8px; font-size: 12.5px; color: var(--apc-team-muted); cursor: pointer; min-width: 0; }
.apc-team__also span { white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.apc-team__also input { margin: 0; width: 15px; height: 15px; }

/* ---------- thread pane ---------- */
.apc-team__thread { position: relative; min-width: 0; min-height: 0; overflow: hidden; border-left: 1px solid var(--apc-team-line); background: var(--apc-team-bg); }
.apc-team__tin { width: 372px; height: 100%; display: grid; grid-template-columns: minmax(0, 1fr); grid-template-rows: auto minmax(0, 1fr) auto auto; }
.apc-team__thread[data-open] .apc-team__tin { animation: apc-team-slide .5s var(--apc-team-out) both; }
.apc-team__thead { display: flex; align-items: center; justify-content: space-between; gap: 8px; min-height: 60px; padding: 10px 14px 10px 18px; border-bottom: 1px solid var(--apc-team-line); }
.apc-team__thead div { display: grid; line-height: 1.25; }
.apc-team__thead b { font-size: 15px; font-weight: 760; letter-spacing: -0.015em; }
.apc-team__thead small { font-size: 12px; color: var(--apc-team-faint); }
.apc-team__thead button { display: flex; align-items: center; gap: 6px; height: 30px; padding: 0 6px; border-radius: 8px; color: var(--apc-team-muted); }
.apc-team__thead button:hover { background: var(--apc-team-hover); color: var(--apc-team-ink); }
.apc-team__tscroll { overflow: auto; overscroll-behavior: contain; scrollbar-width: thin; }
.apc-team__tmsgs { padding: 10px 0 14px; }
.apc-team__tmsgs .apc-team__msg { padding-inline: 16px; }
.apc-team__tmsgs .apc-team__tools { right: 12px; }
.apc-team__tcount { display: flex; align-items: center; gap: 10px; margin: 8px 16px; font-size: 12px; font-weight: 650; color: var(--apc-team-faint); font-variant-numeric: tabular-nums; }
.apc-team__tcount::after { content: ""; flex: 1; border-top: 1px solid var(--apc-team-line); }

/* ---------- floating layers ---------- */
.apc-team__mention {
  position: absolute; z-index: 30; width: 260px; padding: 5px; border-radius: 12px; background: var(--apc-team-bg);
  box-shadow: 0 0 0 1px var(--apc-team-line2), 0 18px 40px -16px color-mix(in oklch, var(--apc-team-ink) 45%, transparent);
  transform-origin: 20px 100%; transition: opacity .18s, scale .3s var(--apc-team-spring);
  @starting-style { opacity: 0; scale: .94; }
}
.apc-team__mention li { display: flex; align-items: center; gap: 9px; padding: 6px 8px; border-radius: 8px; cursor: pointer; font-size: 13.5px; }
.apc-team__mention li small { margin-left: auto; color: var(--apc-team-faint); font-size: 11.5px; }
.apc-team__mention li .apc-team__av { --s: 24px; font-size: 9.5px; border-radius: 7px; }
.apc-team__mention li[aria-selected="true"] { background: var(--apc-team-tint); }
.apc-team__mention li[aria-selected="true"] small { color: var(--apc-team-deep); }

.apc-team__picker {
  position: absolute; z-index: 30; display: grid; grid-template-columns: repeat(6, 34px); gap: 2px; padding: 6px; border-radius: 12px; background: var(--apc-team-bg);
  box-shadow: 0 0 0 1px var(--apc-team-line2), 0 18px 40px -16px color-mix(in oklch, var(--apc-team-ink) 45%, transparent);
  transition: opacity .18s, scale .32s var(--apc-team-spring); transform-origin: 100% 0;
  @starting-style { opacity: 0; scale: .9; }
}
.apc-team__picker button { display: grid; place-items: center; width: 34px; height: 34px; border-radius: 8px; color: var(--c); transition: background-color .15s, scale .25s var(--apc-team-spring); }
.apc-team__picker button:is(:hover, :focus-visible) { background: color-mix(in oklch, var(--c) 13%, transparent); scale: 1.12; outline: none; }
.apc-team__picker svg { width: 19px; height: 19px; stroke-width: 2; }

.apc-team__switcher {
  position: absolute; inset: 0; z-index: 40; display: grid; justify-items: center; align-items: start; padding: clamp(16px, 9cqi, 90px) 16px 16px;
  background: color-mix(in oklch, var(--apc-team-ink) 24%, transparent);
  transition: opacity .2s; @starting-style { opacity: 0; }
}
.apc-team__sbox {
  width: min(560px, 100%); border-radius: 16px; background: var(--apc-team-bg); overflow: hidden;
  box-shadow: 0 0 0 1px var(--apc-team-line2), 0 40px 80px -30px color-mix(in oklch, var(--apc-team-ink) 60%, transparent);
  transition: translate .45s var(--apc-team-spring), scale .45s var(--apc-team-spring);
  @starting-style { translate: 0 -10px; scale: .97; }
}
.apc-team__sfield { display: flex; align-items: center; gap: 10px; padding: 14px 16px; border-bottom: 1px solid var(--apc-team-line); }
.apc-team__sfield input { flex: 1; min-width: 0; border: 0; outline: none; background: none; font-size: 16px; }
.apc-team__sfield svg { color: var(--apc-team-faint); }
.apc-team__slist { max-height: 300px; overflow: auto; padding: 6px; }
.apc-team__slist li { display: flex; align-items: center; gap: 10px; height: 38px; padding: 0 10px; border-radius: 9px; cursor: pointer; font-size: 14px; animation: apc-team-rise .3s var(--apc-team-out) both; animation-delay: calc(var(--i) * 18ms); }
.apc-team__slist li > svg { width: 16px; height: 16px; color: var(--apc-team-faint); }
.apc-team__slist li .apc-team__av { --s: 24px; font-size: 9.5px; border-radius: 7px; }
.apc-team__slist li small { margin-left: auto; font-size: 12px; color: var(--apc-team-faint); white-space: nowrap; }
.apc-team__slist li mark { background: none; color: var(--apc-team-deep); font-weight: 750; }
.apc-team__slist li[aria-selected="true"] { background: var(--apc-team-tint); }
.apc-team__slist .apc-team__none { justify-content: center; color: var(--apc-team-faint); cursor: default; height: 64px; }
.apc-team__sfoot { display: flex; flex-wrap: wrap; gap: 6px 16px; padding: 10px 16px; font-size: 11.5px; color: var(--apc-team-faint); border-top: 1px solid var(--apc-team-line); background: var(--apc-team-side); }
.apc-team__sfoot span { display: inline-flex; align-items: center; gap: 3px; }

.apc-team__toast {
  position: absolute; left: 50%; bottom: 18px; z-index: 35; display: flex; align-items: center; gap: 12px; padding: 8px 8px 8px 14px; border-radius: 11px;
  font-size: 13px; color: var(--apc-team-bg); background: var(--apc-team-ink); box-shadow: 0 16px 40px -14px color-mix(in oklch, var(--apc-team-ink) 70%, transparent);
  translate: -50% 16px; opacity: 0; pointer-events: none; transition: translate .45s var(--apc-team-spring), opacity .2s; white-space: nowrap;
}
.apc-team__toast[data-show] { translate: -50% 0; opacity: 1; pointer-events: auto; }
.apc-team__toast button { display: inline-flex; align-items: center; gap: 6px; height: 26px; padding: 0 8px; border-radius: 7px; font-weight: 700; color: oklch(0.85 0.12 160); }
.apc-team__toast button:hover { background: color-mix(in oklch, var(--apc-team-bg) 12%, transparent); }
.apc-team__toast .apc-team__kbd { background: transparent; color: inherit; box-shadow: 0 0 0 1px color-mix(in oklch, var(--apc-team-bg) 30%, transparent); }

@keyframes apc-team-rise { from { opacity: 0; translate: 0 8px; } }
@keyframes apc-team-leave { to { opacity: 0; translate: -10px 0; filter: blur(2px); } }
@keyframes apc-team-pop { from { scale: .4; opacity: 0; } }
@keyframes apc-team-bump { 40% { scale: 1.14; } }
@keyframes apc-team-roll { from { translate: 0 70%; opacity: 0; } }
@keyframes apc-team-dot { 0%, 60%, 100% { translate: 0 0; opacity: .5; } 30% { translate: 0 -4px; opacity: 1; } }
@keyframes apc-team-slide { from { opacity: 0; translate: 24px 0; } }
@keyframes apc-team-flash { 0%, 35% { background: color-mix(in oklch, var(--apc-team-accent) 16%, transparent); } }
@keyframes apc-team-push { from { opacity: 0; translate: 28px 0; } }

/* ---------- responsive ---------- */
@container (width < 960px) {
  .apc-team__app, .apc-team:has(.apc-team__thread[data-open]) .apc-team__app { grid-template-columns: 216px minmax(0, 1fr) 0px; }
  .apc-team__thread {
    grid-area: auto; position: absolute; z-index: 20; top: 0; right: 0; bottom: 0; width: min(372px, 100%);
    box-shadow: -24px 0 50px -30px color-mix(in oklch, var(--apc-team-ink) 50%, transparent);
    translate: 100% 0; visibility: hidden; transition: translate .5s var(--apc-team-out), visibility 0s .5s;
  }
  .apc-team__thread[data-open] { translate: 0 0; visibility: visible; transition: translate .5s var(--apc-team-out), visibility 0s; }
  .apc-team__tin { width: 100%; }
  .apc-team__members b, .apc-team__hint { display: none; }
  .apc-team__bar { justify-content: flex-start; }
}
@container (width < 760px) {
  .apc-team__app, .apc-team:has(.apc-team__thread[data-open]) .apc-team__app { grid-template-columns: minmax(0, 1fr); grid-template-areas: "main"; }
  .apc-team__side, .apc-team__chan { grid-area: main; border: 0; }
  .apc-team[data-view="list"] .apc-team__chan { display: none; }
  .apc-team:not([data-view="list"]) .apc-team__side { display: none; }
  .apc-team[data-view="channel"] .apc-team__chan, .apc-team[data-view="list"] .apc-team__side { animation: apc-team-push .38s var(--apc-team-out); }
  .apc-team__back { display: grid; }
  .apc-team__thread { width: 100%; border: 0; }
  .apc-team__members .apc-team__av:nth-child(n+2) { display: none; }
  .apc-team__head { padding: 8px 14px; gap: 8px; min-height: 54px; }
  .apc-team__msg { padding-inline: 14px; column-gap: 10px; grid-template-columns: 32px minmax(0, 1fr); }
  .apc-team__msg .apc-team__gut .apc-team__av { --s: 32px; }
  .apc-team__new { margin-left: 56px; margin-right: 14px; }
  .apc-team__composer { padding: 0 10px 10px; }
  .apc-team__item { height: 38px; font-size: 15px; }
}
@container (width < 440px) {
  .apc-team__title p { display: none; }
  .apc-team__tools { right: 8px; }
  .apc-team__sfoot span:last-child { display: none; }
}

@media (prefers-reduced-motion: reduce) {
  .apc-team__app { transition: none; }
  .apc-team *, .apc-team *::before, .apc-team *::after {
    animation-duration: .01ms !important; animation-delay: 0s !important; animation-iteration-count: 1 !important;
    transition-duration: .12s !important; transition-timing-function: linear !important;
  }
  .apc-team__dots i { opacity: .7; translate: none; }
}

