    M('theo', 0, '08:15', 'Sent you the deployment map export: 52 buoys, coloured by firmware version.'),
  ] },
];
const SCRIPT = {
  firmware: [['ari', 'Thanks — I’ll hold Thursday and move the OTA to Tuesday 06:00. Two more soak nights on the bench fleet.'], ['lena', 'I can review the PR after lunch. Is `sensor_sleep()` the only change?'], ['ari', 'One line plus a test. B-12 should drop back to about 41 µA tonight.']],
  'field-ops': [['jonas', 'Noted. I’ll radio from the boat once B-17 is aboard.'], ['sana', 'Boots packed. See you at the jetty.']],
  general: [['mei', 'Thanks, Noor — adding it to the Friday notes.'], ['jonas', 'Noted, thanks.']],
  'design-review': [['sana', 'Good call. I’ll fold that into Wednesday’s crit.']],
  'launch-oct': [['mei', 'Added — I’ve put your name next to it in the doc.']],
  'dm-ari': [['ari', 'Perfect, I’ll tag you as the reviewer.'], ['ari', 'Merged. Tuesday OTA it is.']],
  'dm-lena': [['lena', 'Great, thank you!']],
  'dm-theo': [['theo', 'Back at my desk at 14:00 — I’ll reply properly then.']],
};
const THREAD_LINES = ['Got it — thanks for adding that.', 'Makes sense. I’ll update the doc.', 'Agreed, let’s go with that.'];

const S = { ch: 'firmware', newFrom: null, thread: null, edit: null, view: 'channel', fold: { ch: true, dm: true }, script: {}, threadLine: 0, typing: {}, undo: null, sw: null, mention: null, picker: null };

const app = $('.apc-team__app');
const nav = $('.apc-team__nav');
const ol = $('.apc-team__msgs');
const scroller = $('.apc-team__scroll');
const head = $('.apc-team__head');
const thread = $('.apc-team__thread');
const tol = $('.apc-team__tmsgs');
const tscroll = $('.apc-team__tscroll');
const mainForm = $('.apc-team__composer[data-scope="main"]');
const threadForm = $('.apc-team__composer[data-scope="thread"]');
const mainTa = $('textarea', mainForm);
const threadTa = $('textarea', threadForm);
const jumpNew = $('.apc-team__jumpnew');
const mentionEl = $('.apc-team__mention');
const picker = $('.apc-team__picker');
const switcher = $('.apc-team__switcher');
const swInput = $('.apc-team__sfield input');
const swList = $('.apc-team__slist');
const toast = $('.apc-team__toast');
swList.id = `apc-team-${UID}-sl`;
mentionEl.id = `apc-team-${UID}-ml`;
swInput.setAttribute('aria-controls', swList.id);
$$('[data-mod]').forEach((k) => { k.textContent = (MAC ? '⌘' : 'Ctrl ') + k.textContent; });
if (!MAC) $$('[data-alt]').forEach((k) => { k.textContent = k.textContent.replace('⌥', 'Alt'); });
thread.inert = true;

const ch = (id = S.ch) => CH.find((c) => c.id === id);
const later = (fn, ms) => setTimeout(() => { if (root.isConnected) fn(); }, ms);
const narrow = () => root.clientWidth < 760;
const av = (k, extra = '') => {
  const p = P[k];
  if (p.bot) return `<span class="apc-team__av" data-bot ${extra}>${ic('wave')}</span>`;
  return `<span class="apc-team__av" style="--h:${p.h}" ${extra}>${p.ini}</span>`;
};
const chName = (c) => (c.type === 'dm' ? P[c.who].name : c.name);
const chLabel = (c) => (c.type === 'dm' ? P[c.who].name : '#' + c.name);
const mentionsMe = (m) => m.by !== 'me' && /@Noor\b/.test(m.text);
const dayLabel = (d) => (d === 0 ? 'Today' : d === -1 ? 'Yesterday' : 'Earlier');
const ago = (m) => {
  if (m.d < 0) return 'yesterday at ' + hhmm(m.t);
  const diff = nowMin() - m.t;
  return diff < 1 ? 'just now' : diff < 60 ? `${diff} min ago` : 'today at ' + hhmm(m.t);
};

function fmtText(t) {
  return String(t).split(/(`[^`]+`)/).map((part, i) => {
    if (i % 2) return `<code>${esc(part.slice(1, -1))}</code>`;
    return esc(part)
      .replace(/\*([^*\n]+)\*/g, '<b>$1</b>')
      .replace(/@(Noor|Ari|Lena|Theo|Sana|Jonas|Mei)\b/g, (_, n) => `<span class="apc-team__at"${n === 'Noor' ? ' data-me' : ''}>@${n}</span>`);
  }).join('');
}

/* ---------------- sidebar ---------------- */
function renderNav() {
  const item = (c) => {
    const cur = c.id === S.ch;
    const mentions = c.msgs.slice(c.msgs.length - c.unread).filter(mentionsMe).length;
    let badge = '';
    if (c.type === 'dm' && c.unread) badge = `<b class="apc-team__badge">${c.unread}</b>`;
    else if (mentions) badge = `<b class="apc-team__badge">${mentions}</b>`;
    const lead = c.type === 'dm' ? av(c.who, `data-presence="${P[c.who].pres}"`) : ic('hash');
    const label = c.unread ? `${chName(c)}, ${c.unread} unread` : chName(c);
    return `<li><button class="apc-team__item" type="button" data-ch="${c.id}" ${cur ? 'aria-current="page"' : ''} ${c.unread && !cur ? 'data-unread' : ''} aria-label="${esc(label)}">${lead}<span>${esc(chName(c))}</span>${cur ? '' : badge}</button></li>`;
  };
  const sec = (key, title, list) => `<div class="apc-team__sec"><button class="apc-team__sechead" type="button" data-act="fold" data-fold="${key}" aria-expanded="${S.fold[key]}">${ic('chev')}${title}</button><div class="apc-team__fold"><ul>${list.map(item).join('')}</ul></div></div>`;
  nav.innerHTML = sec('ch', 'Channels', CH.filter((c) => c.type === 'ch')) + sec('dm', 'Direct messages', CH.filter((c) => c.type === 'dm'));
}

/* ---------------- messages ---------------- */
function msgHTML(m, cont, scope, i) {
  const p = P[m.by];
  const own = m.by === 'me';
  const reacts = Object.entries(m.rx).filter(([, who]) => who.length).map(([k, who]) => {
    const r = RX[k];
    const names = who.map((w) => (w === 'me' ? 'you' : P[w].first)).join(', ');
    return `<button class="apc-team__react" type="button" data-act="toggle-react" data-k="${k}" aria-pressed="${who.includes('me')}" aria-label="${r.label}: ${esc(names)}" title="${r.label} — ${esc(names)}" style="--c:${r.c}" ${S.bump === m.id + k ? 'data-bump' : ''}>${ic(k)}<b>${who.length}</b></button>`;
  }).join('');
  const addBtn = reacts ? `<button class="apc-team__react apc-team__react--add" type="button" data-act="react" aria-label="Add reaction">${ic('smile')}</button>` : '';
  let replies = '';
  if (scope === 'main' && m.th.length) {
    const who = [...new Set(m.th.map((r) => r.by))].slice(0, 3);
    const last = m.th[m.th.length - 1];
    replies = `<button class="apc-team__replies" type="button" data-act="thread">${who.map((w) => av(w)).join('')}<b>${m.th.length} ${m.th.length === 1 ? 'reply' : 'replies'}</b><span>Last reply ${ago(last)}</span><i>View thread</i></button>`;
  }
  const text = S.edit === m.id
    ? `<div class="apc-team__edit"><textarea aria-label="Edit message">${esc(m.text)}</textarea><p>Enter to save · Esc to cancel</p></div>`
    : `<div class="apc-team__text">${m.also ? '<small>replied to a thread: </small>' : ''}${fmtText(m.text)}${m.edited ? ' <small>(edited)</small>' : ''}</div>`;
  const tools = `<div class="apc-team__tools" role="toolbar" aria-label="Message actions">
    <button type="button" data-act="react" aria-label="Add reaction" title="Add reaction">${ic('smile')}</button>
    ${scope === 'main' ? `<button type="button" data-act="thread" aria-label="Reply in thread" title="Reply in thread">${ic('thread')}</button>` : ''}
    ${own && scope !== 'parent' ? `<button type="button" data-act="edit" aria-label="Edit message" title="Edit">${ic('edit')}</button><button type="button" data-act="delete" aria-label="Delete message" title="Delete">${ic('trash')}</button>` : ''}
  </div>`;
  return `<li class="apc-team__msg" data-id="${m.id}" data-scope="${scope}" ${cont ? 'data-cont' : ''} ${mentionsMe(m) ? 'data-mention' : ''} ${S.fresh === m.id ? 'data-new' : ''} style="--i:${i}">
    <div class="apc-team__gut">${cont ? `<time>${hhmm(m.t)}</time>` : av(m.by)}</div>
    <div class="apc-team__body">
      ${cont ? '' : `<div class="apc-team__meta"><b>${esc(p.name)}</b>${p.bot ? '<span class="apc-team__app-tag">APP</span>' : ''}<time>${hhmm(m.t)}</time></div>`}
      ${text}
      <div class="apc-team__reacts">${reacts}${addBtn}</div>
      ${replies}
    </div>
    ${tools}
  </li>`;
}

function listHTML(msgs, scope, startIdx = 0) {
  let html = '', prev = null;
  const n = msgs.length;
  msgs.forEach((m, idx) => {
    if (scope === 'main' && (!prev || prev.d !== m.d)) { html += `<li class="apc-team__day" style="--i:${Math.max(0, idx - (n - 12))}"><span>${dayLabel(m.d)}</span></li>`; prev = null; }
    if (scope === 'main' && S.newFrom === m.id) { html += `<li class="apc-team__new" style="--i:${Math.max(0, idx - (n - 12))}"><span>New</span></li>`; prev = null; }
    const cont = !!prev && prev.by === m.by && prev.d === m.d && m.t - prev.t < 6 && !prev.th.length && !m.also;
    html += msgHTML(m, cont, scope, Math.max(0, idx + startIdx - (n - 12)));
    prev = m;
  });
  return html;
}

const atBottom = (el) => el.scrollHeight - el.scrollTop - el.clientHeight < 48;
function renderMsgs({ enter = false, stick = true } = {}) {
  const c = ch();
  ol.innerHTML = listHTML(c.msgs, 'main');
  if (enter && !RM.matches) { ol.setAttribute('data-enter', ''); later(() => ol.removeAttribute('data-enter'), 900); }
  if (stick) scroller.scrollTop = scroller.scrollHeight;
  settle();
}

function renderHead() {
  const c = ch();
  const h2 = $('h2', head), p = $('p', head), mem = $('.apc-team__members');
  if (c.type === 'dm') {
    const who = P[c.who];
    h2.innerHTML = esc(who.name);
    p.textContent = `${who.role} · ${who.pres === 'active' ? 'Active now' : who.pres === 'away' ? 'Away' : 'Offline'}`;
    mem.innerHTML = av(c.who, `data-presence="${who.pres}"`);
    mem.setAttribute('aria-label', who.name);
  } else {
    h2.innerHTML = ic('hash') + esc(c.name);
    p.textContent = c.topic;
    mem.innerHTML = c.crew.map((k) => av(k)).join('') + `<b>${c.count}</b>`;
    mem.setAttribute('aria-label', `${c.count} members`);
  }
  mainTa.placeholder = `Message ${chLabel(c)}`;
  $('.apc-team__also b').textContent = chLabel(c);
}

function openChannel(id, { focus = true, initial = false } = {}) {
  const c = ch(id);
  if (!c) return;
  if (S.ch !== id || initial) {
    if (S.thread && S.thread.ch !== id) closeThread(false);
    S.ch = id; S.edit = null;
    S.newFrom = c.unread ? c.msgs[c.msgs.length - c.unread].id : null;
    c.unread = 0;
    renderHead(); renderMsgs({ enter: true }); renderTyping(); renderNav();
    jumpNew.hidden = true;
  }
  if (narrow()) setView('channel');
  if (focus) mainTa.focus({ preventScroll: true });
}
function stepChannel(dir) {
  const i = CH.findIndex((c) => c.id === S.ch);
  openChannel(CH[(i + dir + CH.length) % CH.length].id);
}
function setView(v) { S.view = v; root.dataset.view = v; }

/* ---------------- thread ---------------- */
function renderThread() {
  if (!S.thread) return;
  const c = ch(S.thread.ch);
  const parent = c.msgs.find((m) => m.id === S.thread.id);
  if (!parent) { closeThread(false); return; }
  $('.apc-team__thead small').textContent = chLabel(c);
  const n = parent.th.length;
  tol.innerHTML = msgHTML(parent, false, 'parent', 0)
    + `<li class="apc-team__tcount">${n ? `${n} ${n === 1 ? 'reply' : 'replies'}` : 'No replies yet'}</li>`
    + listHTML(parent.th, 'thread', 0);
  settle();
}
function openThread(id) {
  const opening = !S.thread;
  S.thread = { ch: S.ch, id };
  renderThread();
  thread.setAttribute('data-open', '');
  thread.inert = false;
  threadTa.placeholder = 'Reply…';
  tscroll.scrollTop = tscroll.scrollHeight;
  if (opening && !RM.matches) {
    const tin = $('.apc-team__tin');
    tin.style.animation = 'none'; void tin.offsetWidth; tin.style.animation = '';
  }
  threadTa.focus({ preventScroll: true });
}
function closeThread(restore = true) {
  if (!S.thread) return;
  const id = S.thread.id;
  S.thread = null;
  thread.removeAttribute('data-open');
  thread.inert = true;
  renderTyping();
  if (restore) {
    const btn = $(`.apc-team__msgs [data-id="${id}"] [data-act="thread"]`);
    (btn || mainTa).focus({ preventScroll: true });
  }
}

/* ---------------- typing ---------------- */
function renderTyping() {
  const box = $('.apc-team__typing:not(.apc-team__typing--t)');
  const tbox = $('.apc-team__typing--t');
  const dots = '<span class="apc-team__dots" aria-hidden="true"><i style="--i:0"></i><i style="--i:1"></i><i style="--i:2"></i></span>';
  const who = S.typing[S.ch];
  box.innerHTML = who ? `${dots}<b>${esc(P[who].first)}</b> is typing…` : '';
  const twho = S.thread && S.typing['t:' + S.thread.id];
  tbox.innerHTML = twho ? `${dots}<b>${esc(P[twho].first)}</b> is typing…` : '';
}

/* ---------------- sending ---------------- */
function post(text, scope) {
  const msg = M('me', 0, nowMin(), text);
  if (scope === 'thread' && S.thread) {
    const c = ch(S.thread.ch);
    const parent = c.msgs.find((m) => m.id === S.thread.id);
    parent.th.push(msg);
    S.fresh = msg.id;
    renderThread();
    tscroll.scrollTop = tscroll.scrollHeight;
    if ($('.apc-team__also input').checked) {
      const copy = M('me', 0, nowMin(), text, { also: parent.id });
      c.msgs.push(copy);
      $('.apc-team__also input').checked = false;
    }
    const keep = atBottom(scroller);
    renderMsgs({ stick: keep });
    replyLater(c.id, parent);
  } else {
    const c = ch();
    c.msgs.push(msg);
    S.newFrom = null; S.fresh = msg.id;
    renderMsgs();
    replyLater(c.id);
  }
}

function replyLater(chId, parent) {
  const c = ch(chId);
  let by, text;
  if (parent) {
    const pool = [parent.by, ...parent.th.map((r) => r.by)].filter((k) => k !== 'me' && k !== 'bot');
    if (!pool.length) return;
    by = pool[0];
    text = THREAD_LINES[S.threadLine++ % THREAD_LINES.length];
  } else {
    const list = SCRIPT[chId] || [];
    const i = S.script[chId] || 0;
    if (i >= list.length) return;
    S.script[chId] = i + 1;
    [by, text] = list[i];
  }
  const key = parent ? 't:' + parent.id : chId;
  const typeFor = 1200 + Math.min(2600, text.length * 22);
  later(() => { S.typing[key] = by; renderTyping(); }, 900);
  later(() => {
    delete S.typing[key];
    const msg = M(by, 0, nowMin(), text);
    if (parent) {
      parent.th.push(msg);
      const stick = atBottom(tscroll);
      S.fresh = msg.id;
      refresh(parent.id);
      if (stick && S.thread && S.thread.id === parent.id) tscroll.scrollTop = tscroll.scrollHeight;
    } else {
      c.msgs.push(msg);
      if (S.ch === chId) {
        const stick = atBottom(scroller);
        S.fresh = msg.id; renderMsgs({ stick });
        if (!stick) jumpNew.hidden = false;
      } else {
        c.unread += 1; renderNav();
      }
    }
    renderTyping();
  }, 900 + typeFor);
}

/* Re-render one message (and its thread) in place, and keep keyboard focus where it was. */
function refresh(id) {
  const ae = root.ownerDocument.activeElement;
  const host = ae && ae.closest ? ae.closest('.apc-team__msg') : null;
  const restore = host ? { id: host.dataset.id, scope: host.dataset.scope, act: ae.dataset.act, k: ae.dataset.k } : null;
  const f = findMsg(id);
  if (f && f.c.id === S.ch) {
    const m = f.parent || f.m;
    const live = $(`.apc-team__msgs .apc-team__msg[data-id="${m.id}"]`);
    if (live) {
      const tmp = document.createElement('template');
      tmp.innerHTML = msgHTML(m, live.hasAttribute('data-cont'), 'main', 0).trim();
      live.replaceWith(tmp.content.firstElementChild);
    }
  }
  if (S.thread) renderThread();
  settle();
  if (restore) {
    const el = $(`.apc-team__msg[data-id="${restore.id}"][data-scope="${restore.scope}"]`);
    const target = el && (el.querySelector(`[data-act="${restore.act}"]${restore.k ? `[data-k="${restore.k}"]` : ''}`) || el.querySelector('[data-act="react"]'));
    if (target) target.focus({ preventScroll: true });
  }
}
/* one-shot render flags (entry rise, reaction bump) live for exactly one task */
function settle() { queueMicrotask(() => { S.fresh = null; S.bump = null; }); }

function findMsg(id) {
  for (const c of CH) {
    for (const m of c.msgs) {
      if (m.id === id) return { c, m, list: c.msgs };
      const r = m.th.find((x) => x.id === id);
      if (r) return { c, m: r, list: m.th, parent: m };
    }
  }
  return null;
}

function toggleReact(id, k) {
  const f = findMsg(id);
  if (!f) return;
  const who = f.m.rx[k] || (f.m.rx[k] = []);
  const i = who.indexOf('me');
  if (i >= 0) who.splice(i, 1); else who.push('me');
  S.bump = who.length ? id + k : null;
  refresh(id);
}

/* ---------------- edit / delete / undo ---------------- */
function startEdit(id) {
  S.edit = id;
  const f = findMsg(id);
  if (!f) return;
  refresh(id);
  const ta = $(`.apc-team__msg[data-id="${id}"] .apc-team__edit textarea`);
  if (ta) { ta.focus(); ta.setSelectionRange(ta.value.length, ta.value.length); }
}
function endEdit(save) {
  const id = S.edit;
  if (!id) return;
  const f = findMsg(id);
  const ta = $(`.apc-team__msg[data-id="${id}"] .apc-team__edit textarea`);
  S.edit = null;
  if (f && save && ta) {
    const v = ta.value.trim();
    if (!v) { removeMsg(id); return; }
    if (v !== f.m.text) { f.m.text = v; f.m.edited = true; }
  }
  if (f) refresh(id);
  (f && f.parent ? threadTa : mainTa).focus({ preventScroll: true });
}
function removeMsg(id) {
  const f = findMsg(id);
  if (!f) return;
  const els = $$(`.apc-team__msg[data-id="${id}"]`);
  els.forEach((el) => el.setAttribute('data-leaving', ''));
  later(() => {
    const idx = f.list.indexOf(f.m);
    if (idx < 0) return;
    f.list.splice(idx, 1);
    S.undo = { f, idx };
    if (f.parent) refresh(f.parent.id); else if (f.c.id === S.ch) renderMsgs({ stick: false });
    showToast('Message deleted', true);
  }, RM.matches ? 0 : 300);
}
function undo() {
  if (!S.undo) return;
  const { f, idx } = S.undo;
  S.undo = null;
  f.list.splice(idx, 0, f.m);
  S.fresh = f.m.id;
  if (f.parent) refresh(f.parent.id); else if (f.c.id === S.ch) renderMsgs({ stick: false });
  showToast('Message restored', false);
}
let toastTimer = 0;
function showToast(text, withUndo) {
  toast.innerHTML = `<span>${esc(text)}</span>` + (withUndo ? `<button type="button" data-act="undo">${ic('undo')}Undo <kbd class="apc-team__kbd">${MAC ? '⌘' : 'Ctrl '}Z</kbd></button>` : '');
  toast.setAttribute('data-show', '');
  clearTimeout(toastTimer);
  toastTimer = setTimeout(() => { if (!root.isConnected) return; toast.removeAttribute('data-show'); if (withUndo) S.undo = null; }, withUndo ? 6000 : 1800);
}

/* ---------------- composer ---------------- */
function syncSend(form) {
  $('.apc-team__send', form).disabled = !$('textarea', form).value.trim();
}
function autoGrow(ta) {
  if (CSS.supports('field-sizing', 'content')) return;
  ta.style.height = 'auto';
  ta.style.height = Math.min(150, ta.scrollHeight) + 'px';
}
function wrapSel(ta, a, b = a) {
  const { selectionStart: s, selectionEnd: e, value: v } = ta;
  ta.value = v.slice(0, s) + a + v.slice(s, e) + b + v.slice(e);
  ta.focus();
  ta.setSelectionRange(s + a.length, e + a.length);
  ta.dispatchEvent(new Event('input', { bubbles: true }));
}

[mainForm, threadForm].forEach((form) => {
  const ta = $('textarea', form);
  form.addEventListener('submit', (e) => {
    e.preventDefault();
    const v = ta.value.trim();
    if (!v) return;
    post(v, form.dataset.scope);
    ta.value = '';
    autoGrow(ta); syncSend(form); closeMention();
  });
  ta.addEventListener('input', () => { syncSend(form); autoGrow(ta); updateMention(ta); });
  ta.addEventListener('keydown', (e) => {
    if (S.mention && S.mention.ta === ta) {
      if (e.key === 'ArrowDown' || e.key === 'ArrowUp') { e.preventDefault(); e.stopPropagation(); moveMention(e.key === 'ArrowDown' ? 1 : -1); return; }
      if (e.key === 'Enter' || e.key === 'Tab') { e.preventDefault(); e.stopPropagation(); pickMention(); return; }
      if (e.key === 'Escape') { e.preventDefault(); e.stopPropagation(); closeMention(); return; }
    }
    if (e.key === 'Enter' && !e.shiftKey && !e.isComposing) { e.preventDefault(); form.requestSubmit(); return; }
    if (e.key === 'ArrowUp' && !ta.value) {
      const list = form.dataset.scope === 'thread' && S.thread
        ? ch(S.thread.ch).msgs.find((m) => m.id === S.thread.id).th
        : ch().msgs;
      const mine = [...list].reverse().find((m) => m.by === 'me');
      if (mine) { e.preventDefault(); startEdit(mine.id); }
    }
  });
  ta.addEventListener('blur', () => later(() => { if (S.mention && S.mention.ta === ta && root.ownerDocument.activeElement !== ta) closeMention(); }, 150));
});

/* ---------------- @mention autocomplete ---------------- */
function updateMention(ta) {
  const before = ta.value.slice(0, ta.selectionStart);
  const m = before.match(/(^|\s)@(\w*)$/);
  if (!m) { closeMention(); return; }
  const q = m[2].toLowerCase();
  const list = PEOPLE.filter((k) => P[k].first.toLowerCase().startsWith(q) || P[k].name.toLowerCase().includes(' ' + q));
  if (!list.length) { closeMention(); return; }
  const sel = S.mention && S.mention.ta === ta ? Math.min(S.mention.sel, list.length - 1) : 0;
  S.mention = { ta, q, list, sel, start: before.length - m[2].length - 1 };
  const box = ta.closest('.apc-team__box').getBoundingClientRect();
  const r = root.getBoundingClientRect();
  mentionEl.style.left = Math.max(8, Math.min(box.left - r.left + 8, r.width - 268)) + 'px';
  mentionEl.style.bottom = (r.bottom - box.top + 6) + 'px';
  mentionEl.hidden = false;
  ta.setAttribute('aria-controls', mentionEl.id);
  ta.setAttribute('aria-expanded', 'true');
  renderMention();
}
function renderMention() {
  const { list, sel } = S.mention;
  mentionEl.innerHTML = list.map((k, i) => `<li role="option" id="apc-team-${UID}-mo${i}" data-pick-person="${k}" aria-selected="${i === sel}">${av(k, `data-presence="${P[k].pres}"`)}<span>${esc(P[k].name)}</span><small>${esc(P[k].role)}</small></li>`).join('');
  S.mention.ta.setAttribute('aria-activedescendant', `apc-team-${UID}-mo${sel}`);
}
function moveMention(d) {
  const m = S.mention;
  m.sel = (m.sel + d + m.list.length) % m.list.length;
  renderMention();
}
function pickMention(k) {
  const m = S.mention;
  if (!m) return;
  const who = k || m.list[m.sel];
  const ta = m.ta;
  const end = ta.selectionStart;
  const ins = '@' + P[who].first + ' ';
  ta.value = ta.value.slice(0, m.start) + ins + ta.value.slice(end);
  const pos = m.start + ins.length;
  closeMention();
  ta.focus();
  ta.setSelectionRange(pos, pos);
  syncSend(ta.closest('form'));
}
function closeMention() {
  if (!S.mention) return;
  S.mention.ta.removeAttribute('aria-activedescendant');
  S.mention.ta.setAttribute('aria-expanded', 'false');
  S.mention = null;
  mentionEl.hidden = true;
}
mentionEl.addEventListener('pointerdown', (e) => {
  const li = e.target.closest('[data-pick-person]');
  if (li) { e.preventDefault(); pickMention(li.dataset.pickPerson); }
});

/* ---------------- reaction picker ---------------- */
function openPicker(btn, id) {
  S.picker = { id, btn };
  picker.innerHTML = REACT.map((r) => `<button type="button" role="menuitem" data-pick="${r.k}" aria-label="${r.label}" title="${r.label}" style="--c:${r.c}">${ic(r.k)}</button>`).join('');
  picker.hidden = false;
  const b = btn.getBoundingClientRect(), r = root.getBoundingClientRect();
  const w = picker.offsetWidth, h = picker.offsetHeight;
  let top = b.bottom - r.top + 6;
  if (top + h > r.height - 8) top = b.top - r.top - h - 6;
  picker.style.top = Math.max(8, top) + 'px';
  picker.style.left = Math.max(8, Math.min(b.right - r.left - w, r.width - w - 8)) + 'px';
  picker.querySelector('button').focus();
}
function closePicker(restore = true) {
  if (!S.picker) return;
  const { btn } = S.picker;
  S.picker = null;
  picker.hidden = true;
  if (restore && btn.isConnected) btn.focus({ preventScroll: true });
}
picker.addEventListener('keydown', (e) => {
  const btns = $$('button', picker);
  const i = btns.indexOf(root.ownerDocument.activeElement);
  if (e.key === 'ArrowRight' || e.key === 'ArrowLeft') { e.preventDefault(); btns[(i + (e.key === 'ArrowRight' ? 1 : -1) + btns.length) % btns.length].focus(); }
  if (e.key === 'Home') { e.preventDefault(); btns[0].focus(); }
  if (e.key === 'End') { e.preventDefault(); btns[btns.length - 1].focus(); }
  if (e.key === 'Tab') closePicker(false);
});

/* ---------------- quick switcher ---------------- */
function fuzzy(q, s) {
  if (!q) return { score: 1, html: esc(s) };
  const low = s.toLowerCase();
  let qi = 0, score = 0, last = -2, html = '';
  for (let i = 0; i < s.length; i++) {
    if (qi < q.length && low[i] === q[qi]) {
      score += i === last + 1 ? 3 : 1; if (i === 0) score += 2;
      last = i; qi++; html += `<mark>${esc(s[i])}</mark>`;
    } else html += esc(s[i]);
  }
  return qi === q.length ? { score, html } : null;
}
function openSwitcher() {
  if (S.sw) return;
  closePicker(false); closeMention();
  S.sw = { sel: 0, items: [], ret: root.ownerDocument.activeElement };
  switcher.hidden = false;
  swInput.value = '';
  renderSwitcher();
  swInput.focus();
}
function renderSwitcher() {
  const q = swInput.value.trim().toLowerCase();
  const items = CH.map((c) => ({ c, f: fuzzy(q, chName(c)) })).filter((x) => x.f)
    .sort((a, b) => (q ? b.f.score - a.f.score : (b.c.unread > 0) - (a.c.unread > 0)));
  S.sw.items = items;
  S.sw.sel = Math.min(S.sw.sel, Math.max(0, items.length - 1));
  swList.innerHTML = items.length ? items.map((x, i) => {
    const c = x.c;
    const lead = c.type === 'dm' ? av(c.who, `data-presence="${P[c.who].pres}"`) : ic('hash');
    const meta = c.type === 'dm' ? P[c.who].role : `${c.count} members`;
    return `<li role="option" id="apc-team-${UID}-so${i}" data-sw="${i}" aria-selected="${i === S.sw.sel}" style="--i:${i}">${lead}<span>${x.f.html}</span><small>${c.unread ? `${c.unread} new · ` : ''}${esc(meta)}</small></li>`;
  }).join('') : `<li class="apc-team__none">No channel or person matches “${esc(swInput.value)}”</li>`;
  if (items.length) swInput.setAttribute('aria-activedescendant', `apc-team-${UID}-so${S.sw.sel}`);
