function closeSwitcher(restore = true) {
  if (!S.sw) return;
  const ret = S.sw.ret;
  S.sw = null;
  switcher.hidden = true;
  if (restore && ret && ret.isConnected) ret.focus({ preventScroll: true });
}
function chooseSwitcher(i) {
  const x = S.sw && S.sw.items[i];
  if (!x) return;
  closeSwitcher(false);
  openChannel(x.c.id);
}
swInput.addEventListener('input', () => { S.sw.sel = 0; renderSwitcher(); });
swInput.addEventListener('keydown', (e) => {
  if (e.key === 'ArrowDown' || e.key === 'ArrowUp') {
    e.preventDefault();
    const n = S.sw.items.length; if (!n) return;
    S.sw.sel = (S.sw.sel + (e.key === 'ArrowDown' ? 1 : -1) + n) % n;
    $$('[data-sw]', swList).forEach((li, i) => li.setAttribute('aria-selected', i === S.sw.sel));
    swInput.setAttribute('aria-activedescendant', `apc-team-${UID}-so${S.sw.sel}`);
