  } else if (e.key === 'Enter') { e.preventDefault(); chooseSwitcher(S.sw.sel); }
  else if (e.key === 'Tab') e.preventDefault();
});
switcher.addEventListener('pointerdown', (e) => { if (e.target === switcher) { e.preventDefault(); closeSwitcher(); } });
swList.addEventListener('click', (e) => { const li = e.target.closest('[data-sw]'); if (li) chooseSwitcher(+li.dataset.sw); });

/* ---------------- delegated clicks ---------------- */
root.addEventListener('click', (e) => {
  if (S.picker && !e.target.closest('.apc-team__picker')) {
    const same = e.target.closest('[data-act="react"]') === S.picker.btn;
    closePicker(false);
    if (same) return;
  }
  const chBtn = e.target.closest('[data-ch]');
  if (chBtn) { openChannel(chBtn.dataset.ch); return; }
  const pick = e.target.closest('[data-pick]');
  if (pick && S.picker) {
    const { id } = S.picker;
    closePicker();
    const f = findMsg(id);
    if (f && !(f.m.rx[pick.dataset.pick] || []).includes('me')) toggleReact(id, pick.dataset.pick);
    return;
  }
  const fmt = e.target.closest('[data-fmt]');
  if (fmt) {
    const ta = $('textarea', fmt.closest('form'));
    if (fmt.dataset.fmt === 'bold') wrapSel(ta, '*');
    else if (fmt.dataset.fmt === 'code') wrapSel(ta, '`');
    else { const s = ta.selectionStart; const pre = s && !/\s/.test(ta.value[s - 1]) ? ' @' : '@'; wrapSel(ta, pre, ''); }
    return;
  }
  const act = e.target.closest('[data-act]');
  if (!act) return;
  const li = act.closest('.apc-team__msg');
  const id = li && li.dataset.id;
  switch (act.dataset.act) {
    case 'switcher': openSwitcher(); break;
    case 'fold': {
      const k = act.dataset.fold;
      S.fold[k] = !S.fold[k];
      act.setAttribute('aria-expanded', S.fold[k]);
      break;
    }
    case 'status': {
      const away = P.me.pres === 'active';
      P.me.pres = away ? 'away' : 'active';
      act.setAttribute('aria-pressed', away);
      $('.apc-team__av', act).dataset.presence = P.me.pres;
      $('small', act).textContent = away ? 'Away · on the boat until 15:00' : 'Active · Field lead';
      break;
    }
    case 'to-list': setView('list'); $(`.apc-team__item[data-ch="${S.ch}"]`).focus({ preventScroll: true }); break;
    case 'to-bottom': scroller.scrollTo({ top: scroller.scrollHeight, behavior: RM.matches ? 'auto' : 'smooth' }); jumpNew.hidden = true; break;
    case 'close-thread': closeThread(); break;
    case 'thread': if (id) openThread(id); break;
    case 'react': openPicker(act, id); break;
    case 'toggle-react': toggleReact(id, act.dataset.k); break;
    case 'edit': startEdit(id); break;
    case 'delete': removeMsg(id); break;
    case 'undo': undo(); break;
  }
});

root.addEventListener('keydown', (e) => {
  const mod = e.metaKey || e.ctrlKey;
  const t = e.target;
  if (t.closest && t.closest('.apc-team__edit')) {
    if (e.key === 'Enter' && !e.shiftKey) { e.preventDefault(); endEdit(true); return; }
    if (e.key === 'Escape') { e.preventDefault(); endEdit(false); return; }
  }
  if (mod && e.key.toLowerCase() === 'k') { e.preventDefault(); if (S.sw) closeSwitcher(); else openSwitcher(); return; }
  if (e.altKey && (e.key === 'ArrowUp' || e.key === 'ArrowDown')) { e.preventDefault(); closeSwitcher(false); stepChannel(e.key === 'ArrowUp' ? -1 : 1); return; }
  if (mod && e.key.toLowerCase() === 'z' && S.undo && !(t.tagName === 'TEXTAREA' && t.value)) { e.preventDefault(); undo(); return; }
  if (e.key === 'Escape') {
    if (S.picker) { e.preventDefault(); closePicker(); return; }
    if (S.mention) { e.preventDefault(); closeMention(); return; }
    if (S.sw) { e.preventDefault(); closeSwitcher(); return; }
    if (S.thread) { e.preventDefault(); closeThread(); return; }
    if (narrow() && S.view === 'channel') { e.preventDefault(); setView('list'); }
  }
});

/* stay pinned to the newest message while panes resize or the list re-renders */
let stuck = true;
const ro = new ResizeObserver(() => {
  if (!root.isConnected) { ro.disconnect(); return; }
  if (stuck) scroller.scrollTop = scroller.scrollHeight;
});
ro.observe(scroller); ro.observe(ol);
scroller.addEventListener('scroll', () => {
  stuck = atBottom(scroller);
  if (S.picker) closePicker(false);
  if (!jumpNew.hidden && atBottom(scroller)) jumpNew.hidden = true;
}, { passive: true });
tscroll.addEventListener('scroll', () => { if (S.picker) closePicker(false); }, { passive: true });

/* keep "x min ago" labels honest without re-rendering the whole list */
const clock = setInterval(() => {
  if (!root.isConnected) return clearInterval(clock);
  if (document.hidden) return;
  $$('.apc-team__msgs .apc-team__replies').forEach((b) => {
    const li = b.closest('.apc-team__msg');
    const f = li && findMsg(li.dataset.id);
    if (f && f.m.th.length) $('span', b).textContent = 'Last reply ' + ago(f.m.th[f.m.th.length - 1]);
  });
}, 30000);

openChannel('firmware', { focus: false, initial: true });

css:
/* Direct messages. Re-theme with --apc-dm-bg, -ink, -accent (your bubbles) and -read (receipts). */
.apc-dm {
  --apc-dm-bg: oklch(0.172 0.009 62);
  --apc-dm-ink: oklch(0.945 0.012 78);
  --apc-dm-accent: oklch(0.55 0.135 38);
  --apc-dm-read: oklch(0.87 0.12 172);

  --apc-dm-panel: color-mix(in oklch, var(--apc-dm-ink) 3.5%, var(--apc-dm-bg));
  --apc-dm-raise: color-mix(in oklch, var(--apc-dm-ink) 9%, var(--apc-dm-bg));
  --apc-dm-raise2: color-mix(in oklch, var(--apc-dm-ink) 14%, var(--apc-dm-bg));
  --apc-dm-line: color-mix(in oklch, var(--apc-dm-ink) 9%, transparent);
  --apc-dm-line2: color-mix(in oklch, var(--apc-dm-ink) 16%, transparent);
  --apc-dm-muted: color-mix(in oklch, var(--apc-dm-ink) 62%, var(--apc-dm-bg));
  --apc-dm-faint: color-mix(in oklch, var(--apc-dm-ink) 40%, var(--apc-dm-bg));
  --apc-dm-on: oklch(0.985 0.01 60);
  --apc-dm-glow: color-mix(in oklch, var(--apc-dm-accent) 40%, transparent);
  --apc-dm-live: oklch(0.79 0.16 150);
  --apc-dm-ease: cubic-bezier(.2, .8, .2, 1);
  --apc-dm-out: cubic-bezier(.3, .75, 0, 1);
  --apc-dm-spring: linear(0, 0.08 2.6%, 0.3 6.4%, 0.7 13%, 0.95 19.5%, 1.07 26%, 1.1 31%, 1.07 38%, 1.02 48%, 0.995 62%, 1);

  position: relative;
  isolation: isolate;
  width: 100%;
  height: var(--apc-dm-h, 680px);
  container-type: inline-size;
  overflow: hidden;
  overflow: clip;
  border-radius: 18px;
  background: var(--apc-dm-bg);
  color: var(--apc-dm-ink);
  font: 400 14.5px/1.45 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  -webkit-font-smoothing: antialiased;
  color-scheme: dark;
  accent-color: var(--apc-dm-accent);
  box-shadow: inset 0 0 0 1px var(--apc-dm-line);
}
:where(.apc-dm) *, :where(.apc-dm) *::before, :where(.apc-dm) *::after { box-sizing: border-box; }
:where(.apc-dm) :is(button, input, textarea) { font: inherit; color: inherit; }
:where(.apc-dm) button { background: none; border: 0; padding: 0; cursor: pointer; }
:where(.apc-dm) :is(ol, ul) { list-style: none; margin: 0; padding: 0; }
:where(.apc-dm) :is(h2, h3, p) { margin: 0; }
:where(.apc-dm) svg { width: 20px; height: 20px; fill: none; stroke: currentColor; stroke-width: 1.75; stroke-linecap: round; stroke-linejoin: round; flex: none; }
:where(.apc-dm) :focus-visible { outline: 2px solid var(--apc-dm-read); outline-offset: 2px; }
.apc-dm [hidden] { display: none !important; }
.apc-dm__kbd {
  display: inline-grid; place-items: center; min-width: 18px; height: 18px; padding: 0 4px; border-radius: 5px;
  font: 600 10.5px/1 ui-monospace, Menlo, monospace; color: var(--apc-dm-muted); background: var(--apc-dm-raise);
  box-shadow: inset 0 -1px 0 color-mix(in oklch, black 40%, transparent), 0 0 0 1px var(--apc-dm-line2);
}
.apc-dm__sr { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }

.apc-dm__app { display: grid; height: 100%; grid-template-columns: minmax(280px, 330px) minmax(0, 1fr); grid-template-areas: "inbox chat"; }
.apc-dm__inbox { grid-area: inbox; }
.apc-dm__chat { grid-area: chat; }

/* avatars */
.apc-dm__av {
  --s: 44px; position: relative; display: inline-grid; place-items: center; width: var(--s); height: var(--s); flex: none; border-radius: 50%;
  font-size: calc(var(--s) * .34); font-weight: 700; letter-spacing: .02em;
  color: oklch(0.93 0.04 var(--h)); background: linear-gradient(150deg, oklch(0.52 0.11 var(--h)), oklch(0.38 0.09 calc(var(--h) + 30)));
}
.apc-dm__av[data-on]::after { content: ""; position: absolute; right: 0; bottom: 0; width: 28%; height: 28%; border-radius: 50%; background: var(--apc-dm-live); box-shadow: 0 0 0 2.5px var(--apc-dm-panel); }
.apc-dm__group { --s: 44px; position: relative; width: var(--s); height: var(--s); flex: none; }
.apc-dm__group .apc-dm__av { --s: 30px; position: absolute; box-shadow: 0 0 0 2.5px var(--apc-dm-panel); }
.apc-dm__group .apc-dm__av:first-child { left: 0; top: 0; }
.apc-dm__group .apc-dm__av:last-child { right: 0; bottom: 0; }
.apc-dm__me .apc-dm__av { --s: 32px; }

/* ---------- inbox ---------- */
.apc-dm__inbox { display: grid; grid-template-columns: minmax(0, 1fr); grid-template-rows: auto auto minmax(0, 1fr); min-height: 0; background: var(--apc-dm-panel); border-right: 1px solid var(--apc-dm-line); }
.apc-dm__ihead { display: flex; align-items: center; justify-content: space-between; padding: 18px 18px 10px; }
.apc-dm__ihead h2 { font-size: clamp(20px, 2.1cqi, 24px); font-weight: 780; letter-spacing: -0.03em; }
.apc-dm__search {
  display: flex; align-items: center; gap: 8px; margin: 0 14px 10px; height: 38px; padding: 0 8px 0 12px; border-radius: 11px;
  background: var(--apc-dm-raise); color: var(--apc-dm-faint); transition: box-shadow .2s;
}
.apc-dm__search:focus-within { box-shadow: 0 0 0 1.5px var(--apc-dm-read); color: var(--apc-dm-ink); }
.apc-dm__search svg { width: 16px; height: 16px; }
.apc-dm__search input { flex: 1; min-width: 0; height: 100%; border: 0; outline: none; background: none; font-size: 14px; }
.apc-dm__search input::placeholder { color: var(--apc-dm-faint); }
.apc-dm__search input::-webkit-search-cancel-button { display: none; }
.apc-dm__search:focus-within .apc-dm__kbd { display: none; }
.apc-dm__convos { overflow: auto; padding: 2px 8px 12px; scrollbar-width: thin; overscroll-behavior: contain; outline: none; }
.apc-dm__convo {
  position: relative; display: grid; grid-template-columns: auto minmax(0, 1fr) auto; grid-template-rows: auto auto; column-gap: 12px; row-gap: 2px; align-items: center;
  padding: 10px 10px; border-radius: 14px; cursor: pointer; transition: background-color .18s; outline: none;
}
.apc-dm__convos[data-enter] .apc-dm__convo { animation: apc-dm-in .4s var(--apc-dm-out) both; animation-delay: calc(var(--i) * 30ms); }
.apc-dm__convo:focus-visible { box-shadow: inset 0 0 0 1.5px var(--apc-dm-read); }
.apc-dm__convo > :first-child { grid-row: span 2; }
.apc-dm__convo:hover { background: color-mix(in oklch, var(--apc-dm-ink) 4%, transparent); }
.apc-dm__convo[aria-selected="true"] { background: var(--apc-dm-raise); }
.apc-dm__cname { display: flex; align-items: center; gap: 6px; min-width: 0; font-weight: 620; font-size: 14.5px; }
.apc-dm__cname span { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.apc-dm__cname svg { width: 13px; height: 13px; color: var(--apc-dm-faint); }
.apc-dm__ctime { font-size: 12px; color: var(--apc-dm-faint); font-variant-numeric: tabular-nums; justify-self: end; }
.apc-dm__cprev { display: flex; align-items: center; gap: 4px; min-width: 0; font-size: 13.5px; color: var(--apc-dm-muted); }
.apc-dm__cprev span { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.apc-dm__cprev em { font-style: normal; color: var(--apc-dm-read); }
.apc-dm__cprev .apc-dm__ticks { width: 18px; height: 12px; }
.apc-dm__cprev mark, .apc-dm__cname mark { background: color-mix(in oklch, var(--apc-dm-read) 26%, transparent); color: inherit; border-radius: 3px; }
.apc-dm__unread { justify-self: end; min-width: 20px; height: 20px; padding: 0 6px; border-radius: 10px; display: grid; place-items: center; font-size: 11.5px; font-weight: 750; font-variant-numeric: tabular-nums; color: var(--apc-dm-on); background: var(--apc-dm-accent); animation: apc-dm-pop .5s var(--apc-dm-spring) both; }
.apc-dm__convo[data-unread] .apc-dm__cname { font-weight: 760; }
.apc-dm__convo[data-unread] .apc-dm__cprev { color: var(--apc-dm-ink); }
.apc-dm__convo[data-unread] .apc-dm__ctime { color: var(--apc-dm-accent); font-weight: 650; }
.apc-dm__empty { padding: 30px 16px; text-align: center; color: var(--apc-dm-faint); font-size: 13.5px; text-wrap: balance; }

/* ---------- chat ---------- */
.apc-dm__chat { position: relative; display: grid; grid-template-columns: minmax(0, 1fr); grid-template-rows: auto minmax(0, 1fr) auto; min-width: 0; min-height: 0; }
.apc-dm__chead { display: flex; align-items: center; gap: 10px; min-height: 66px; padding: 10px 14px 10px 18px; border-bottom: 1px solid var(--apc-dm-line); }
.apc-dm__who { display: flex; align-items: center; gap: 12px; min-width: 0; flex: 1; }
.apc-dm__who .apc-dm__av, .apc-dm__who .apc-dm__group { --s: 40px; }
.apc-dm__who .apc-dm__group .apc-dm__av { --s: 27px; box-shadow: 0 0 0 2.5px var(--apc-dm-bg); }
.apc-dm__who .apc-dm__av[data-on]::after { box-shadow: 0 0 0 2.5px var(--apc-dm-bg); }
.apc-dm__who div { min-width: 0; display: grid; }
.apc-dm__who b { font-size: 15.5px; font-weight: 720; letter-spacing: -0.015em; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.apc-dm__who small { font-size: 12.5px; color: var(--apc-dm-faint); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
