  if (i < 0) return esc(text);
  const start = Math.max(0, i - 18);
  return (start ? '…' : '') + esc(text.slice(start, i)) + `<mark>${esc(text.slice(i, i + q.length))}</mark>` + esc(text.slice(i + q.length));
