  const rxKeys = Object.keys(m.rx).filter((k) => m.rx[k].length);
  const rxCount = rxKeys.reduce((a, k) => a + m.rx[k].length, 0);
  const rx = rxKeys.length ? `<span class="apc-dm__rx" title="${rxKeys.map((k) => `${TAP[k].label}: ${m.rx[k].map((w) => (w === 'me' ? 'you' : P[w].first)).join(', ')}`).join(' · ')}">${rxKeys.slice(0, 3).map((k) => `<span style="--c:${TAP[k].c}">${ic(k)}</span>`).join('')}${rxCount > 1 ? rxCount : ''}</span>` : '';
  const showName = c.group && !own && (pos === 'first' || pos === 'single');
  const label = `${own ? 'You' : p.first}, ${hhmm(m.t)}: ${visibleText(m)}`;
  return `<li class="apc-dm__row" data-n="${m.n}" data-pos="${pos}" ${own ? 'data-own' : ''} ${rx ? 'data-rx' : ''} ${m.gone ? 'data-gone' : ''} ${S.fresh === m.n ? 'data-new' : ''}>
