function renderStream() {
  const c = cur();
  let html = '', lastDay = null;
  c.msgs.forEach((m, i) => {
    const d = dayOf(m.t);
    if (d !== lastDay) { html += `<li class="apc-dm__day">${dayLabel(d)}</li>`; lastDay = d; }
    const prev = c.msgs[i - 1], next = c.msgs[i + 1];
    const joinPrev = prev && prev.by === m.by && dayOf(prev.t) === d && m.t - prev.t <= 5;
    const joinNext = next && next.by === m.by && dayOf(next.t) === d && next.t - m.t <= 5;
    html += rowHTML(c, m, joinPrev ? (joinNext ? 'mid' : 'last') : (joinNext ? 'first' : 'single'));
  });
  if (S.typing[c.id]) html += typingHTML(S.typing[c.id]);
  stream.innerHTML = html;
  S.fresh = null;
  renderSeen(false);
