/* Read receipts: the avatars sit under the newest message each person has seen.
   When a pointer moves they FLIP from their old slot to the new one. */
function renderSeen(animate = true) {
  const c = cur();
  const before = new Map();
  if (animate) $$('.apc-dm__seen [data-p]', stream).forEach((el) => before.set(el.dataset.p, el.getBoundingClientRect()));
  $$('.apc-dm__seen', stream).forEach((s) => { s.innerHTML = ''; });
  const lm = last(c.msgs);
  if (c.group) {
    c.with.forEach((p) => {
      const rn = readN(c, p);
      const m = [...c.msgs].reverse().find((x) => x.n <= rn);
      if (!m || m.by === p && m === lm) return;
      const slot = $(`.apc-dm__row[data-n="${m.n}"] .apc-dm__seen`, stream);
      if (slot) slot.insertAdjacentHTML('beforeend', av(p, `data-p="${p}" title="Seen by ${esc(P[p].first)} ${longWhen(timeOf(c.st[p].reads, m.n) ?? m.t)}"`));
    });
  } else if (lm.by === 'me' && !lm.gone) {
    const p = c.with[0];
    const slot = $(`.apc-dm__row[data-n="${lm.n}"] .apc-dm__seen`, stream);
    const st = stateOf(c, lm);
    const label = st === 'read' ? `<b>Read</b>&nbsp;${hhmm(timeOf(c.st[p].reads, lm.n))}` : st === 'delivered' ? 'Delivered' : st === 'sending' ? 'Sending…' : 'Sent';
    if (slot) slot.innerHTML = `<span ${animate ? 'data-fresh' : ''}>${label}</span>`;
  }
  stick();
  if (!animate || RM.matches) return;
  $$('.apc-dm__seen [data-p]', stream).forEach((el) => {
    const o = before.get(el.dataset.p);
    const n = el.getBoundingClientRect();
    if (o) {
      const dx = o.left - n.left, dy = o.top - n.top;
      if (Math.abs(dx) + Math.abs(dy) > 0.5) el.animate([{ transform: `translate(${dx}px, ${dy}px)` }, { transform: 'none' }], { duration: 620, easing: SPRING });
    } else {
      el.animate([{ transform: 'scale(0)', opacity: 0 }, { transform: 'none', opacity: 1 }], { duration: 450, easing: SPRING });
    }
