}
function patchTicks(c) {
  c.msgs.forEach((m) => {
    if (m.by !== 'me' || m.gone) return;
    const t = $(`.apc-dm__row[data-n="${m.n}"] .apc-dm__ticks`, stream);
    if (t) t.dataset.state = stateOf(c, m);
  });
}
function refresh(c, seenAnim = true) {
  if (c.id === S.cur) { patchTicks(c); renderSeen(seenAnim); renderHead(); }
  renderInbox();
}

/* ---------------- delivery simulation ---------------- */
function deliver(c, p, n) {
  const u = c.st[p];
  if (dlvN(c, p) >= n) return;
  u.dlvs.push([n, now()]);
  refresh(c, false);
}
function read(c, p, n) {
  const u = c.st[p];
  if (readN(c, p) >= n) return;
  u.reads.push([n, now()]);
  refresh(c);
  if (c.id === S.cur && c.group) sr.textContent = `Seen by ${P[p].first}`;
}
function wake(c, p) {
  P[p].on = true;
  const top = last(c.msgs).n;
  CV.forEach((x) => { if (x.with.includes(p)) deliver(x, p, last(x.msgs).n); });
  later(() => read(c, p, top), 900);
}
function setTyping(c, p) {
  if (p) S.typing[c.id] = p; else delete S.typing[c.id];
  if (c.id === S.cur) {
    const el = $('.apc-dm__typing', stream);
    if (p && !el) { stream.insertAdjacentHTML('beforeend', typingHTML(p)); stick(); }
    if (!p && el) el.remove();
    renderHead();
  }
  renderInbox();
}
function incoming(c, p, text) {
  setTyping(c, null);
  const m = msg(p, now(), text);
  c.msgs.push(m);
  c.st[p].reads.push([m.n, m.t]);
  if (c.id === S.cur) {
    S.fresh = m.n;
    const keep = pinned;
    renderStream();
    if (!keep) pinned = false;
    sr.textContent = `${P[p].first}: ${text}`;
  } else {
    c.unread += 1;
  }
  renderInbox();
}

function send(text) {
  const c = cur();
  const m = msg('me', now(), text, { pending: true });
  if (S.reply) { m.reply = S.reply; setReply(null); }
  c.msgs.push(m);
  S.fresh = m.n;
  renderStream();
  renderInbox();
  later(() => { m.pending = false; refresh(c, false); }, 420);
  let lastRead = 0;
  c.with.forEach((p, i) => {
    if (!P[p].on) return;
    later(() => deliver(c, p, m.n), 900 + i * 120);
    const at = 1700 + i * 1100 + Math.round(Math.random() * 500);
    lastRead = Math.max(lastRead, at);
    later(() => read(c, p, m.n), at);
  });
  const step = c.script.shift();
  if (!step) return;
  if (step.wake && !P[step.wake].on) {
    later(() => wake(c, step.wake), step.at);
    lastRead = Math.max(lastRead, step.at + 900);
  }
  const by = step.by;
  later(() => setTyping(c, by), lastRead + 700);
  later(() => incoming(c, by, step.text), lastRead + 700 + Math.min(3400, 1200 + step.text.length * 28));
}

/* ---------------- open / switch ---------------- */
function openConvo(id, { focus = 'composer' } = {}) {
  const c = byId(id);
  if (!c) return;
  const changed = S.cur !== id;
  S.cur = id;
  c.unread = 0;
  if (changed) { setReply(null); closeMenu(false); }
  renderHead();
  renderStream();
  renderInbox();
  if (root.clientWidth < 760) setView('chat');
  if (focus === 'composer') ta.focus({ preventScroll: true });
}
function stepConvo(dir) {
  const order = $$('.apc-dm__convo').map((li) => li.dataset.id);
  if (!order.length) return;
  const i = order.indexOf(S.cur);
  openConvo(order[(i + dir + order.length) % order.length]);
}
function setView(v) { S.view = v; root.dataset.view = v; }

/* ---------------- reply ---------------- */
function setReply(n) {
  S.reply = n;
  if (!n) { replying.hidden = true; replying.innerHTML = ''; return; }
  const m = findMsg(cur(), n);
  replying.innerHTML = `<div><b>Replying to ${m.by === 'me' ? 'yourself' : esc(P[m.by].first)}</b><span>${esc(visibleText(m))}</span></div><button type="button" data-act="cancel-reply" aria-label="Cancel reply">${ic('close')}</button>`;
  replying.hidden = false;
  ta.focus({ preventScroll: true });
}

/* ---------------- swipe to reply + long press ---------------- */
let drag = null;
const THRESH = 58;
stream.addEventListener('pointerdown', (e) => {
  const bub = e.target.closest('.apc-dm__bubble');
  const row = bub && bub.closest('.apc-dm__row');
  if (!row || row.classList.contains('apc-dm__typing') || e.button !== 0 || e.target.closest('.apc-dm__quote')) return;
  drag = { x: e.clientX, y: e.clientY, row, bub, id: e.pointerId, active: false, armed: false, own: row.hasAttribute('data-own') };
  drag.press = later(() => { if (drag && !drag.active) { const d = drag; drag = null; openMenu(+d.row.dataset.n, { x: d.x, y: d.y }); } }, 520);
});
stream.addEventListener('pointermove', (e) => {
  if (!drag || e.pointerId !== drag.id) return;
  const dx = e.clientX - drag.x, dy = e.clientY - drag.y;
  if (!drag.active) {
