  const mag = Math.abs(raw);
  const eased = mag < THRESH ? mag : THRESH + (mag - THRESH) * 0.25;
  drag.row.style.setProperty('--dx', (drag.own ? -eased : eased) + 'px');
  drag.row.style.setProperty('--p', Math.min(1, eased / THRESH).toFixed(3));
  const armed = eased >= THRESH;
  if (armed !== drag.armed) { drag.armed = armed; drag.row.toggleAttribute('data-armed', armed); }
});
const endDrag = (e) => {
