  clearTimeout(drag.press);
  const d = drag; drag = null;
  if (!d.active) return;
  d.row.removeAttribute('data-swiping');
  d.row.removeAttribute('data-armed');
  d.row.style.setProperty('--dx', '0px');
  d.row.style.setProperty('--p', '0');
  if (d.armed) setReply(+d.row.dataset.n);
};
stream.addEventListener('pointerup', endDrag);
stream.addEventListener('pointercancel', endDrag);
stream.addEventListener('contextmenu', (e) => {
  const row = e.target.closest('.apc-dm__row[data-n]');
  if (!row) return;
  e.preventDefault();
  if (drag) { clearTimeout(drag.press); drag = null; }
  openMenu(+row.dataset.n, { x: e.clientX, y: e.clientY });
});

/* ---------------- message menu ---------------- */
function openMenu(n, at) {
  const c = cur();
  const m = findMsg(c, n);
  if (!m) return;
  const own = m.by === 'me';
  S.menu = { n };
  menu.innerHTML = (m.gone ? '' : `<div class="apc-dm__taps" role="group" aria-label="React">${TAPS.map((t, i) => `<button type="button" role="menuitemcheckbox" aria-checked="${(m.rx[t.k] || []).includes('me')}" data-tap="${t.k}" aria-label="${t.label}" title="${t.label}" style="--c:${t.c};--i:${i}">${ic(t.k)}</button>`).join('')}</div>`)
    + (m.gone ? '' : `<button class="apc-dm__mi" type="button" role="menuitem" data-act="m-reply">${ic('reply')}Reply<kbd class="apc-dm__kbd">R</kbd></button>`)
    + (m.gone ? '' : `<button class="apc-dm__mi" type="button" role="menuitem" data-act="m-copy">${ic('copy')}Copy text<kbd class="apc-dm__kbd">C</kbd></button>`)
    + (own ? `<button class="apc-dm__mi" type="button" role="menuitem" data-act="m-info">${ic('info')}Message info<kbd class="apc-dm__kbd">I</kbd></button>` : '')
    + (own && !m.gone ? `<button class="apc-dm__mi" type="button" role="menuitem" data-act="m-unsend" data-danger>${ic('unsend')}Unsend</button>` : '');
  if (!menu.innerHTML) { S.menu = null; return; }
  menu.hidden = false;
  const r = root.getBoundingClientRect();
  const bub = $(`.apc-dm__row[data-n="${n}"] .apc-dm__bubble`, stream);
  const br = bub.getBoundingClientRect();
  const pt = at || { x: own ? br.right : br.left, y: br.bottom };
  const w = menu.offsetWidth, h = menu.offsetHeight;
  let x = pt.x - r.left - (own ? w : 0), y = pt.y - r.top + 6;
  if (y + h > r.height - 8) y = Math.max(8, pt.y - r.top - h - 6);
  x = Math.max(8, Math.min(x, r.width - w - 8));
  menu.style.left = x + 'px'; menu.style.top = y + 'px';
  menu.style.setProperty('--ox', own ? '100%' : '0%');
  menu.style.setProperty('--oy', y < pt.y - r.top ? '100%' : '0%');
