}
function closeMenu(restore = true) {
  if (!S.menu) return;
  const { n } = S.menu;
  S.menu = null;
  menu.hidden = true;
  if (restore) focusBubble(n);
}
menu.addEventListener('keydown', (e) => {
  const items = $$('button', menu);
  const i = items.indexOf(root.ownerDocument.activeElement);
  const taps = $$('[data-tap]', menu);
  const inTaps = taps.includes(items[i]);
  if (e.key === 'ArrowDown') { e.preventDefault(); const mi = $$('.apc-dm__mi', menu); const j = inTaps ? 0 : mi.indexOf(items[i]) + 1; (mi[j] || mi[0]).focus(); }
  else if (e.key === 'ArrowUp') { e.preventDefault(); const mi = $$('.apc-dm__mi', menu); const j = mi.indexOf(items[i]); if (j <= 0 && taps.length) taps[0].focus(); else (mi[j - 1] || mi[mi.length - 1]).focus(); }
  else if ((e.key === 'ArrowRight' || e.key === 'ArrowLeft') && inTaps) { e.preventDefault(); const j = taps.indexOf(items[i]); taps[(j + (e.key === 'ArrowRight' ? 1 : -1) + taps.length) % taps.length].focus(); }
