    if (b) { e.preventDefault(); b.click(); }
  }
});
function react(n, k) {
  const m = findMsg(cur(), n);
  const list = m.rx[k] || (m.rx[k] = []);
  const i = list.indexOf('me');
  if (i >= 0) list.splice(i, 1); else {
    Object.keys(m.rx).forEach((key) => { const j = m.rx[key].indexOf('me'); if (j >= 0) m.rx[key].splice(j, 1); });
    m.rx[k].push('me');
  }
  const ae = root.ownerDocument.activeElement;
  renderStream();
  if (ae && !ae.isConnected) focusBubble(n);
  if (S.drawer) renderDrawer();
}
function unsend(n) {
  const c = cur();
  const m = findMsg(c, n);
  m.gone = true;
  S.undo = { c, n };
  renderStream(); renderInbox();
  showToast('Message unsent', true);
}
function undoUnsend() {
  if (!S.undo) return;
  const { c, n } = S.undo;
  S.undo = null;
  const m = findMsg(c, n);
  if (m) m.gone = false;
  if (c.id === S.cur) { S.fresh = n; renderStream(); }
  renderInbox();
  showToast('Message restored', false);
}
let toastTimer = 0;
function showToast(text, undo) {
  toast.innerHTML = `<span>${esc(text)}</span>${undo ? '<button type="button" data-act="undo">Undo</button>' : ''}`;
  toast.setAttribute('data-show', '');
  clearTimeout(toastTimer);
  toastTimer = setTimeout(() => { if (!root.isConnected) return; toast.removeAttribute('data-show'); if (undo) S.undo = null; }, undo ? 5000 : 1600);
}

/* ---------------- message info sheet ---------------- */
function openSheet(n) {
  const c = cur();
  const m = findMsg(c, n);
  S.sheet = { n };
  const rows = c.with.map((p) => {
    const rt = timeOf(c.st[p].reads, n);
    const dt = timeOf(c.st[p].dlvs, n) ?? rt;
    const state = rt != null ? 'read' : dt != null ? 'delivered' : 'sent';
    const text = rt != null ? `Read ${longWhen(rt)}` : dt != null ? `Delivered ${longWhen(dt)}` : 'Not delivered yet';
    return `<div class="apc-dm__receipt">${av(p)}<span>${esc(P[p].name)}</span><small>${ticks(state)}${text}</small></div>`;
  }).join('');
  sheet.innerHTML = `<div class="apc-dm__sbox"><header><b>Message info</b><button class="apc-dm__iconbtn" type="button" data-act="sheet-close" aria-label="Close">${ic('close')}</button></header>
    <ol>${rowHTML(c, m, 'single').replace('tabindex="-1"', '')}</ol>${rows}</div>`;
  sheet.hidden = false;
  $('[data-act="sheet-close"]', sheet).focus();
}
function closeSheet() {
  if (!S.sheet) return;
  const { n } = S.sheet;
  S.sheet = null;
  sheet.hidden = true;
  focusBubble(n);
}

/* ---------------- roving focus over bubbles ---------------- */
const bubbles = () => $$('.apc-dm__row[data-n] > .apc-dm__col > .apc-dm__bubble', stream);
function rovingReset() {
  const all = bubbles();
  all.forEach((b, i) => b.setAttribute('tabindex', i === all.length - 1 ? '0' : '-1'));
}
function focusBubble(n) {
  const b = $(`.apc-dm__row[data-n="${n}"] > .apc-dm__col > .apc-dm__bubble`, stream);
  if (!b) return;
  bubbles().forEach((x) => x.setAttribute('tabindex', x === b ? '0' : '-1'));
  b.focus({ preventScroll: false });
}
stream.addEventListener('keydown', (e) => {
  const b = e.target.closest('.apc-dm__bubble');
  if (!b || e.target !== b) return;
  const all = bubbles();
  const i = all.indexOf(b);
  const n = +b.closest('.apc-dm__row').dataset.n;
  const go = (j) => { const t = all[Math.max(0, Math.min(all.length - 1, j))]; if (t) focusBubble(+t.closest('.apc-dm__row').dataset.n); };
  if (e.key === 'ArrowUp') { e.preventDefault(); go(i - 1); }
  else if (e.key === 'ArrowDown') { e.preventDefault(); go(i + 1); }
  else if (e.key === 'Home') { e.preventDefault(); go(0); }
  else if (e.key === 'End') { e.preventDefault(); go(all.length - 1); }
  else if (e.key === 'Enter' || e.key === 'ContextMenu' || (e.shiftKey && e.key === 'F10')) { e.preventDefault(); openMenu(n); }
  else if ((e.key === 'r' || e.key === 'R') && !e.metaKey && !e.ctrlKey) { e.preventDefault(); if (!findMsg(cur(), n).gone) setReply(n); }
});

/* ---------------- inbox keyboard ---------------- */
inboxList.addEventListener('keydown', (e) => {
  const li = e.target.closest('.apc-dm__convo');
  if (!li) return;
  const all = $$('.apc-dm__convo');
  const i = all.indexOf(li);
  const move = (j) => { const t = all[(j + all.length) % all.length]; all.forEach((x) => x.setAttribute('tabindex', x === t ? '0' : '-1')); t.focus(); };
  if (e.key === 'ArrowDown') { e.preventDefault(); move(i + 1); }
  else if (e.key === 'ArrowUp') { e.preventDefault(); move(i - 1); }
  else if (e.key === 'Home') { e.preventDefault(); move(0); }
  else if (e.key === 'End') { e.preventDefault(); move(all.length - 1); }
  else if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); openConvo(li.dataset.id); }
});

/* ---------------- composer ---------------- */
form.addEventListener('submit', (e) => {
  e.preventDefault();
  const v = ta.value.trim();
  if (!v) return;
  send(v);
  ta.value = '';
  sendBtn.disabled = true;
  if (!CSS.supports('field-sizing', 'content')) ta.style.height = '';
});
ta.addEventListener('input', () => {
  sendBtn.disabled = !ta.value.trim();
  if (!CSS.supports('field-sizing', 'content')) { ta.style.height = 'auto'; ta.style.height = Math.min(140, ta.scrollHeight) + 'px'; }
});
ta.addEventListener('keydown', (e) => {
  if (e.key === 'Enter' && !e.shiftKey && !e.isComposing) { e.preventDefault(); form.requestSubmit(); }
  else if (e.key === 'ArrowUp' && !ta.value) { const all = bubbles(); if (all.length) { e.preventDefault(); focusBubble(+last(all).closest('.apc-dm__row').dataset.n); } }
});
search.addEventListener('input', () => { S.q = search.value; renderInbox(); });
search.addEventListener('keydown', (e) => {
  if (e.key === 'ArrowDown') { e.preventDefault(); const f = $('.apc-dm__convo'); if (f) { $$('.apc-dm__convo').forEach((x) => x.setAttribute('tabindex', x === f ? '0' : '-1')); f.focus(); } }
  if (e.key === 'Escape' && search.value) { e.preventDefault(); e.stopPropagation(); search.value = ''; S.q = ''; renderInbox(); }
});

/* ---------------- delegated clicks ---------------- */
root.addEventListener('click', (e) => {
  if (S.menu && !e.target.closest('.apc-dm__menu')) closeMenu(false);
  const convo = e.target.closest('.apc-dm__convo');
  if (convo) { openConvo(convo.dataset.id); return; }
  const tap = e.target.closest('[data-tap]');
  if (tap && S.menu) { const { n } = S.menu; closeMenu(false); react(n, tap.dataset.tap); return; }
  if (e.target === sheet) { closeSheet(); return; }
  const act = e.target.closest('[data-act]');
  if (!act) return;
  const n = S.menu && S.menu.n;
  switch (act.dataset.act) {
    case 'back': setView('list'); { const li = $(`.apc-dm__convo[data-id="${S.cur}"]`); if (li) li.focus({ preventScroll: true }); } break;
    case 'info': toggleDrawer(); break;
    case 'info-close': toggleDrawer(false); infoBtn.focus(); break;
    case 'mute': cur().muted = act.checked; renderInbox(); break;
    case 'pin': cur().pinned = act.checked; renderInbox(); break;
    case 'cancel-reply': setReply(null); ta.focus(); break;
    case 'jump': {
      const row = $(`.apc-dm__row[data-n="${act.dataset.n}"]`, stream);
      if (row) {
        row.scrollIntoView({ block: 'center', behavior: RM.matches ? 'auto' : 'smooth' });
        row.removeAttribute('data-flash'); void row.offsetWidth; row.setAttribute('data-flash', '');
      }
      break;
    }
    case 'm-reply': closeMenu(false); setReply(n); break;
    case 'm-copy': {
      closeMenu();
      const m = findMsg(cur(), n);
      try { navigator.clipboard.writeText(m.text).then(() => showToast('Copied', false), () => showToast('Copy blocked by the browser', false)); }
      catch (err) { showToast('Copy blocked by the browser', false); }
      break;
    }
    case 'm-info': closeMenu(false); openSheet(n); break;
    case 'm-unsend': closeMenu(false); unsend(n); break;
    case 'sheet-close': closeSheet(); break;
    case 'undo': undoUnsend(); break;
  }
});

root.addEventListener('keydown', (e) => {
  const t = e.target;
  const typing = t.tagName === 'TEXTAREA' || t.tagName === 'INPUT';
  if (e.altKey && (e.key === 'ArrowUp' || e.key === 'ArrowDown')) { e.preventDefault(); stepConvo(e.key === 'ArrowUp' ? -1 : 1); return; }
  if (e.key === '/' && !typing) { e.preventDefault(); if (root.clientWidth < 760) setView('list'); search.focus(); return; }
  if ((e.metaKey || e.ctrlKey) && e.key.toLowerCase() === 'z' && S.undo && !(typing && t.value)) { e.preventDefault(); undoUnsend(); return; }
  if (e.key === 'Escape') {
    if (S.menu) { e.preventDefault(); closeMenu(); return; }
    if (S.sheet) { e.preventDefault(); closeSheet(); return; }
    if (S.drawer) { e.preventDefault(); toggleDrawer(false); infoBtn.focus(); return; }
    if (S.reply) { e.preventDefault(); setReply(null); return; }
    if (root.clientWidth < 760 && S.view === 'chat') { e.preventDefault(); setView('list'); const li = $(`.apc-dm__convo[data-id="${S.cur}"]`); if (li) li.focus(); }
  }
});

const ro = new ResizeObserver(() => {
  if (!root.isConnected) { ro.disconnect(); return; }
  stick();
});
ro.observe(scroller);

renderHead();
renderStream();
renderInbox(true);

