/* Assistant chat. Re-theme with --apc-assist-bg, -ink and -accent (and -h for height). */
@property --apc-assist-sweep { syntax: "<percentage>"; inherits: false; initial-value: -30%; }

.apc-assist {
  --apc-assist-bg: oklch(0.984 0.005 85);
  --apc-assist-ink: oklch(0.235 0.014 55);
  --apc-assist-accent: oklch(0.55 0.175 358);

  --apc-assist-side: color-mix(in oklch, var(--apc-assist-ink) 3.5%, var(--apc-assist-bg));
  --apc-assist-card: color-mix(in oklch, white 70%, var(--apc-assist-bg));
  --apc-assist-line: color-mix(in oklch, var(--apc-assist-ink) 10%, transparent);
  --apc-assist-line2: color-mix(in oklch, var(--apc-assist-ink) 17%, transparent);
  --apc-assist-muted: color-mix(in oklch, var(--apc-assist-ink) 64%, var(--apc-assist-bg));
  --apc-assist-faint: color-mix(in oklch, var(--apc-assist-ink) 43%, var(--apc-assist-bg));
  --apc-assist-hover: color-mix(in oklch, var(--apc-assist-ink) 5%, transparent);
  --apc-assist-tint: color-mix(in oklab, var(--apc-assist-accent) 8%, var(--apc-assist-bg));
  --apc-assist-deep: color-mix(in oklab, var(--apc-assist-accent) 82%, var(--apc-assist-ink));
