/* ---------------- Markdown → ops ----------------
   The answer is compiled once into a flat list of operations (open a block, open a list
   item, a table row or cell, emit a word, emit a code token). Streaming is just applying
   the next few operations to the live DOM, so partial lists and tables are always valid. */
const KW = new Set('SELECT FROM WHERE AND OR GROUP BY HAVING ORDER ASC DESC COUNT SUM ROUND FILTER AS WITH DATE INTERVAL JOIN ON LEFT CASE WHEN THEN ELSE END'.split(' '));
function compile(md) {
  const ops = [];
  const lines = md.split('\n');
  const words = (s, fmt) => s.split(/(?<=\s)/).forEach((w) => { if (w) ops.push({ k: 'text', s: w, fmt }); });
  const inline = (s) => s.split(/(\*\*[^*]+\*\*|`[^`]+`)/).forEach((p) => {
    if (!p) return;
