    else if (p.startsWith('`') && p.endsWith('`') && p.length > 2) ops.push({ k: 'text', s: p.slice(1, -1), fmt: 'code' });
    else words(p, null);
  });
  const isNum = (c) => /\d/.test(c) && /^[\d.,%€\s–-]+$/.test(c.replace(/\*\*/g, ''));
  let i = 0;
  while (i < lines.length) {
    const L = lines[i];
    if (!L.trim()) { i++; continue; }
    if (L.startsWith('```')) {
      ops.push({ k: 'block', tag: 'pre', lang: L.slice(3).trim() || 'text' });
      i++;
      while (i < lines.length && !lines[i].startsWith('```')) {
        ops.push({ k: 'nl' });
        const line = lines[i];
        if (line.trim().startsWith('--')) ops.push({ k: 'code', s: line, cls: 'com' });
        else line.split(/(\s+)/).forEach((t) => {
          if (!t) return;
          const w = t.match(/^[A-Z_]+/);
          const cls = /'/.test(t) ? 'str' : (w && KW.has(w[0])) ? 'kw' : /^\(?\d/.test(t) ? 'num' : '';
          ops.push({ k: 'code', s: t, cls });
        });
        i++;
      }
      i++;
      continue;
    }
    if (/^#{1,3} /.test(L)) { ops.push({ k: 'block', tag: 'h3' }); inline(L.replace(/^#+ /, '')); i++; continue; }
    const listRe = /^[-*] /.test(L) ? /^[-*] / : /^\d+\. /.test(L) ? /^\d+\. / : null;
    if (listRe) {
      ops.push({ k: 'block', tag: listRe.source.includes('d') ? 'ol' : 'ul' });
      while (i < lines.length && listRe.test(lines[i])) { ops.push({ k: 'item' }); inline(lines[i].replace(listRe, '')); i++; }
      continue;
    }
    if (L.startsWith('|')) {
      const rows = [];
      while (i < lines.length && lines[i].startsWith('|')) {
        if (!/^\|[\s|:-]+\|$/.test(lines[i])) rows.push(lines[i].slice(1, -1).split('|').map((c) => c.trim()));
        i++;
      }
      const body = rows.slice(1);
      const numCol = rows[0].map((_, j) => body.every((r) => isNum(r[j] || '')));
      ops.push({ k: 'block', tag: 'table' });
      rows.forEach((r, ri) => {
        ops.push({ k: 'row', head: ri === 0, total: /^\*\*total\*\*$/i.test(r[0]) });
        r.forEach((c, j) => { ops.push({ k: 'cell', num: numCol[j] }); inline(c); });
      });
      continue;
    }
    ops.push({ k: 'block', tag: 'p' });
    let first = true;
    while (i < lines.length && lines[i].trim() && !/^(```|#{1,3} |[-*] |\d+\. |\|)/.test(lines[i])) {
