/* Applies ops to a message body. `anim` marks each new word so it sharpens in from blur. */
class Builder {
  constructor(body, anim) { this.body = body; this.anim = anim; this.target = null; this.caret = null; }
  el(tag, cls) { const e = document.createElement(tag); if (cls) e.className = cls; return e; }
  apply(op) {
    const B = this;
    switch (op.k) {
      case 'block': {
        B.row = B.cell = B.line = null;
        if (op.tag === 'table') {
          const wrap = B.el('div', 'apc-assist__tablewrap');
          const t = B.el('table');
          B.thead = B.el('thead'); B.tbody = B.el('tbody');
          t.append(B.thead, B.tbody); wrap.append(t); B.body.append(wrap);
          B.target = null;
        } else if (op.tag === 'pre') {
          const card = B.el('div', 'apc-assist__code');
          card.innerHTML = `<header><span>${esc(op.lang)}</span><button type="button" data-act="copy-code">${ic('copy')}Copy</button></header>`;
          B.pre = B.el('pre');
          card.append(B.pre); B.body.append(card);
          B.target = null;
        } else {
          B.blk = B.el(op.tag);
          B.body.append(B.blk);
          B.target = op.tag === 'ul' || op.tag === 'ol' ? null : B.blk;
        }
        break;
      }
      case 'item': B.target = B.el('li'); B.blk.append(B.target); break;
      case 'row': B.row = B.el('tr'); B.rowHead = op.head; if (op.total) B.row.dataset.total = ''; (op.head ? B.thead : B.tbody).append(B.row); break;
      case 'cell': B.target = B.el(B.rowHead ? 'th' : 'td'); if (op.num) B.target.dataset.num = ''; B.row.append(B.target); break;
      case 'br': if (B.target) B.target.append(B.el('br')); break;
      case 'nl': B.line = B.el('span', 'apc-assist__ln'); B.pre.append(B.line); break;
      case 'code': {
        if (!B.line) break;
        if (!op.cls && !B.anim) { B.line.append(op.s); break; }
        const s = B.el('span', [op.cls ? 'apc-assist__' + op.cls : '', B.anim ? 'apc-assist__tok' : ''].join(' ').trim());
        s.textContent = op.s; B.line.append(s);
        break;
      }
      case 'text': {
        if (!B.target) break;
        if (!op.fmt && !B.anim) { B.target.append(op.s); break; }
        const s = B.el(op.fmt === 'b' ? 'b' : op.fmt === 'code' ? 'code' : 'span', B.anim ? 'apc-assist__tok' : '');
        s.textContent = op.s; B.target.append(s);
        break;
      }
    }
  }
  placeCaret() {
    if (!this.caret) { this.caret = this.el('span', 'apc-assist__caret'); this.caret.setAttribute('aria-hidden', 'true'); }
    const host = this.line || this.target || this.body;
    host.append(this.caret);
  }
  dropCaret() { if (this.caret) this.caret.remove(); }
}

/* ---------------- conversation tree ---------------- */
const nodes = new Map();
let nid = 0;
function node(role, extra = {}, parent = null) {
  const n = { id: 'n' + (++nid), role, parent, kids: [], act: 0, ...extra };
  nodes.set(n.id, n);
  if (parent) { const p = nodes.get(parent); p.kids.push(n.id); p.act = p.kids.length - 1; }
  return n;
}
const pickAnswer = (q) => ANSWERS.find((a) => a.re.test(q)) || FALLBACK;
function asstNode(parent, q, variant, extra = {}) {
  const a = pickAnswer(q);
  const text = a.v[variant % a.v.length];
  return node('assistant', { text, ops: compile(text), shown: 0, status: 'thinking', think: a.think, model: 'swift', ...extra }, parent);
}
function doneAsst(parent, q, variant, model, ms, think) {
  const n = asstNode(parent, q, variant, { model, ms, status: 'done', thinkMs: MODELS.find((m) => m.id === model).think });
  n.shown = n.ops.length;
  if (think) n.think = think;
  return n;
}
let cid = 0;
function chat(title, day, exchanges = []) {
  const r = node('root');
  const c = { id: 'c' + (++cid), title, day, root: r.id };
  let at = r.id;
  exchanges.forEach(([q, variants, act]) => {
    const u = node('user', { text: q }, at);
    variants.forEach(([v, model, ms, think]) => doneAsst(u.id, q, v, model, ms, think));
    if (act != null) u.act = act;
    at = u.kids[u.act];
  });
  return c;
}
const FUEL = `Here is a Q4 table with a **€1.62/L base** and **1% surcharge for every €0.05 above it**:

| Diesel price (€/L) | Surcharge |
|---|---|
| up to 1.66 | 0% |
| 1.67 – 1.71 | 1% |
| 1.72 – 1.76 | 2% |
| 1.77 – 1.81 | 3% |
| 1.82 – 1.86 | 4% |

At this week’s average of €1.74/L, loads carry a **2%** surcharge.`;
const ONBOARD = `### Owner-operator onboarding

1. Signed haulage agreement and rate card
2. Operator licence and vehicle registration
3. Goods-in-transit insurance certificate (minimum €150,000)
4. Tachograph card and the last 28 days of records
5. App account for proof-of-delivery photos
6. A shadow run on a short regional lane before solo work`;
const HS = `For the parts we ship most, the heading is **8714** — parts and accessories for bicycles:

- \`8714.91\` frames and forks
- \`8714.92\` wheel rims and spokes
- \`8714.94\` brakes and their parts
- \`8714.96\` pedals and crank-gears

Spain is inside the EU customs union with us, so these codes matter for the Intrastat return, not for duties.`;
const CHATS = [
  chat('Late shipments by carrier', 'Today', [['Summarize last week’s late shipments by carrier', [[0, 'swift', 3100], [1, 'deep', 6800]], 1]]),
  chat('Fuel surcharge table for Q4', 'Yesterday'),
  chat('Owner-operator onboarding', 'Previous 7 days'),
  chat('HS codes for bike parts to Spain', 'Previous 7 days'),
];
/* the three older chats hold one finished answer each */
[[1, 'Build a fuel surcharge table for Q4 using a €1.62/L base.', FUEL, ['Reading 4 rate cards', 'Read 4 rate cards']],
 [2, 'Checklist for onboarding a new owner-operator', ONBOARD, ['Reading the carrier handbook', 'Read the carrier handbook']],
 [3, 'Which HS codes do we use for bike parts to Spain?', HS, ['Checking 312 customs declarations', 'Checked 312 customs declarations']]].forEach(([i, q, text, think]) => {
  const u = node('user', { text: q }, CHATS[i].root);
  const a = node('assistant', { text, ops: compile(text), status: 'done', think, model: 'swift', ms: 2400 + i * 700 }, u.id);
  a.shown = a.ops.length;
});

const S = { chat: CHATS[0].id, model: 'swift', live: null, editing: null, q: '', visible: true, side: false };

const col = $('.apc-assist__col');
const scroller = $('.apc-assist__scroll');
const history = $('.apc-assist__history');
const find = $('.apc-assist__find input');
const form = $('.apc-assist__composer');
const ta = $('textarea', form);
const sendBtn = $('.apc-assist__send');
const titleEl = $('.apc-assist__title');
const modelBtn = $('.apc-assist__modelbtn');
const modelMenu = $('.apc-assist__models');
const downBtn = $('.apc-assist__down');
const toast = $('.apc-assist__toast');

const later = (fn, ms) => setTimeout(() => { if (root.isConnected) fn(); }, ms);
const curChat = () => CHATS.find((c) => c.id === S.chat);
function pathOf(c) {
  const out = [];
  let n = nodes.get(c.root);
  while (n.kids.length) { n = nodes.get(n.kids[n.act]); out.push(n); }
  return out;
}
const modelOf = (id) => MODELS.find((m) => m.id === id);
const secs = (ms) => (ms / 1000).toFixed(1) + ' s';

/* ---------------- rendering ---------------- */
function verNav(n) {
  const p = nodes.get(n.parent);
  if (!p || p.kids.length < 2) return '';
  const i = p.kids.indexOf(n.id);
  const busy = !!S.live;
  return `<div class="apc-assist__ver" role="group" aria-label="Versions"><button type="button" data-act="ver" data-dir="-1" data-id="${n.id}" aria-label="Previous version" ${i === 0 || busy ? 'disabled' : ''}>${ic('left')}</button><span aria-live="polite">${i + 1} / ${p.kids.length}</span><button type="button" data-act="ver" data-dir="1" data-id="${n.id}" aria-label="Next version" ${i === p.kids.length - 1 || busy ? 'disabled' : ''}>${ic('right')}</button></div>`;
}
function userHTML(n) {
  if (S.editing === n.id) {
    return `<div class="apc-assist__q" data-id="${n.id}"><div class="apc-assist__edit"><textarea aria-label="Edit message">${esc(n.text)}</textarea><div><span>Saving starts a new branch</span><button class="apc-assist__btn" type="button" data-act="edit-cancel">Cancel</button><button class="apc-assist__btn" type="button" data-act="edit-save" data-primary>Send</button></div></div></div>`;
  }
  return `<div class="apc-assist__q" data-id="${n.id}"><div class="apc-assist__bubble">${esc(n.text)}</div><div class="apc-assist__qtools">${verNav(n)}<button class="apc-assist__tool" type="button" data-act="edit" aria-label="Edit message" title="Edit">${ic('edit')}</button><button class="apc-assist__tool" type="button" data-act="copy" aria-label="Copy message" title="Copy">${ic('copy')}</button></div></div>`;
}
function actsHTML(n, isLast) {
  const m = modelOf(n.model);
  const stopped = n.status === 'stopped' ? '<span class="apc-assist__stopped">Stopped</span>' : '';
  const follow = isLast && n.status !== 'thinking' && n.status !== 'streaming' ? followHTML() : '';
  return `${stopped}${verNav(n)}
    <button class="apc-assist__tool" type="button" data-act="copy" aria-label="Copy answer" title="Copy">${ic('copy')}</button>
    <button class="apc-assist__tool" type="button" data-act="regen" aria-label="Regenerate" title="Regenerate" ${S.live ? 'disabled' : ''}>${ic('regen')}</button>
    <button class="apc-assist__tool" type="button" data-act="rate" data-v="up" aria-pressed="${n.rate === 'up'}" aria-label="Good answer" title="Good answer">${ic('up')}</button>
    <button class="apc-assist__tool" type="button" data-act="rate" data-v="down" aria-pressed="${n.rate === 'down'}" aria-label="Bad answer" title="Bad answer">${ic('up', 'style="rotate:180deg"')}</button>
    <span class="apc-assist__meta">${esc(m.name)}${n.ms ? ' · ' + secs(n.ms) : ''}</span>${follow}`;
}
function followHTML() {
  const asked = new Set(pathOf(curChat()).filter((n) => n.role === 'user').map((n) => n.text));
  const list = FOLLOW.filter((f) => !asked.has(f)).slice(0, 2);
  if (!list.length) return '';
  return `<div class="apc-assist__follow">${list.map((f, i) => `<button type="button" data-act="ask" data-q="${esc(f)}" style="--i:${i}">${ic('arrow')}<span>${esc(f)}</span></button>`).join('')}</div>`;
}
function asstHTML(n, isLast) {
  const label = n.status === 'thinking' ? n.think[0] + '…' : `${n.think[1]}${n.thinkMs ? ' · ' + secs(n.thinkMs) : ''}`;
  return `<article class="apc-assist__a" data-id="${n.id}" data-state="${n.status}" aria-busy="${n.status === 'thinking' || n.status === 'streaming'}">
    <span class="apc-assist__mark" aria-hidden="true">${ic('mark')}</span>
    <div class="apc-assist__think">${ic('spark')}<span>${esc(label)}</span></div>
    <div class="apc-assist__body"></div>
    <div class="apc-assist__acts">${actsHTML(n, isLast)}</div>
  </article>`;
}
function helloHTML() {
  return `<div class="apc-assist__hello"><h3>Good afternoon, Priya.<br><em>What are we moving today?</em></h3><p>Ask about carriers, lanes and late loads, or have Wren draft a note with the latest figures.</p>
    <div class="apc-assist__ideas">${IDEAS.map((x, i) => `<button class="apc-assist__idea" type="button" data-act="ask" data-q="${esc(x.text)}" style="--i:${i}">${ic(x.icon)}<span>${esc(x.text)}</span><small>${esc(x.sub)}</small></button>`).join('')}</div></div>`;
}
let live = null;
function renderThread({ stick = true } = {}) {
  const c = curChat();
  const path = pathOf(c);
  titleEl.textContent = c.title;
  if (!path.length) { col.innerHTML = helloHTML(); return; }
  const lastA = [...path].reverse().find((n) => n.role === 'assistant');
  col.innerHTML = path.map((n) => (n.role === 'user' ? userHTML(n) : asstHTML(n, n === lastA))).join('');
  live = null;
  path.forEach((n) => {
    if (n.role !== 'assistant') return;
    const body = $(`.apc-assist__a[data-id="${n.id}"] .apc-assist__body`, col);
    const b = new Builder(body, false);
    for (let i = 0; i < n.shown; i++) b.apply(n.ops[i]);
    if (n.id === S.live) { b.anim = !RM.matches; live = { node: n, b, el: body.closest('.apc-assist__a') }; if (n.status === 'streaming') b.placeCaret(); }
  });
  if (S.editing) {
    const t = $('.apc-assist__edit textarea', col);
    if (t) { t.focus(); t.setSelectionRange(t.value.length, t.value.length); }
  }
  if (stick) toBottom();
}
function patchActs(n) {
  const el = $(`.apc-assist__a[data-id="${n.id}"]`, col);
  if (!el) return;
  el.dataset.state = n.status;
  el.setAttribute('aria-busy', 'false');
  el.setAttribute('data-fresh', '');
  $('.apc-assist__think span', el).textContent = `${n.think[1]}${n.thinkMs ? ' · ' + secs(n.thinkMs) : ''}`;
  const path = pathOf(curChat());
  const lastA = [...path].reverse().find((x) => x.role === 'assistant');
  $('.apc-assist__acts', el).innerHTML = actsHTML(n, n === lastA);
  $$('.apc-assist__ver button', col).forEach((b) => {
    const t = nodes.get(b.dataset.id); const p = t && nodes.get(t.parent);
    if (!p) return;
    const i = p.kids.indexOf(t.id);
    b.disabled = b.dataset.dir === '-1' ? i === 0 : i === p.kids.length - 1;
  });
  $$('[data-act="regen"]', col).forEach((b) => { b.disabled = false; });
}

function renderHistory() {
  const q = S.q.trim().toLowerCase();
  const groups = ['Today', 'Yesterday', 'Previous 7 days'];
  let html = '';
  groups.forEach((g) => {
    const list = CHATS.filter((c) => c.day === g && (!q || c.title.toLowerCase().includes(q)));
    if (!list.length) return;
    html += `<h3>${g}</h3><ul>${list.map((c) => {
      let t = esc(c.title);
      if (q) { const i = c.title.toLowerCase().indexOf(q); t = esc(c.title.slice(0, i)) + `<mark>${esc(c.title.slice(i, i + q.length))}</mark>` + esc(c.title.slice(i + q.length)); }
      return `<li><button class="apc-assist__chat" type="button" data-chat="${c.id}" ${c.id === S.chat ? 'aria-current="page"' : ''}>${t}</button></li>`;
    }).join('')}</ul>`;
  });
  history.innerHTML = html || `<p class="apc-assist__none">No chats match “${esc(S.q)}”.</p>`;
}
function renderModel() {
  const m = modelOf(S.model);
  $('span', modelBtn).innerHTML = `${esc(m.name.replace('Wren ', ''))}<small>${S.model === 'swift' ? 'fast' : 'thorough'}</small>`;
  modelMenu.innerHTML = MODELS.map((x) => `<button class="apc-assist__opt" type="button" role="menuitemradio" aria-checked="${x.id === S.model}" data-model="${x.id}"><b>${esc(x.name)}</b>${ic('check')}<small>${esc(x.desc)}</small></button>`).join('');
}

/* ---------------- scrolling ---------------- */
let pinned = true;
const nearBottom = () => scroller.scrollHeight - scroller.scrollTop - scroller.clientHeight < 60;
function toBottom(smooth) {
  scroller.scrollTo({ top: scroller.scrollHeight, behavior: smooth && !RM.matches ? 'smooth' : 'auto' });
  pinned = true; downBtn.hidden = true;
}
scroller.addEventListener('scroll', () => { pinned = nearBottom(); downBtn.hidden = pinned; }, { passive: true });
const ro = new ResizeObserver(() => {
  if (!root.isConnected) { ro.disconnect(); return; }
  if (pinned) scroller.scrollTop = scroller.scrollHeight;
});
ro.observe(col);

/* ---------------- streaming ---------------- */
let raf = 0, lastT = 0, acc = 0;
function setBusy(on) {
  root.toggleAttribute('data-busy', on);
  sendBtn.setAttribute('aria-label', on ? 'Stop generating' : 'Send');
  sendBtn.disabled = on ? false : !ta.value.trim();
}
function startStream(n) {
  n.model = S.model;
  n.status = 'thinking';
  n.started = performance.now();
  n.thinkLeft = modelOf(S.model).think;
  S.live = n.id;
  setBusy(true);
  renderThread();
  ta.focus({ preventScroll: true });
  kick();
}
function kick() { if (!raf && S.live && S.visible) { lastT = performance.now(); raf = requestAnimationFrame(pump); } }
function pump(t) {
  if (!root.isConnected) return;
  raf = 0;
  if (!live || !S.live || !S.visible) return;
  const n = live.node;
  const dt = Math.min(120, t - lastT);
  lastT = t;
  const m = modelOf(n.model);
  if (n.status === 'thinking') {
    n.thinkLeft -= dt;
    if (n.thinkLeft <= 0) {
      n.status = 'streaming';
      n.thinkMs = m.think;
      live.el.dataset.state = 'streaming';
      $('.apc-assist__think span', live.el).textContent = n.think[1] + ' · ' + secs(m.think);
      acc = m.every;
    }
  } else {
    acc += dt;
    const per = RM.matches ? m.rate * 6 : m.rate;
    while (acc >= m.every && n.shown < n.ops.length) {
      acc -= m.every;
      let k = 0;
      while (n.shown < n.ops.length && k < per) {
        const op = n.ops[n.shown++];
        live.b.apply(op);
        if (isToken(op)) k++;
      }
    }
    live.b.placeCaret();
    if (pinned) scroller.scrollTop = scroller.scrollHeight;
    if (n.shown >= n.ops.length) { finish('done'); return; }
  }
  raf = requestAnimationFrame(pump);
}
function finish(status) {
  const n = S.live && nodes.get(S.live);
  if (!n) return;
  if (raf) { cancelAnimationFrame(raf); raf = 0; }
  n.status = status;
  n.ms = Math.round(performance.now() - n.started);
  if (live) live.b.dropCaret();
  S.live = null;
  setBusy(false);
  patchActs(n);
  live = null;
  if (status === 'stopped') ta.focus({ preventScroll: true });
}

const io = new IntersectionObserver((entries) => {
  if (!root.isConnected) { io.disconnect(); return; }
  S.visible = entries[entries.length - 1].isIntersecting;
  if (S.visible) kick();
});
io.observe(root);

/* ---------------- actions ---------------- */
function ask(text) {
  const c = curChat();
  if (S.live) return;
  const path = pathOf(c);
  const parent = path.length ? path[path.length - 1].id : c.root;
  if (!path.length) {
    c.title = text.length > 42 ? text.slice(0, 40).trim() + '…' : text;
    renderHistory();
  }
  const u = node('user', { text }, parent);
  const a = asstNode(u.id, text, 0);
  startStream(a);
}
function regen(aId) {
  if (S.live) return;
  const a = nodes.get(aId);
  const u = nodes.get(a.parent);
  const n = asstNode(u.id, u.text, u.kids.length);
  startStream(n);
}
function branchEdit(uId, text) {
  const u = nodes.get(uId);
  S.editing = null;
  if (!text.trim() || text.trim() === u.text) { renderThread({ stick: false }); return; }
  const v = node('user', { text: text.trim() }, u.parent);
  const a = asstNode(v.id, v.text, 0);
  startStream(a);
}
function switchVer(id, dir) {
  if (S.live) return;
  const n = nodes.get(id);
  const p = nodes.get(n.parent);
  const i = p.kids.indexOf(id) + dir;
  if (i < 0 || i >= p.kids.length) return;
  p.act = i;
  const el = $(`[data-id="${id}"]`, col);
  const top = el ? el.getBoundingClientRect().top : 0;
  renderThread({ stick: false });
  const now = $(`[data-id="${p.kids[i]}"]`, col);
  if (now) {
    scroller.scrollTop += now.getBoundingClientRect().top - top;
    const btn = $(`[data-act="ver"][data-dir="${dir}"]`, now) || $('[data-act="ver"]', now);
    if (btn && !btn.disabled) btn.focus({ preventScroll: true }); else { const other = $('[data-act="ver"]:not(:disabled)', now); if (other) other.focus({ preventScroll: true }); }
    if (!RM.matches) now.animate([{ opacity: 0.35, filter: 'blur(3px)' }, { opacity: 1, filter: 'blur(0)' }], { duration: 380, easing: 'cubic-bezier(.2,.75,.2,1)' });
  }
}
function openChat(id) {
  if (S.live) finish('stopped');
  S.chat = id; S.editing = null;
  renderHistory(); renderThread();
  setSide(false);
  ta.focus({ preventScroll: true });
}
function newChat() {
  const blank = CHATS.find((c) => c.day === 'Today' && !pathOf(c).length);
  if (blank) { openChat(blank.id); return; }
  const c = chat('New chat', 'Today');
  CHATS.unshift(c);
  openChat(c.id);
}
function copy(text) {
  try { navigator.clipboard.writeText(text).then(() => say('Copied'), () => say('Copy blocked by the browser')); }
  catch (e) { say('Copy blocked by the browser'); }
}
let toastT = 0;
function say(text) {
  toast.textContent = text;
  toast.setAttribute('data-show', '');
  clearTimeout(toastT);
  toastT = setTimeout(() => { if (root.isConnected) toast.removeAttribute('data-show'); }, 1400);
}
function setSide(open) {
  S.side = open;
  root.dataset.side = open ? 'open' : 'closed';
  if (open) { const cur = $('.apc-assist__chat[aria-current="page"]') || find; cur.focus({ preventScroll: true }); }
}
function openModels(open) {
  modelMenu.hidden = !open;
  modelBtn.setAttribute('aria-expanded', open);
  if (open) ($('[aria-checked="true"]', modelMenu) || $('button', modelMenu)).focus();
}

/* ---------------- events ---------------- */
form.addEventListener('submit', (e) => {
  e.preventDefault();
  if (S.live) { finish('stopped'); return; }
  const v = ta.value.trim();
  if (!v) return;
  ta.value = '';
  sendBtn.disabled = true;
  ask(v);
});
ta.addEventListener('input', () => { if (!S.live) sendBtn.disabled = !ta.value.trim(); });
ta.addEventListener('keydown', (e) => {
  if (e.key === 'Enter' && !e.shiftKey && !e.isComposing) { e.preventDefault(); if (!S.live) form.requestSubmit(); }
  else if (e.key === 'ArrowUp' && !ta.value && !S.live) {
    const lastU = [...pathOf(curChat())].reverse().find((n) => n.role === 'user');
    if (lastU) { e.preventDefault(); S.editing = lastU.id; renderThread({ stick: false }); $(`[data-id="${lastU.id}"]`, col).scrollIntoView({ block: 'nearest' }); }
  }
});
find.addEventListener('input', () => { S.q = find.value; renderHistory(); });

root.addEventListener('click', (e) => {
  if (!modelMenu.hidden && !e.target.closest('.apc-assist__model')) openModels(false);
  const chatBtn = e.target.closest('[data-chat]');
  if (chatBtn) { openChat(chatBtn.dataset.chat); return; }
  const opt = e.target.closest('[data-model]');
  if (opt) { S.model = opt.dataset.model; renderModel(); openModels(false); modelBtn.focus(); say(`${modelOf(S.model).name} selected`); return; }
  const act = e.target.closest('[data-act]');
  if (!act) return;
  const host = act.closest('[data-id]');
  const id = host && host.dataset.id;
  switch (act.dataset.act) {
    case 'new': newChat(); break;
    case 'side-open': setSide(true); break;
    case 'side-close': setSide(false); break;
    case 'model': openModels(modelMenu.hidden); break;
    case 'down': toBottom(true); break;
    case 'ask': if (!S.live) ask(act.dataset.q); break;
    case 'edit': if (!S.live) { S.editing = id; renderThread({ stick: false }); } break;
    case 'edit-cancel': S.editing = null; renderThread({ stick: false }); break;
    case 'edit-save': branchEdit(id, $('.apc-assist__edit textarea', col).value); break;
    case 'copy': copy(nodes.get(id).text); break;
    case 'copy-code': copy($$('.apc-assist__ln', act.closest('.apc-assist__code')).map((l) => l.textContent).join('\n')); break;
    case 'regen': regen(id); break;
    case 'ver': switchVer(act.dataset.id, +act.dataset.dir); break;
    case 'rate': {
      const n = nodes.get(id);
      n.rate = n.rate === act.dataset.v ? null : act.dataset.v;
      $$('[data-act="rate"]', host).forEach((b) => b.setAttribute('aria-pressed', n.rate === b.dataset.v));
      if (n.rate) say(n.rate === 'up' ? 'Thanks — noted as helpful' : 'Thanks — we’ll use this to improve Wren');
      break;
    }
  }
});

root.addEventListener('keydown', (e) => {
  const t = e.target;
  if (e.altKey && e.code === 'KeyN') { e.preventDefault(); newChat(); return; }
  if (t.closest && t.closest('.apc-assist__edit') && t.tagName === 'TEXTAREA') {
    if (e.key === 'Enter' && !e.shiftKey) { e.preventDefault(); branchEdit(t.closest('[data-id]').dataset.id, t.value); return; }
  }
  if (!modelMenu.hidden && t.closest && t.closest('.apc-assist__models')) {
    const opts = $$('.apc-assist__opt', modelMenu);
    const i = opts.indexOf(t);
    if (e.key === 'ArrowDown' || e.key === 'ArrowUp') { e.preventDefault(); opts[(i + (e.key === 'ArrowDown' ? 1 : -1) + opts.length) % opts.length].focus(); return; }
    if (e.key === 'Tab') { openModels(false); }
  }
  if (t.closest && t.closest('.apc-assist__history') && (e.key === 'ArrowDown' || e.key === 'ArrowUp')) {
    const all = $$('.apc-assist__chat');
    const i = all.indexOf(t);
    if (i >= 0) { e.preventDefault(); all[(i + (e.key === 'ArrowDown' ? 1 : -1) + all.length) % all.length].focus(); }
    return;
  }
  if (e.key === 'Escape') {
    if (S.live) { e.preventDefault(); finish('stopped'); return; }
    if (!modelMenu.hidden) { e.preventDefault(); openModels(false); modelBtn.focus(); return; }
    if (S.editing) { e.preventDefault(); S.editing = null; renderThread({ stick: false }); ta.focus(); return; }
    if (S.side) { e.preventDefault(); setSide(false); $('[data-act="side-open"]').focus(); }
  }
});

renderModel();
renderHistory();
renderThread();

css:
/* Helpdesk. Re-theme with --apc-desk-bg, -ink, -accent and -note (and -h for height). */
@property --apc-desk-p { syntax: "<number>"; inherits: true; initial-value: 1; }

.apc-desk {
  --apc-desk-bg: oklch(0.978 0.004 250);
  --apc-desk-ink: oklch(0.245 0.02 255);
  --apc-desk-accent: oklch(0.69 0.17 50);
  --apc-desk-note: oklch(0.87 0.12 88);

  --apc-desk-panel: color-mix(in oklch, white 75%, var(--apc-desk-bg));
  --apc-desk-sunk: color-mix(in oklch, var(--apc-desk-ink) 3.5%, var(--apc-desk-bg));
  --apc-desk-line: color-mix(in oklch, var(--apc-desk-ink) 10%, transparent);
  --apc-desk-line2: color-mix(in oklch, var(--apc-desk-ink) 17%, transparent);
  --apc-desk-muted: color-mix(in oklch, var(--apc-desk-ink) 64%, var(--apc-desk-bg));
  --apc-desk-faint: color-mix(in oklch, var(--apc-desk-ink) 44%, var(--apc-desk-bg));
  --apc-desk-hover: color-mix(in oklch, var(--apc-desk-ink) 4.5%, transparent);
  --apc-desk-deep: color-mix(in oklab, var(--apc-desk-accent) 62%, var(--apc-desk-ink));
  --apc-desk-tint: color-mix(in oklab, var(--apc-desk-accent) 10%, var(--apc-desk-panel));
  --apc-desk-notebg: color-mix(in oklab, var(--apc-desk-note) 34%, var(--apc-desk-panel));
  --apc-desk-noteink: color-mix(in oklab, var(--apc-desk-note) 30%, oklch(0.38 0.08 70));
  --apc-desk-ok: oklch(0.64 0.14 155);
  --apc-desk-warn: oklch(0.74 0.16 72);
  --apc-desk-bad: oklch(0.6 0.2 25);
  --apc-desk-ease: cubic-bezier(.2, .75, .2, 1);
  --apc-desk-out: cubic-bezier(.3, .7, 0, 1);
  --apc-desk-spring: linear(0, 0.07 2.6%, 0.28 6.6%, 0.67 13.4%, 0.94 20%, 1.06 27%, 1.08 33%, 1.05 41%, 1.01 52%, 0.997 66%, 1);

  position: relative;
  isolation: isolate;
  width: 100%;
  height: var(--apc-desk-h, 680px);
  container-type: inline-size;
  overflow: hidden;
  overflow: clip;
  border-radius: 14px;
  background: var(--apc-desk-bg);
  color: var(--apc-desk-ink);
  font: 400 14px/1.5 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  -webkit-font-smoothing: antialiased;
  color-scheme: light;
  accent-color: var(--apc-desk-accent);
  box-shadow: inset 0 0 0 1px var(--apc-desk-line);
}
:where(.apc-desk) *, :where(.apc-desk) *::before, :where(.apc-desk) *::after { box-sizing: border-box; }
:where(.apc-desk) :is(button, input, textarea, select) { font: inherit; color: inherit; }
:where(.apc-desk) button { background: none; border: 0; padding: 0; cursor: pointer; }
:where(.apc-desk) :is(ol, ul) { list-style: none; margin: 0; padding: 0; }
:where(.apc-desk) :is(h2, h3, h4, p, dl, dd) { margin: 0; }
:where(.apc-desk) svg { width: 18px; height: 18px; fill: none; stroke: currentColor; stroke-width: 1.75; stroke-linecap: round; stroke-linejoin: round; flex: none; }
:where(.apc-desk) :focus-visible { outline: 2px solid var(--apc-desk-accent); outline-offset: 2px; border-radius: 6px; }
.apc-desk [hidden] { display: none !important; }
.apc-desk__kbd {
  display: inline-grid; place-items: center; min-width: 18px; height: 18px; padding: 0 4px; border-radius: 5px;
  font: 600 10.5px/1 ui-monospace, Menlo, monospace; color: var(--apc-desk-muted); background: var(--apc-desk-panel);
  box-shadow: inset 0 -1px 0 var(--apc-desk-line2), 0 0 0 1px var(--apc-desk-line2);
}
.apc-desk__av { --s: 28px; display: inline-grid; place-items: center; width: var(--s); height: var(--s); border-radius: 50%; flex: none; font-size: calc(var(--s) * .38); font-weight: 700; color: oklch(0.38 0.08 var(--h)); background: oklch(0.91 0.05 var(--h)); }

.apc-desk__app { display: grid; height: 100%; grid-template-columns: minmax(300px, 340px) minmax(0, 1fr) minmax(250px, 280px); grid-template-areas: "queue ticket cust"; }
.apc-desk__queue { grid-area: queue; }
.apc-desk__ticket { grid-area: ticket; }
.apc-desk__cust { grid-area: cust; }

/* ---------- queue ---------- */
.apc-desk__queue { display: grid; grid-template-columns: minmax(0, 1fr); grid-template-rows: auto minmax(0, 1fr) auto; min-height: 0; background: var(--apc-desk-sunk); border-right: 1px solid var(--apc-desk-line); }
.apc-desk__qhead { padding: 14px 14px 10px; display: grid; gap: 10px; border-bottom: 1px solid var(--apc-desk-line); }
.apc-desk__brand { display: flex; align-items: center; gap: 10px; }
.apc-desk__brand div { display: grid; line-height: 1.2; flex: 1; min-width: 0; }
.apc-desk__brand b { font-size: 15.5px; font-weight: 780; letter-spacing: -0.02em; }
.apc-desk__brand small { font-size: 11.5px; color: var(--apc-desk-faint); }
.apc-desk__logo { display: grid; place-items: center; width: 32px; height: 32px; border-radius: 9px; color: var(--apc-desk-ink); background: var(--apc-desk-accent); flex: none; }
.apc-desk__logo svg { width: 20px; height: 20px; stroke-width: 1.8; }
.apc-desk__breach { display: inline-flex; align-items: center; gap: 6px; height: 24px; padding: 0 9px; border-radius: 99px; font-size: 12px; font-weight: 700; font-variant-numeric: tabular-nums; color: var(--apc-desk-bad); background: color-mix(in oklch, var(--apc-desk-bad) 10%, transparent); white-space: nowrap; }
.apc-desk__breach:empty { display: none; }
.apc-desk__breach::before { content: ""; width: 7px; height: 7px; border-radius: 50%; background: currentColor; animation: apc-desk-pulse 1.6s var(--apc-desk-ease) infinite; }
.apc-desk__views { display: flex; gap: 2px; padding: 3px; border-radius: 10px; background: color-mix(in oklch, var(--apc-desk-ink) 6%, transparent); }
.apc-desk__views button { flex: 1; display: inline-flex; align-items: center; justify-content: center; gap: 6px; height: 30px; padding: 0 6px; border-radius: 8px; font-size: 12.5px; font-weight: 600; color: var(--apc-desk-muted); white-space: nowrap; transition: background-color .2s, color .2s, box-shadow .2s; }
.apc-desk__views button:hover { color: var(--apc-desk-ink); }
.apc-desk__views button[aria-selected="true"] { color: var(--apc-desk-ink); background: var(--apc-desk-panel); box-shadow: 0 1px 3px var(--apc-desk-line2), 0 0 0 1px var(--apc-desk-line); }
.apc-desk__views b { font-size: 11px; font-weight: 700; font-variant-numeric: tabular-nums; color: var(--apc-desk-faint); }
.apc-desk__views button[aria-selected="true"] b { color: var(--apc-desk-deep); }
.apc-desk__search { display: flex; align-items: center; gap: 8px; height: 34px; padding: 0 10px; border-radius: 9px; background: var(--apc-desk-panel); box-shadow: 0 0 0 1px var(--apc-desk-line2); color: var(--apc-desk-faint); }
.apc-desk__search:focus-within { box-shadow: 0 0 0 1.5px var(--apc-desk-accent); }
.apc-desk__search svg { width: 15px; height: 15px; }
.apc-desk__search input { flex: 1; min-width: 0; border: 0; outline: none; background: none; font-size: 13.5px; }
.apc-desk__list { position: relative; overflow: auto; padding: 6px; scrollbar-width: thin; overscroll-behavior: contain; outline: none; }
.apc-desk__row {
  position: relative; display: grid; grid-template-columns: 40px minmax(0, 1fr) auto; grid-template-areas: "sla who when" "sla subj subj" "sla prev meta"; column-gap: 10px; row-gap: 1px;
  padding: 10px 10px 10px 8px; border-radius: 11px; cursor: pointer; transition: background-color .18s, box-shadow .18s;
}
.apc-desk__row + .apc-desk__row { margin-top: 2px; }
.apc-desk__row:hover { background: var(--apc-desk-hover); }
.apc-desk__row[aria-selected="true"] { background: var(--apc-desk-panel); box-shadow: 0 0 0 1px var(--apc-desk-line2), 0 2px 8px -4px var(--apc-desk-line2); }
.apc-desk__row[aria-selected="true"]::before { content: ""; position: absolute; left: -6px; top: 12px; bottom: 12px; width: 3px; border-radius: 0 3px 3px 0; background: var(--apc-desk-accent); }
.apc-desk__row[data-leaving] { animation: apc-desk-leave .35s var(--apc-desk-ease) forwards; pointer-events: none; }
.apc-desk__row[data-entering] { animation: apc-desk-enter .45s var(--apc-desk-out) both; }
.apc-desk__who { grid-area: who; display: flex; align-items: center; gap: 6px; min-width: 0; font-size: 13px; font-weight: 600; color: var(--apc-desk-muted); }
.apc-desk__who span { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.apc-desk__who svg { width: 14px; height: 14px; color: var(--apc-desk-faint); }
.apc-desk__when { grid-area: when; font-size: 11.5px; color: var(--apc-desk-faint); font-variant-numeric: tabular-nums; }
.apc-desk__subj { grid-area: subj; font-size: 14px; font-weight: 650; letter-spacing: -0.005em; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.apc-desk__row[data-unread] .apc-desk__subj::after { content: ""; display: inline-block; width: 7px; height: 7px; margin-left: 6px; border-radius: 50%; background: var(--apc-desk-accent); vertical-align: 2px; }
.apc-desk__prev { grid-area: prev; font-size: 12.5px; color: var(--apc-desk-faint); overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.apc-desk__rmeta { grid-area: meta; display: flex; align-items: center; gap: 6px; justify-self: end; }
.apc-desk__rmeta .apc-desk__av { --s: 20px; font-size: 8px; }
.apc-desk__unassigned { width: 20px; height: 20px; border-radius: 50%; box-shadow: inset 0 0 0 1.5px var(--apc-desk-line2); background: repeating-linear-gradient(45deg, transparent 0 3px, var(--apc-desk-line) 3px 4px); }
.apc-desk__pri { height: 18px; padding: 0 6px; border-radius: 5px; display: inline-grid; place-items: center; font-size: 10.5px; font-weight: 750; letter-spacing: .03em; text-transform: uppercase; color: var(--apc-desk-muted); background: color-mix(in oklch, var(--apc-desk-ink) 7%, transparent); }
.apc-desk__pri[data-p="urgent"] { color: white; background: var(--apc-desk-bad); }
.apc-desk__pri[data-p="high"] { color: var(--apc-desk-deep); background: color-mix(in oklch, var(--apc-desk-accent) 20%, transparent); }
.apc-desk__row mark { background: color-mix(in oklch, var(--apc-desk-accent) 28%, transparent); color: inherit; border-radius: 3px; }
.apc-desk__empty { display: grid; justify-items: center; gap: 8px; padding: 40px 16px; text-align: center; color: var(--apc-desk-faint); font-size: 13.5px; text-wrap: balance; }
.apc-desk__empty svg { width: 34px; height: 34px; color: var(--apc-desk-ok); }
.apc-desk__empty b { font-size: 15px; color: var(--apc-desk-ink); }
.apc-desk__qfoot { display: flex; align-items: center; gap: 4px; padding: 9px 14px; border-top: 1px solid var(--apc-desk-line); font-size: 11.5px; color: var(--apc-desk-faint); white-space: nowrap; overflow: hidden; }
.apc-desk__qfoot .apc-desk__kbd:nth-child(3), .apc-desk__qfoot .apc-desk__kbd:nth-child(4) { margin-left: 8px; }

/* SLA ring: a conic gradient whose sweep is a registered number, so each tick eases */
.apc-desk__sla {
  --c: var(--apc-desk-ok);
  grid-area: sla; align-self: start; position: relative; display: grid; place-items: center; width: 40px; height: 40px; border-radius: 50%;
  font-size: 10px; font-weight: 750; font-variant-numeric: tabular-nums; letter-spacing: -0.02em; color: var(--apc-desk-muted);
  transition: --apc-desk-p 1s linear;
}
.apc-desk__sla::before {
  content: ""; position: absolute; inset: 0; border-radius: 50%;
  background: conic-gradient(var(--c) calc(var(--apc-desk-p) * 1turn), color-mix(in oklch, var(--apc-desk-ink) 9%, transparent) 0);
  -webkit-mask: radial-gradient(farthest-side, transparent calc(100% - 3.5px), black calc(100% - 3px));
  mask: radial-gradient(farthest-side, transparent calc(100% - 3.5px), black calc(100% - 3px));
}
.apc-desk__sla[data-s="warn"] { --c: var(--apc-desk-warn); color: color-mix(in oklch, var(--apc-desk-warn) 55%, var(--apc-desk-ink)); }
.apc-desk__sla[data-s="bad"] { --c: var(--apc-desk-bad); color: var(--apc-desk-bad); }
.apc-desk__sla[data-s="bad"]::after { content: ""; position: absolute; inset: -3px; border-radius: 50%; box-shadow: 0 0 0 2px color-mix(in oklch, var(--apc-desk-bad) 30%, transparent); animation: apc-desk-ring 1.8s var(--apc-desk-ease) infinite; }
.apc-desk__sla[data-s="none"] { color: var(--apc-desk-faint); }
.apc-desk__sla[data-s="none"]::before { background: color-mix(in oklch, var(--apc-desk-ink) 9%, transparent); }
.apc-desk__sla svg { width: 15px; height: 15px; }

/* ---------- ticket ---------- */
.apc-desk__ticket { position: relative; display: grid; grid-template-columns: minmax(0, 1fr); grid-template-rows: auto minmax(0, 1fr) auto; min-width: 0; min-height: 0; background: var(--apc-desk-panel); }
.apc-desk__thead { display: grid; grid-template-columns: auto minmax(0, 1fr) auto; grid-template-areas: "back title side" "back fields fields"; align-items: center; column-gap: 10px; row-gap: 8px; padding: 14px 18px 12px; border-bottom: 1px solid var(--apc-desk-line); }
.apc-desk__back, .apc-desk__custbtn { display: none; place-items: center; width: 32px; height: 32px; border-radius: 8px; color: var(--apc-desk-muted); }
.apc-desk__back { grid-area: back; margin-left: -8px; align-self: start; }
.apc-desk__back:hover, .apc-desk__custbtn:hover { background: var(--apc-desk-hover); color: var(--apc-desk-ink); }
.apc-desk__title { grid-area: title; min-width: 0; }
.apc-desk__title h2 { font-size: clamp(16px, 1.6cqi, 18.5px); font-weight: 760; letter-spacing: -0.02em; line-height: 1.25; text-wrap: balance; }
.apc-desk__title p { margin-top: 2px; font-size: 12.5px; color: var(--apc-desk-faint); font-variant-numeric: tabular-nums; }
.apc-desk__tside { grid-area: side; display: flex; align-items: center; gap: 6px; align-self: start; }
.apc-desk__viewing { display: inline-flex; align-items: center; gap: 6px; height: 26px; padding: 0 9px 0 3px; border-radius: 99px; font-size: 12px; color: var(--apc-desk-muted); background: var(--apc-desk-sunk); box-shadow: 0 0 0 1px var(--apc-desk-line); white-space: nowrap; animation: apc-desk-enter .5s var(--apc-desk-out) both; }
.apc-desk__viewing .apc-desk__av { --s: 20px; font-size: 8px; position: relative; }
.apc-desk__viewing .apc-desk__av::after { content: ""; position: absolute; inset: -2px; border-radius: 50%; box-shadow: 0 0 0 1.5px var(--apc-desk-ok); animation: apc-desk-ring 2s var(--apc-desk-ease) infinite; }
.apc-desk__fields { grid-area: fields; display: flex; gap: 6px; overflow-x: auto; scrollbar-width: none; padding: 2px; margin: -2px; }
.apc-desk__field { position: relative; display: inline-flex; align-items: center; gap: 5px; height: 30px; padding: 0 2px 0 9px; border-radius: 8px; font-size: 12px; flex: none; white-space: nowrap; color: var(--apc-desk-faint); box-shadow: 0 0 0 1px var(--apc-desk-line2); background: var(--apc-desk-panel); transition: box-shadow .2s; }
.apc-desk__field:focus-within { box-shadow: 0 0 0 1.5px var(--apc-desk-accent); }
.apc-desk__field select { appearance: none; -webkit-appearance: none; height: 100%; padding: 0 22px 0 0; border: 0; outline: none; background: transparent; font-weight: 650; color: var(--apc-desk-ink); cursor: pointer; }
.apc-desk__field::after { content: ""; position: absolute; right: 9px; top: 50%; width: 6px; height: 6px; margin-top: -5px; border: solid var(--apc-desk-faint); border-width: 0 1.5px 1.5px 0; rotate: 45deg; pointer-events: none; }
.apc-desk__field[data-status="solved"] select { color: var(--apc-desk-ok); }
.apc-desk__field[data-status="pending"] select { color: color-mix(in oklch, var(--apc-desk-warn) 60%, var(--apc-desk-ink)); }

.apc-desk__thread { overflow: auto; overscroll-behavior: contain; scrollbar-width: thin; outline: none; }
.apc-desk__events { display: grid; gap: 14px; padding: 18px 18px 22px; }
.apc-desk__ev { display: grid; grid-template-columns: 32px minmax(0, 1fr); column-gap: 12px; animation: apc-desk-enter .4s var(--apc-desk-out) both; animation-delay: calc(var(--i, 0) * 40ms); }
.apc-desk__ev .apc-desk__av { --s: 32px; }
.apc-desk__msg { min-width: 0; padding: 10px 14px 12px; border-radius: 4px 14px 14px 14px; background: var(--apc-desk-sunk); box-shadow: 0 0 0 1px var(--apc-desk-line); }
.apc-desk__msg header { display: flex; align-items: baseline; gap: 8px; margin-bottom: 3px; font-size: 13px; }
.apc-desk__msg header b { font-weight: 700; }
.apc-desk__msg header span { color: var(--apc-desk-faint); font-size: 12px; font-variant-numeric: tabular-nums; }
.apc-desk__msg header em { margin-left: auto; font-style: normal; font-size: 11px; font-weight: 700; letter-spacing: .05em; text-transform: uppercase; color: var(--apc-desk-faint); }
.apc-desk__msg p { white-space: pre-wrap; text-wrap: pretty; overflow-wrap: anywhere; }
.apc-desk__ev[data-kind="agent"] .apc-desk__msg { background: var(--apc-desk-tint); box-shadow: 0 0 0 1px color-mix(in oklch, var(--apc-desk-accent) 22%, transparent); }
.apc-desk__ev[data-kind="note"] .apc-desk__msg { background: var(--apc-desk-notebg); box-shadow: 0 0 0 1px color-mix(in oklch, var(--apc-desk-note) 70%, transparent); border-radius: 14px; }
.apc-desk__ev[data-kind="note"] header em { color: var(--apc-desk-noteink); }
.apc-desk__ev[data-kind="sys"] { grid-template-columns: minmax(0, 1fr); justify-items: center; }
.apc-desk__sys { display: inline-flex; align-items: center; gap: 8px; padding: 3px 12px; border-radius: 99px; font-size: 12px; color: var(--apc-desk-faint); background: var(--apc-desk-sunk); text-align: center; text-wrap: balance; }
.apc-desk__sys svg { width: 14px; height: 14px; }
.apc-desk__nothing { display: grid; place-items: center; height: 100%; color: var(--apc-desk-faint); }

/* composer: the whole block turns into a sticky-note when "Internal note" is checked */
.apc-desk__composer {
  position: relative; margin: 0 14px 14px; padding: 10px 10px 8px 12px; border-radius: 14px; background: var(--apc-desk-panel);
  box-shadow: 0 0 0 1px var(--apc-desk-line2), 0 10px 30px -18px color-mix(in oklch, var(--apc-desk-ink) 40%, transparent);
  transition: background-color .35s var(--apc-desk-ease), box-shadow .35s var(--apc-desk-ease);
}
.apc-desk__composer:focus-within { box-shadow: 0 0 0 1.5px color-mix(in oklch, var(--apc-desk-accent) 70%, transparent), 0 10px 30px -18px color-mix(in oklch, var(--apc-desk-accent) 60%, transparent); }
.apc-desk__composer:has(input[value="note"]:checked) { background: var(--apc-desk-notebg); box-shadow: 0 0 0 1.5px color-mix(in oklab, var(--apc-desk-note) 80%, var(--apc-desk-ink)), 0 10px 30px -18px color-mix(in oklch, var(--apc-desk-note) 80%, transparent); }
.apc-desk__ctop { display: flex; align-items: center; gap: 10px; min-width: 0; }
.apc-desk__mode { display: flex; padding: 2px; border-radius: 9px; background: color-mix(in oklch, var(--apc-desk-ink) 6%, transparent); flex: none; }
.apc-desk__mode label { position: relative; cursor: pointer; }
.apc-desk__mode input { position: absolute; opacity: 0; pointer-events: none; }
.apc-desk__mode span { display: inline-flex; align-items: center; height: 26px; padding: 0 10px; border-radius: 7px; font-size: 12.5px; font-weight: 650; color: var(--apc-desk-muted); transition: background-color .2s, color .2s, box-shadow .2s; }
.apc-desk__mode input:checked + span { color: var(--apc-desk-ink); background: var(--apc-desk-panel); box-shadow: 0 1px 3px var(--apc-desk-line2); }
.apc-desk__mode input[value="note"]:checked + span { background: var(--apc-desk-note); color: var(--apc-desk-noteink); }
.apc-desk__mode input:focus-visible + span { outline: 2px solid var(--apc-desk-accent); outline-offset: 1px; }
.apc-desk__to { min-width: 0; font-size: 12.5px; color: var(--apc-desk-faint); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.apc-desk__to b { color: var(--apc-desk-muted); font-weight: 600; }
.apc-desk__private { display: none; align-items: center; gap: 6px; font-size: 12.5px; font-weight: 600; color: var(--apc-desk-noteink); white-space: nowrap; }
.apc-desk__private svg { width: 14px; height: 14px; }
.apc-desk__composer:has(input[value="note"]:checked) .apc-desk__to { display: none; }
.apc-desk__composer:has(input[value="note"]:checked) .apc-desk__private { display: inline-flex; animation: apc-desk-enter .35s var(--apc-desk-out) both; }
.apc-desk__composer:has(input[value="note"]:checked) .apc-desk__send--resolve { display: none; }
.apc-desk__composer:has(input[value="note"]:checked) .apc-desk__send { background: var(--apc-desk-noteink); }
.apc-desk__composer textarea { display: block; width: 100%; min-height: 66px; max-height: 170px; margin-top: 8px; padding: 2px 2px; border: 0; outline: none; resize: none; background: none; field-sizing: content; line-height: 1.55; }
.apc-desk__composer textarea::placeholder { color: var(--apc-desk-faint); }
