/* ---------------- SLA ---------------- */
function sla(t) {
  if (t.status !== 'open' || t.due == null) return { s: 'none', p: 1, label: t.status === 'solved' ? 'done' : 'wait' };
  const left = t.due - Date.now();
  const p = Math.max(0, Math.min(1, left / (t.win * MIN)));
  const a = Math.abs(left);
  const m = Math.floor(a / MIN), s = Math.floor((a % MIN) / 1000);
  let label;
  if (a < 10 * MIN) label = `${m}:${String(s).padStart(2, '0')}`;
  else if (a < 60 * MIN) label = `${m}m`;
  else label = `${Math.floor(m / 60)}h${m % 60 ? String(m % 60).padStart(2, '0') : ''}`;
  if (left < 0) return { s: 'bad', p: 1, label: '−' + label };
  return { s: p <= 0.25 ? 'warn' : 'ok', p, label };
}
const order = (a, b) => {
  const ra = a.status === 'open' && a.due != null ? a.due : Infinity;
  const rb = b.status === 'open' && b.due != null ? b.due : Infinity;
  return ra - rb || b.id - a.id;
};
function slaHTML(t) {
  const x = sla(t);
  const inner = x.s === 'none' ? ic(t.status === 'solved' ? 'check' : 'pause') : x.label;
  const lbl = x.s === 'none' ? (t.status === 'solved' ? 'Solved' : 'Waiting on customer') : x.s === 'bad' ? `SLA breached ${x.label.slice(1)} ago` : `${x.label} left on SLA`;
  return `<span class="apc-desk__sla" data-s="${x.s}" style="--apc-desk-p:${x.p.toFixed(4)}" role="img" aria-label="${lbl}">${inner}</span>`;
}

/* ---------------- queue ---------------- */
function visibleTickets() {
  const v = VIEWS.find((x) => x.id === S.view);
  const q = S.q.trim().toLowerCase();
  return TK.filter(v.test).filter((t) => {
    if (!q) return true;
    const c = CUST[t.cust];
    return [t.subj, c.name, c.email, '#' + t.id, ...c.orders.map((o) => o.n)].some((s) => s.toLowerCase().includes(q));
  }).sort(order);
}
function hl(s, q) {
  if (!q) return esc(s);
  const i = s.toLowerCase().indexOf(q);
  return i < 0 ? esc(s) : esc(s.slice(0, i)) + `<mark>${esc(s.slice(i, i + q.length))}</mark>` + esc(s.slice(i + q.length));
}
function renderViews() {
  viewsEl.innerHTML = VIEWS.map((v) => `<button type="button" role="tab" data-view="${v.id}" aria-selected="${v.id === S.view}">${v.name}<b>${TK.filter(v.test).length}</b></button>`).join('');
}
function rowHTML(t) {
  const c = CUST[t.cust];
  const q = S.q.trim().toLowerCase();
  const last = [...t.ev].reverse().find((e) => e.k !== 'sys');
  const lastText = last ? (last.k === 'agent' ? 'You: ' : last.k === 'note' ? 'Note: ' : '') + last.text : '';
  const owner = t.who ? av(TEAM[t.who].h, TEAM[t.who].ini, `title="${esc(TEAM[t.who].name)}"`) : '<span class="apc-desk__unassigned" title="Unassigned"></span>';
  const when = t.ev.length ? t.ev[t.ev.length - 1].t : 0;
  return `<li class="apc-desk__row" role="option" id="apc-desk-${UID}-t${t.id}" data-id="${t.id}" aria-selected="${t.id === S.sel}" tabindex="${t.id === S.sel ? 0 : -1}" ${t.unread ? 'data-unread' : ''}>
    ${slaHTML(t)}
    <span class="apc-desk__who">${ic(t.ch)}<span>${hl(c.name, q)}</span></span>
    <span class="apc-desk__when">${when < 0 ? 'Yesterday' : hhmm(when)}</span>
    <span class="apc-desk__subj">${hl(t.subj, q)}</span>
    <span class="apc-desk__prev">${esc(lastText)}</span>
    <span class="apc-desk__rmeta">${t.pri === 'low' || t.pri === 'normal' ? '' : `<span class="apc-desk__pri" data-p="${t.pri}">${t.pri}</span>`}${owner}</span>
  </li>`;
}
function renderList({ flip = false, enter = null } = {}) {
  const before = new Map();
  if (flip && !RM.matches) $$('.apc-desk__row', listEl).forEach((r) => before.set(r.dataset.id, r.getBoundingClientRect().top));
  const ae = root.ownerDocument.activeElement;
  const hadFocus = ae && ae.classList && ae.classList.contains('apc-desk__row');
  const list = visibleTickets();
  listEl.innerHTML = list.length ? list.map(rowHTML).join('') : (S.q
    ? `<li class="apc-desk__empty"><b>No matches</b>Nothing in ${VIEWS.find((v) => v.id === S.view).name} matches “${esc(S.q)}”.</li>`
    : `<li class="apc-desk__empty">${ic('done')}<b>Queue clear</b>Nothing left in ${VIEWS.find((v) => v.id === S.view).name}. Nice work.</li>`);
  if (enter) { const r = $(`.apc-desk__row[data-id="${enter}"]`, listEl); if (r) r.setAttribute('data-entering', ''); }
  if (before.size) {
    $$('.apc-desk__row', listEl).forEach((r) => {
      const o = before.get(r.dataset.id);
      if (o == null) return;
      const d = o - r.getBoundingClientRect().top;
      if (Math.abs(d) > 0.5) r.animate([{ transform: `translateY(${d}px)` }, { transform: 'none' }], { duration: 520, easing: SPRING });
    });
  }
  if (hadFocus) { const r = $(`.apc-desk__row[data-id="${S.sel}"]`, listEl); if (r) r.focus({ preventScroll: true }); }
  renderViews();
  renderBreach();
}
function renderBreach() {
  const n = TK.filter((t) => t.status === 'open' && t.due != null && t.due < Date.now()).length;
  breachEl.textContent = n ? `${n} breaching` : '';
}

/* ---------------- ticket ---------------- */
function evHTML(e, i) {
  if (e.k === 'sys') return `<li class="apc-desk__ev" data-kind="sys" style="--i:${i}"><span class="apc-desk__sys">${ic('route')}${esc(e.text)} · ${e.t < 0 ? 'yesterday' : hhmm(e.t)}</span></li>`;
  const person = e.k === 'cust' ? { name: CUST[e.by].name, h: CUST[e.by].h, ini: CUST[e.by].name.split(' ').map((w) => w[0]).join('') } : TEAM[e.by];
  const tag = e.k === 'note' ? 'Internal note' : e.k === 'agent' ? 'Reply' : '';
  return `<li class="apc-desk__ev" data-kind="${e.k}" style="--i:${i}">${av(person.h, person.ini)}<div class="apc-desk__msg"><header><b>${esc(person.name)}</b><span>${e.t < 0 ? 'Yesterday ' + hhmm(e.t + 1440) : hhmm(e.t)}</span>${tag ? `<em>${tag}</em>` : ''}</header><p>${esc(e.text)}</p></div></li>`;
}
function renderTicket({ animate = true } = {}) {
  const t = cur();
  if (!t) {
    thead.innerHTML = `<button class="apc-desk__back" type="button" data-act="back" aria-label="Back to queue">${ic('back')}</button>`;
    events.innerHTML = '<li class="apc-desk__nothing">Select a ticket</li>';
    custEl.innerHTML = '';
    return;
  }
  const c = CUST[t.cust];
  const chName = { chat: 'Chat', mail: 'Email', phone: 'Phone callback' }[t.ch];
  const opened = t.ev[0].t;
  thead.innerHTML = `
    <button class="apc-desk__back" type="button" data-act="back" aria-label="Back to queue">${ic('back')}</button>
    <div class="apc-desk__title"><h2>${esc(t.subj)}</h2><p>#${t.id} · ${chName} · opened ${opened < 0 ? 'yesterday' : hhmm(opened)} · ${esc(c.name)}</p></div>
    <div class="apc-desk__tside">${t.viewing && t.status !== 'solved' ? `<span class="apc-desk__viewing">${av(TEAM[t.viewing].h, TEAM[t.viewing].ini)}<span>${esc(TEAM[t.viewing].first)} is viewing</span></span>` : ''}<button class="apc-desk__custbtn" type="button" data-act="cust" aria-label="Customer details" aria-expanded="${S.cust}">${ic('user')}</button></div>
    <div class="apc-desk__fields">
      <label class="apc-desk__field" data-status="${t.status}">Status <select data-field="status" aria-label="Status">${['open', 'pending', 'solved'].map((s) => `<option value="${s}" ${s === t.status ? 'selected' : ''}>${s[0].toUpperCase() + s.slice(1)}</option>`).join('')}</select></label>
      <label class="apc-desk__field">Assignee <select data-field="who" aria-label="Assignee"><option value="">Unassigned</option>${Object.entries(TEAM).map(([k, p]) => `<option value="${k}" ${t.who === k ? 'selected' : ''}>${esc(p.name)}${k === 'me' ? ' (you)' : ''}</option>`).join('')}</select></label>
      <label class="apc-desk__field">Priority <select data-field="pri" aria-label="Priority">${PRI.map((p) => `<option value="${p}" ${p === t.pri ? 'selected' : ''}>${p[0].toUpperCase() + p.slice(1)}</option>`).join('')}</select></label>
    </div>`;
  events.innerHTML = t.ev.map((e, i) => evHTML(e, animate ? i : 0)).join('');
  if (!animate || RM.matches) $$('.apc-desk__ev', events).forEach((li) => { li.style.animation = 'none'; });
  thread.scrollTop = thread.scrollHeight;
  toLine.innerHTML = `To <b>${esc(c.name)}</b> · ${esc(c.email)} · via ${chName}`;
  ta.setAttribute('aria-label', S.mode === 'note' ? 'Internal note' : `Reply to ${c.name}`);
  renderCust();
}
function renderCust() {
  const t = cur();
  if (!t) { custEl.innerHTML = ''; return; }
  const c = CUST[t.cust];
  const tickets = c.past.length + TK.filter((x) => x.cust === t.cust).length;
  custEl.innerHTML = `
    <div class="apc-desk__ccard">${av(c.h, c.name.split(' ').map((w) => w[0]).join(''))}<h3>${esc(c.name)}</h3><p>${esc(c.email)}</p><p>${esc(c.city)} · customer since ${esc(c.since)}</p>
      <button class="apc-desk__custbtn apc-desk__x" type="button" data-act="cust" aria-label="Close customer details">${ic('close')}</button></div>
    <div class="apc-desk__kpis"><div><b>${eur(ltv(c))}</b><small>lifetime spend</small></div><div><b>${tickets}</b><small>${tickets === 1 ? 'ticket' : 'tickets'} all time</small></div></div>
    <div class="apc-desk__sec"><h4>Orders</h4>${c.orders.map((o) => `<div class="apc-desk__order"><b>${esc(o.product)}</b><span>${eur(o.total)}</span><small>${o.n} · ${esc(o.date)}</small><em data-s="${o.status}">${o.status}</em></div>`).join('')}</div>
    <div class="apc-desk__sec"><h4>Tags</h4><div class="apc-desk__tags">${c.tags.map((g) => `<span>${esc(g)}</span>`).join('')}</div></div>
    ${c.past.length ? `<div class="apc-desk__sec"><h4>Earlier conversations</h4><ul class="apc-desk__past">${c.past.map(([s, d]) => `<li><span>${esc(s)}</span><span>${esc(d)}</span></li>`).join('')}</ul></div>` : ''}`;
}
function select(id, { focusList = false } = {}) {
  const t = tk(id);
  if (!t) return;
  const changed = S.sel !== id;
  S.sel = id;
  t.unread = false;
  if (changed) { ta.value = ''; filled.hidden = true; syncSend(); closeMacros(); }
  $$('.apc-desk__row', listEl).forEach((r) => {
    const on = +r.dataset.id === id;
    r.setAttribute('aria-selected', on); r.tabIndex = on ? 0 : -1;
    if (on) { r.removeAttribute('data-unread'); if (focusList) { r.focus({ preventScroll: true }); r.scrollIntoView({ block: 'nearest' }); } }
  });
  renderTicket({ animate: changed });
  if (root.clientWidth < 760 && !focusList) setView('ticket');
}
function setView(v) { root.dataset.view = v; }
function setMode(m) {
  S.mode = m;
  $(`input[value="${m}"]`, form).checked = true;
  const c = cur() && CUST[cur().cust];
  ta.placeholder = m === 'note' ? 'Add a note for your team — @mention to notify' : 'Write a reply, or type / for macros';
  ta.setAttribute('aria-label', m === 'note' ? 'Internal note' : `Reply to ${c ? c.name : 'customer'}`);
}

/* ---------------- sending ---------------- */
function syncSend() { const off = !ta.value.trim() || !cur(); $$('.apc-desk__send', form).forEach((b) => { b.disabled = off; }); }
function send(how) {
  const t = cur();
  const text = ta.value.trim();
  if (!t || !text) return;
  const prev = { status: t.status, due: t.due, who: t.who, evLen: t.ev.length };
  if (S.mode === 'note') {
    t.ev.push(E('note', 'me', nowMin(), text));
  } else {
    t.ev.push(E('agent', 'me', nowMin(), text));
    if (!t.who) t.who = 'me';
    if (how === 'resolve') { t.status = 'solved'; t.due = null; t.ev.push(E('sys', null, nowMin(), 'Solved by Ines Duarte')); }
    else if (t.status === 'open') { t.status = 'pending'; t.due = null; }
  }
  ta.value = ''; filled.hidden = true; syncSend();
  if (!CSS.supports('field-sizing', 'content')) ta.style.height = '';
  if (how === 'resolve' && S.mode === 'reply') resolveOut(t, prev, 'Sent and solved');
  else {
    renderTicket({ animate: false });
    const lastEv = $('.apc-desk__ev:last-child', events);
    if (lastEv && !RM.matches) { lastEv.style.animation = ''; }
    renderList({ flip: true });
    if (S.mode === 'reply') { S.undo = { t, prev }; toastMsg(`Reply sent · #${t.id} is pending`, true); maybeCustomerReply(t); }
    else toastMsg('Note added for the team', false);
  }
}
function resolveOut(t, prev, verb) {
  const row = $(`.apc-desk__row[data-id="${t.id}"]`, listEl);
  const stays = VIEWS.find((v) => v.id === S.view).test(t);
  const go = () => {
    const vis = visibleTickets();
    const ghost = { id: t.id, status: prev.status, due: prev.due };
    const next = stays ? t : vis.find((x) => order(x, ghost) > 0) || vis[vis.length - 1];
    renderList({ flip: true });
    if (next) select(next.id); else { S.sel = null; renderTicket(); }
  };
  S.undo = { t, prev };
  toastMsg(`${verb} · #${t.id}`, true);
  if (row && !stays && !RM.matches) { row.setAttribute('data-leaving', ''); later(go, 330); }
  else go();
}
function undo() {
  const u = S.undo;
  if (!u) return;
  S.undo = null;
  const { t, prev } = u;
  t.status = prev.status; t.due = prev.due; t.who = prev.who;
  t.ev.length = prev.evLen;
  S.sel = t.id;
  renderList({ flip: true, enter: t.id });
  select(t.id);
  toastMsg(`Restored #${t.id}`, false);
}
function maybeCustomerReply(t) {
  if (t.id !== 4821 || S.replied[t.id]) return;
  S.replied[t.id] = true;
  later(() => {
    if (t.status === 'solved') return;
    t.ev.push(E('cust', 'mara', nowMin(), 'Thank you, Ines! Rolled back to 3.1 — the app shows 82% after my test loop, so it looks fixed.'));
    t.status = 'open'; t.due = Date.now() + 30 * MIN; t.unread = S.sel !== t.id;
    if (S.sel === t.id) { renderTicket({ animate: false }); const l = $('.apc-desk__ev:last-child', events); if (l && !RM.matches) l.style.animation = ''; }
    renderList({ flip: true });
  }, 7000);
}
let toastT = 0;
function toastMsg(text, withUndo) {
  toast.innerHTML = `${ic('check')}<span>${esc(text)}</span>${withUndo ? `<button type="button" data-act="undo">Undo <kbd class="apc-desk__kbd">${MAC ? '⌘' : 'Ctrl '}Z</kbd></button>` : ''}`;
  toast.setAttribute('data-show', '');
  clearTimeout(toastT);
  toastT = setTimeout(() => { if (!root.isConnected) return; toast.removeAttribute('data-show'); if (withUndo) S.undo = null; }, withUndo ? 6000 : 1800);
}

/* ---------------- field changes ---------------- */
function changeField(field, value) {
  const t = cur();
  if (!t) return;
  const prev = { status: t.status, due: t.due, who: t.who, evLen: t.ev.length };
  if (field === 'status') {
    if (value === t.status) return;
    t.status = value;
    if (!t.win) t.win = 60;
    t.due = value === 'open' ? Date.now() + t.win * MIN : null;
    t.ev.push(E('sys', null, nowMin(), value === 'solved' ? 'Solved by Ines Duarte' : `Status set to ${value} by Ines Duarte`));
    if (value === 'solved') { resolveOut(t, prev, 'Solved'); return; }
  } else if (field === 'who') {
    t.who = value || null;
    t.ev.push(E('sys', null, nowMin(), value ? `Assigned to ${TEAM[value].name} by Ines Duarte` : 'Unassigned by Ines Duarte'));
  } else if (field === 'pri') {
    t.pri = value;
    t.ev.push(E('sys', null, nowMin(), `Priority set to ${value} by Ines Duarte`));
  }
  renderTicket({ animate: false });
  const l = $('.apc-desk__ev:last-child', events); if (l && !RM.matches) l.style.animation = '';
  const sel = $(`select[data-field="${field}"]`, thead); if (sel) sel.focus({ preventScroll: true });
  renderList({ flip: true });
}

/* ---------------- macros ---------------- */
function ctx() {
  const t = cur(); const c = CUST[t.cust]; const o = c.orders[0];
  return { 'customer.first_name': firstName(c), 'customer.name': c.name, 'order.number': o.n, 'order.product': o.product.split(',')[0], 'order.total': eur(o.total), 'agent.first_name': TEAM.me.first };
}
function openMacros() {
  if (!cur()) return;
  S.macro = { sel: 0, items: MACROS };
  macroBox.hidden = false;
  macroBtn.setAttribute('aria-expanded', 'true');
  macroInput.value = '';
  renderMacros();
  macroInput.focus();
}
function renderMacros() {
  const q = macroInput.value.trim().toLowerCase();
  const items = MACROS.filter((m) => !q || m.name.toLowerCase().includes(q) || m.text.toLowerCase().includes(q));
  S.macro.items = items;
  S.macro.sel = Math.min(S.macro.sel, Math.max(0, items.length - 1));
  const vars = ctx();
  macroList.innerHTML = items.length ? items.map((m, i) => `<li role="option" id="apc-desk-${UID}-m${i}" data-macro="${i}" aria-selected="${i === S.macro.sel}"><b>${esc(m.name)}</b><small>${esc(fill(m.text, vars).replace(/\s+/g, ' '))}</small></li>`).join('') : '<li class="apc-desk__none">No macro matches</li>';
  if (items.length) macroInput.setAttribute('aria-activedescendant', `apc-desk-${UID}-m${S.macro.sel}`);
}
const fill = (text, vars) => text.replace(/\{\{([\w.]+)\}\}/g, (_, k) => vars[k] ?? `{{${k}}}`);
function applyMacro(i) {
  const m = S.macro && S.macro.items[i];
  if (!m) return;
  const vars = ctx();
  const used = [...new Set([...m.text.matchAll(/\{\{([\w.]+)\}\}/g)].map((x) => x[1]))];
  ta.value = fill(m.text, vars);
  closeMacros(false);
  setMode('reply');
  ta.focus();
  ta.setSelectionRange(ta.value.length, ta.value.length);
  filled.innerHTML = `<span>Filled ${used.length} from ${esc(CUST[cur().cust].name.split(' ')[0])}’s record:</span>` + used.map((k, j) => `<code style="--i:${j}">${esc(k)} <b>${esc(vars[k])}</b></code>`).join('');
  filled.hidden = false;
  syncSend();
  if (!CSS.supports('field-sizing', 'content')) { ta.style.height = 'auto'; ta.style.height = Math.min(170, ta.scrollHeight) + 'px'; }
}
function closeMacros(restore = true) {
  if (!S.macro) return;
  S.macro = null;
  macroBox.hidden = true;
  macroBtn.setAttribute('aria-expanded', 'false');
  if (restore) ta.focus();
}
macroInput.addEventListener('input', () => { S.macro.sel = 0; renderMacros(); });
macroInput.addEventListener('keydown', (e) => {
  const n = S.macro ? S.macro.items.length : 0;
  if (e.key === 'ArrowDown' || e.key === 'ArrowUp') {
    e.preventDefault(); if (!n) return;
    S.macro.sel = (S.macro.sel + (e.key === 'ArrowDown' ? 1 : -1) + n) % n;
    renderMacros();
    const li = $(`[data-macro="${S.macro.sel}"]`, macroList); if (li) li.scrollIntoView({ block: 'nearest' });
  } else if (e.key === 'Enter') { e.preventDefault(); applyMacro(S.macro.sel); }
  else if (e.key === 'Escape') { e.preventDefault(); e.stopPropagation(); closeMacros(); }
  else if (e.key === 'Tab') { closeMacros(false); }
});
macroList.addEventListener('pointerdown', (e) => { const li = e.target.closest('[data-macro]'); if (li) { e.preventDefault(); applyMacro(+li.dataset.macro); } });

/* ---------------- events ---------------- */
form.addEventListener('submit', (e) => { e.preventDefault(); send(e.submitter && e.submitter.dataset.how === 'resolve' ? 'resolve' : 'send'); });
form.addEventListener('change', (e) => { if (e.target.name === 'apc-desk-mode') { setMode(e.target.value); ta.focus(); } });
ta.addEventListener('input', () => {
  syncSend();
  if (!ta.value.trim()) filled.hidden = true;
  if (ta.value === '/') { ta.value = ''; syncSend(); openMacros(); }
  if (!CSS.supports('field-sizing', 'content')) { ta.style.height = 'auto'; ta.style.height = Math.min(170, ta.scrollHeight) + 'px'; }
});
ta.addEventListener('keydown', (e) => {
  if (e.key === 'Enter' && (e.metaKey || e.ctrlKey)) { e.preventDefault(); send(e.shiftKey && S.mode === 'reply' ? 'resolve' : 'send'); }
});
thead.addEventListener('change', (e) => { const f = e.target.dataset.field; if (f) changeField(f, e.target.value); });
search.addEventListener('input', () => { S.q = search.value; renderList(); });
search.addEventListener('keydown', (e) => { if (e.key === 'ArrowDown') { e.preventDefault(); const r = $('.apc-desk__row', listEl); if (r) select(+r.dataset.id, { focusList: true }); } });
listEl.addEventListener('keydown', (e) => {
  const row = e.target.closest('.apc-desk__row');
  if (!row) return;
  const rows = $$('.apc-desk__row', listEl);
  const i = rows.indexOf(row);
  if (e.key === 'ArrowDown' || e.key === 'ArrowUp') { e.preventDefault(); const r = rows[i + (e.key === 'ArrowDown' ? 1 : -1)]; if (r) select(+r.dataset.id, { focusList: true }); }
  else if (e.key === 'Enter') { e.preventDefault(); select(+row.dataset.id); ta.focus(); }
});

root.addEventListener('click', (e) => {
  if (S.macro && !e.target.closest('.apc-desk__macros') && !e.target.closest('[data-act="macros"]')) closeMacros(false);
  const row = e.target.closest('.apc-desk__row');
  if (row) { select(+row.dataset.id); return; }
  const v = e.target.closest('[data-view]');
  if (v && v.closest('.apc-desk__views')) {
    S.view = v.dataset.view;
    renderList();
    const first = visibleTickets()[0];
    if (first && !visibleTickets().some((t) => t.id === S.sel)) select(first.id);
    return;
  }
  const act = e.target.closest('[data-act]');
  if (!act) return;
  switch (act.dataset.act) {
    case 'macros': if (S.macro) closeMacros(); else openMacros(); break;
    case 'back': setView('queue'); { const r = $(`.apc-desk__row[data-id="${S.sel}"]`, listEl); if (r) r.focus({ preventScroll: true }); } break;
    case 'cust': S.cust = !S.cust; root.toggleAttribute('data-cust', S.cust); $$('[data-act="cust"]').forEach((b) => b.setAttribute('aria-expanded', S.cust)); if (S.cust) { const x = $('.apc-desk__x', custEl); if (x) x.focus(); } break;
    case 'undo': undo(); break;
  }
});

root.addEventListener('keydown', (e) => {
  const t = e.target;
  const mod = e.metaKey || e.ctrlKey;
  if (mod && e.key.toLowerCase() === 'z' && S.undo && !(typing(t) && t.value)) { e.preventDefault(); undo(); return; }
  if (e.key === 'Escape') {
    if (S.macro) { e.preventDefault(); closeMacros(); return; }
    if (S.cust && root.clientWidth < 1060) { e.preventDefault(); S.cust = false; root.removeAttribute('data-cust'); return; }
    if (root.clientWidth < 760 && root.dataset.view === 'ticket') { e.preventDefault(); setView('queue'); const r = $(`.apc-desk__row[data-id="${S.sel}"]`, listEl); if (r) r.focus(); return; }
  }
  if (typing(t) || mod || e.altKey) return;
  const k = e.key.toLowerCase();
  if (k === 'j' || k === 'k') {
    e.preventDefault();
    const list = visibleTickets();
    const i = list.findIndex((x) => x.id === S.sel);
    const n = list[Math.max(0, Math.min(list.length - 1, i + (k === 'j' ? 1 : -1)))];
    if (n) select(n.id, { focusList: true });
  } else if (k === 'r' || k === 'n') {
    e.preventDefault();
    if (root.clientWidth < 760) setView('ticket');
    setMode(k === 'r' ? 'reply' : 'note');
    ta.focus();
  } else if (k === '/') { e.preventDefault(); search.focus(); }
});

/* one clock for every SLA ring; it sleeps while the desk is off screen or the tab is hidden */
function tick() {
  $$('.apc-desk__row', listEl).forEach((r) => {
    const t = tk(+r.dataset.id);
    const ring = $('.apc-desk__sla', r);
    if (!t || !ring) return;
    const x = sla(t);
    if (x.s === 'none') return;
    if (ring.dataset.s !== x.s) ring.dataset.s = x.s;
    ring.style.setProperty('--apc-desk-p', x.p.toFixed(4));
    ring.textContent = x.label;
    ring.setAttribute('aria-label', x.s === 'bad' ? `SLA breached ${x.label.slice(1)} ago` : `${x.label} left on SLA`);
  });
  renderBreach();
}
const clock = setInterval(() => {
  if (!root.isConnected) return clearInterval(clock);
  if (!S.visible || document.hidden) return;
  tick();
}, 1000);
const io = new IntersectionObserver((en) => {
  if (!root.isConnected) { io.disconnect(); return; }
  S.visible = en[en.length - 1].isIntersecting;
  if (S.visible) tick();
});
io.observe(root);

setMode('reply');
renderList();
select(S.sel);

