/* Video call. Re-theme with --apc-call-bg, -ink, -accent (speaking) and -danger (and -h for height). */
@property --apc-call-lv { syntax: "<number>"; inherits: true; initial-value: 0; }

.apc-call {
  --apc-call-bg: oklch(0.16 0.004 95);
  --apc-call-ink: oklch(0.96 0.006 95);
  --apc-call-accent: oklch(0.88 0.19 126);
  --apc-call-danger: oklch(0.63 0.21 26);

  --apc-call-tile: color-mix(in oklch, var(--apc-call-ink) 7%, var(--apc-call-bg));
  --apc-call-raise: color-mix(in oklch, var(--apc-call-ink) 11%, var(--apc-call-bg));
  --apc-call-raise2: color-mix(in oklch, var(--apc-call-ink) 17%, var(--apc-call-bg));
  --apc-call-line: color-mix(in oklch, var(--apc-call-ink) 10%, transparent);
  --apc-call-line2: color-mix(in oklch, var(--apc-call-ink) 18%, transparent);
  --apc-call-muted: color-mix(in oklch, var(--apc-call-ink) 64%, var(--apc-call-bg));
  --apc-call-faint: color-mix(in oklch, var(--apc-call-ink) 42%, var(--apc-call-bg));
  --apc-call-hand: oklch(0.86 0.15 85);
  --apc-call-ease: cubic-bezier(.2, .75, .2, 1);
  --apc-call-out: cubic-bezier(.3, .7, 0, 1);
  --apc-call-spring: linear(0, 0.07 2.6%, 0.28 6.6%, 0.67 13.4%, 0.94 20%, 1.06 27%, 1.08 33%, 1.05 41%, 1.01 52%, 0.997 66%, 1);

  position: relative;
  isolation: isolate;
  width: 100%;
  height: var(--apc-call-h, 680px);
  container-type: inline-size;
  container-name: apc-call;
  overflow: hidden;
  overflow: clip;
  border-radius: 18px;
  background: var(--apc-call-bg);
  color: var(--apc-call-ink);
  font: 400 14px/1.45 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  -webkit-font-smoothing: antialiased;
  color-scheme: dark;
  accent-color: var(--apc-call-accent);
}
:where(.apc-call) *, :where(.apc-call) *::before, :where(.apc-call) *::after { box-sizing: border-box; }
:where(.apc-call) :is(button, input) { font: inherit; color: inherit; }
:where(.apc-call) button { background: none; border: 0; padding: 0; cursor: pointer; }
:where(.apc-call) :is(ul, ol) { list-style: none; margin: 0; padding: 0; }
:where(.apc-call) :is(h3, p) { margin: 0; }
:where(.apc-call) svg { width: 20px; height: 20px; fill: none; stroke: currentColor; stroke-width: 1.75; stroke-linecap: round; stroke-linejoin: round; flex: none; }
:where(.apc-call) :focus-visible { outline: 2px solid var(--apc-call-accent); outline-offset: 2px; }
.apc-call [hidden] { display: none !important; }
.apc-call__sr { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }

.apc-call__app {
  display: grid; height: 100%;
  grid-template-columns: minmax(0, 1fr) 0px;
  grid-template-rows: auto minmax(0, 1fr) auto;
  grid-template-areas: "top top" "stage panel" "bar bar";
}
.apc-call[data-panel] .apc-call__app { grid-template-columns: minmax(0, 1fr) 330px; }
.apc-call__top { grid-area: top; }
.apc-call__stage, .apc-call__caps { grid-area: stage; }
.apc-call__panel { grid-area: panel; }
.apc-call__bar { grid-area: bar; }

/* ---------- top ---------- */
.apc-call__top { display: flex; align-items: center; justify-content: space-between; gap: 12px; padding: 14px 18px 8px; min-width: 0; }
.apc-call__meet { display: flex; align-items: center; gap: 12px; min-width: 0; }
.apc-call__meet div { display: grid; min-width: 0; line-height: 1.25; }
.apc-call__meet b { font-size: 15px; font-weight: 720; letter-spacing: -0.015em; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.apc-call__meet small { font-size: 12.5px; color: var(--apc-call-faint); white-space: nowrap; }
.apc-call__rec { display: inline-flex; align-items: center; gap: 6px; height: 24px; padding: 0 9px 0 8px; border-radius: 7px; font-size: 11px; font-weight: 800; letter-spacing: .08em; color: var(--apc-call-danger); background: color-mix(in oklch, var(--apc-call-danger) 14%, transparent); flex: none; }
.apc-call__rec i { width: 8px; height: 8px; border-radius: 50%; background: currentColor; animation: apc-call-blink 1.6s var(--apc-call-ease) infinite; }
.apc-call__timer { font: 600 13px/1 ui-monospace, Menlo, monospace; font-variant-numeric: tabular-nums; color: var(--apc-call-muted); padding: 6px 10px; border-radius: 8px; background: var(--apc-call-tile); flex: none; }

/* ---------- stage: tiles are absolutely placed by a layout solver, moved with FLIP ---------- */
.apc-call__stage { position: relative; min-height: 0; margin: 4px 12px 0; }
.apc-call__tile {
  --apc-call-lv: 0;
  position: absolute; left: 0; top: 0; container-type: inline-size; container-name: apc-call-tile; transform-origin: 0 0;
  border-radius: clamp(8px, 4cqi, 16px); overflow: hidden; background: var(--apc-call-tile);
  box-shadow: 0 0 0 calc(1px + var(--apc-call-lv) * 3px) color-mix(in oklch, var(--apc-call-accent) calc(var(--apc-call-lv) * 100%), transparent),
              0 0 calc(var(--apc-call-lv) * 26px) color-mix(in oklch, var(--apc-call-accent) calc(var(--apc-call-lv) * 45%), transparent);
  transition: --apc-call-lv .14s linear;
  will-change: transform;
}
.apc-call__tile[data-active] { box-shadow: 0 0 0 calc(2px + var(--apc-call-lv) * 3px) var(--apc-call-accent), 0 0 calc(8px + var(--apc-call-lv) * 26px) color-mix(in oklch, var(--apc-call-accent) 40%, transparent); }
.apc-call__feed {
  position: absolute; inset: 0;
  background:
    radial-gradient(60% 70% at 78% 18%, oklch(0.7 0.06 var(--h) / .55), transparent 70%),
    linear-gradient(90deg, transparent 8%, oklch(0.3 0.03 var(--h) / .6) 8% 9%, transparent 9%),
    linear-gradient(172deg, oklch(0.44 0.04 var(--h)), oklch(0.24 0.03 var(--h)) 70%);
}
.apc-call__feed::before { content: ""; position: absolute; right: 12%; top: 10%; width: 24%; height: 42%; border-radius: 4px; background: linear-gradient(oklch(0.86 0.04 calc(var(--h) + 40) / .6), oklch(0.7 0.04 var(--h) / .25)); filter: blur(6px); }
.apc-call__feed::after { content: ""; position: absolute; inset: 0; background: radial-gradient(120% 100% at 50% 40%, transparent 55%, oklch(0.1 0.01 var(--h) / .55)); }
.apc-call__fig { position: absolute; left: 50%; bottom: -1%; width: 56%; height: auto; translate: -50% 0; overflow: visible; stroke: none; filter: drop-shadow(0 6px 14px oklch(0.1 0.02 var(--h) / .45)); }
.apc-call__fig .apc-call__head { transform-box: fill-box; transform-origin: 50% 100%; animation: apc-call-sway 7s var(--apc-call-ease) infinite alternate; animation-delay: var(--d); translate: 0 calc(var(--apc-call-lv) * -1.6px); rotate: calc(var(--apc-call-lv) * 2deg); }
.apc-call__fig .apc-call__body { animation: apc-call-breathe 4.8s var(--apc-call-ease) infinite; animation-delay: var(--d); transform-box: fill-box; transform-origin: 50% 100%; }
.apc-call__avatar { position: absolute; inset: 0; display: none; place-items: center; background: radial-gradient(circle at 50% 45%, color-mix(in oklch, var(--apc-call-ink) 8%, var(--apc-call-tile)), var(--apc-call-tile) 60%); }
.apc-call__avatar span {
  display: grid; place-items: center; width: clamp(40px, 26cqi, 120px); aspect-ratio: 1; border-radius: 50%;
  font-size: clamp(14px, 8.5cqi, 40px); font-weight: 700; letter-spacing: .02em; color: oklch(0.95 0.03 var(--h));
  background: linear-gradient(150deg, oklch(0.55 0.11 var(--h)), oklch(0.38 0.09 calc(var(--h) + 30)));
  box-shadow: 0 0 0 calc(var(--apc-call-lv) * 10px) color-mix(in oklch, var(--apc-call-accent) 35%, transparent), 0 0 0 calc(var(--apc-call-lv) * 20px) color-mix(in oklch, var(--apc-call-accent) 12%, transparent);
}
.apc-call__tile[data-cam="off"] .apc-call__feed { display: none; }
.apc-call__tile[data-cam="off"] .apc-call__avatar { display: grid; }
.apc-call__tag {
  position: absolute; left: 8px; bottom: 8px; display: inline-flex; align-items: center; gap: 6px; max-width: calc(100% - 16px); height: clamp(22px, 9cqi, 28px); padding: 0 9px 0 6px; border-radius: 8px;
  font-size: clamp(10.5px, 4.4cqi, 13px); font-weight: 600; background: oklch(0.12 0.005 95 / .62); backdrop-filter: blur(8px);
}
.apc-call__tag span { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.apc-call__tag svg { width: 14px; height: 14px; }
.apc-call__tag .apc-call__muted { color: var(--apc-call-danger); }
.apc-call__eq { display: inline-flex; align-items: center; gap: 1.5px; height: 12px; width: 14px; justify-content: center; }
.apc-call__eq i { width: 3px; height: 12px; border-radius: 2px; background: var(--apc-call-accent); scale: 1 calc(.22 + var(--apc-call-lv) * var(--k)); transition: scale .12s linear; }
.apc-call__tile[data-mic="off"] .apc-call__eq { display: none; }
.apc-call__tile:not([data-mic="off"]) .apc-call__muted { display: none; }
.apc-call__hand { position: absolute; left: 8px; top: 8px; display: inline-flex; align-items: center; gap: 4px; height: 26px; padding: 0 8px 0 6px; border-radius: 8px; font-size: 12px; font-weight: 750; color: oklch(0.25 0.05 80); background: var(--apc-call-hand); animation: apc-call-wave .9s var(--apc-call-spring) both; }
.apc-call__hand svg { width: 15px; height: 15px; }
.apc-call__pin { position: absolute; right: 8px; top: 8px; display: grid; place-items: center; width: 32px; height: 32px; border-radius: 9px; background: oklch(0.12 0.005 95 / .62); backdrop-filter: blur(8px); opacity: 0; transition: opacity .18s, background-color .18s; }
.apc-call__tile:is(:hover, :focus-within) .apc-call__pin, .apc-call__pin[aria-pressed="true"] { opacity: 1; }
.apc-call__pin[aria-pressed="true"] { color: var(--apc-call-bg); background: var(--apc-call-accent); }
.apc-call__pin svg { width: 16px; height: 16px; }
.apc-call__self { position: absolute; right: 8px; bottom: 8px; height: 20px; padding: 0 7px; border-radius: 6px; display: inline-grid; place-items: center; font-size: 10.5px; font-weight: 700; letter-spacing: .04em; text-transform: uppercase; background: oklch(0.12 0.005 95 / .62); }
@container apc-call-tile (width < 170px) {
  .apc-call__tag span, .apc-call__self { display: none; }
  .apc-call__tag { padding: 0 6px; }
}
.apc-call__float { position: absolute; left: calc(50% + var(--x)); bottom: 18%; display: grid; place-items: center; width: 44px; height: 44px; margin-left: -22px; border-radius: 50%; color: var(--c); background: oklch(0.12 0.005 95 / .55); backdrop-filter: blur(6px); pointer-events: none; animation: apc-call-float 2.4s var(--apc-call-out) forwards; }
.apc-call__float svg { width: 24px; height: 24px; stroke-width: 2; fill: color-mix(in oklch, var(--c) 30%, transparent); }

.apc-call__caps {
  align-self: end; justify-self: center; z-index: 5; width: min(720px, calc(100% - 48px)); margin-bottom: var(--apc-call-capsoff, 16px); padding: 10px 16px; border-radius: 12px;
  font-size: clamp(14px, 1.6cqi, 17px); line-height: 1.45; text-wrap: pretty; background: oklch(0.1 0.004 95 / .78); backdrop-filter: blur(10px); pointer-events: none;
  transition: opacity .25s, translate .35s var(--apc-call-out);
}
.apc-call__caps:empty, .apc-call[data-caps="off"] .apc-call__caps { opacity: 0; translate: 0 8px; }
.apc-call__caps b { font-weight: 700; color: var(--apc-call-accent); margin-right: 6px; }
.apc-call__caps span { animation: apc-call-word .3s var(--apc-call-ease) both; }

/* ---------- control bar ---------- */
.apc-call__bar { display: flex; align-items: flex-start; justify-content: center; gap: 6px; padding: 10px 12px 12px; }
.apc-call__ctl { position: relative; display: grid; justify-items: center; gap: 4px; min-width: 58px; font-size: 11px; font-weight: 600; color: var(--apc-call-muted); }
.apc-call__ctl > span:first-child {
  display: grid; place-items: center; width: 44px; height: 44px; border-radius: 14px; color: var(--apc-call-ink); background: var(--apc-call-raise);
  transition: background-color .2s, color .2s, scale .3s var(--apc-call-spring), border-radius .3s var(--apc-call-spring);
}
.apc-call__ctl:hover > span:first-child { background: var(--apc-call-raise2); }
.apc-call__ctl:active > span:first-child { scale: .92; }
.apc-call__ctl[aria-pressed="true"] > span:first-child { color: var(--apc-call-bg); background: var(--apc-call-ink); border-radius: 22px; }
.apc-call__ctl[data-off="true"] > span:first-child { color: white; background: var(--apc-call-danger); }
.apc-call__ctl[data-key="h"][aria-pressed="true"] > span:first-child { background: var(--apc-call-hand); color: oklch(0.25 0.05 80); }
.apc-call__ctl kbd { font: 600 10px/1 ui-monospace, Menlo, monospace; color: var(--apc-call-faint); }
.apc-call__ctl b { position: absolute; top: -3px; right: 4px; min-width: 18px; height: 18px; padding: 0 5px; border-radius: 9px; display: grid; place-items: center; font-size: 10.5px; font-weight: 800; color: var(--apc-call-bg); background: var(--apc-call-accent); animation: apc-call-pop .45s var(--apc-call-spring) both; }
.apc-call__ctl--leave > span:first-child { width: 64px; color: white; background: var(--apc-call-danger); border-radius: 22px; }
.apc-call__ctl--leave:hover > span:first-child { background: color-mix(in oklch, var(--apc-call-danger) 85%, white); }
.apc-call__ctl--more { display: none; }
.apc-call__sep { width: 1px; height: 36px; margin: 4px 6px 0; background: var(--apc-call-line2); }

.apc-call__more, .apc-call__reacts {
  position: absolute; z-index: 30; padding: 6px; border-radius: 14px; background: var(--apc-call-raise);
  box-shadow: 0 0 0 1px var(--apc-call-line2), 0 24px 50px -16px black;
  transform-origin: 50% 100%; transition: opacity .16s, scale .3s var(--apc-call-spring); @starting-style { opacity: 0; scale: .9; }
}
.apc-call__reacts { display: flex; gap: 2px; }
.apc-call__reacts button { display: grid; place-items: center; width: 42px; height: 42px; border-radius: 11px; color: var(--c); transition: background-color .15s, scale .3s var(--apc-call-spring); }
.apc-call__reacts button:is(:hover, :focus-visible) { background: color-mix(in oklch, var(--c) 18%, transparent); scale: 1.12; outline: none; }
.apc-call__reacts svg { width: 22px; height: 22px; stroke-width: 2; }
.apc-call__more { width: 220px; }
.apc-call__more button { display: flex; align-items: center; gap: 10px; width: 100%; height: 38px; padding: 0 10px; border-radius: 9px; font-size: 14px; text-align: left; }
