/* Spatial voice room. Re-theme with --apc-room-bg, -ink, -accent (voices), -quiet and -stage (and -h for height). */
.apc-room {
  --apc-room-bg: oklch(0.19 0.017 55);
  --apc-room-ink: oklch(0.95 0.015 80);
  --apc-room-accent: oklch(0.83 0.15 74);
  --apc-room-quiet: oklch(0.78 0.08 190);
  --apc-room-stage: oklch(0.74 0.14 18);

  --apc-room-wood: color-mix(in oklab, var(--apc-room-ink) 7%, var(--apc-room-bg));
  --apc-room-wood2: color-mix(in oklab, var(--apc-room-ink) 10%, var(--apc-room-bg));
  --apc-room-panel: color-mix(in oklab, var(--apc-room-ink) 4%, var(--apc-room-bg));
  --apc-room-raise: color-mix(in oklab, var(--apc-room-ink) 12%, var(--apc-room-bg));
  --apc-room-line: color-mix(in oklch, var(--apc-room-ink) 10%, transparent);
  --apc-room-line2: color-mix(in oklch, var(--apc-room-ink) 18%, transparent);
  --apc-room-muted: color-mix(in oklab, var(--apc-room-ink) 64%, var(--apc-room-bg));
  --apc-room-faint: color-mix(in oklab, var(--apc-room-ink) 42%, var(--apc-room-bg));
  --apc-room-ease: cubic-bezier(.2, .75, .2, 1);
  --apc-room-out: cubic-bezier(.3, .7, 0, 1);
  --apc-room-spring: linear(0, 0.07 2.6%, 0.28 6.6%, 0.67 13.4%, 0.94 20%, 1.06 27%, 1.08 33%, 1.05 41%, 1.01 52%, 0.997 66%, 1);

  position: relative;
  isolation: isolate;
  width: 100%;
  height: var(--apc-room-h, 680px);
  container-type: inline-size;
  container-name: apc-room;
  overflow: hidden;
  overflow: clip;
  border-radius: 18px;
  background: var(--apc-room-bg);
  color: var(--apc-room-ink);
  font: 400 14px/1.45 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  -webkit-font-smoothing: antialiased;
  color-scheme: dark;
  accent-color: var(--apc-room-accent);
}
:where(.apc-room) *, :where(.apc-room) *::before, :where(.apc-room) *::after { box-sizing: border-box; }
:where(.apc-room) button { font: inherit; color: inherit; background: none; border: 0; padding: 0; cursor: pointer; }
:where(.apc-room) :is(ul, ol) { list-style: none; margin: 0; padding: 0; }
:where(.apc-room) p { margin: 0; }
:where(.apc-room svg:not(.apc-room__plan, .apc-room__links)) { width: 18px; height: 18px; fill: none; stroke: currentColor; stroke-width: 1.75; stroke-linecap: round; stroke-linejoin: round; flex: none; }
:where(.apc-room) :focus-visible { outline: 2px solid var(--apc-room-accent); outline-offset: 2px; }
.apc-room [hidden] { display: none !important; }
.apc-room__kbd { display: inline-grid; place-items: center; min-width: 18px; height: 18px; padding: 0 4px; border-radius: 5px; font: 600 10.5px/1 ui-monospace, Menlo, monospace; color: var(--apc-room-muted); background: var(--apc-room-raise); box-shadow: inset 0 -1px 0 color-mix(in oklch, black 40%, transparent), 0 0 0 1px var(--apc-room-line2); }

