.apc-room__links line { stroke: var(--apc-room-accent); stroke-width: 2.5; stroke-linecap: round; stroke-dasharray: 2 9; animation: apc-room-flow 1.1s linear infinite; vector-effect: non-scaling-stroke; }
.apc-room__links .apc-room__reach { fill: color-mix(in oklch, var(--apc-room-accent) 4%, transparent); stroke: color-mix(in oklch, var(--apc-room-accent) 30%, transparent); stroke-width: 1.5; stroke-dasharray: 3 8; vector-effect: non-scaling-stroke; }

