.apc-room__help span { display: inline-flex; align-items: center; gap: 3px; }
.apc-room__help .apc-room__kbd + .apc-room__kbd { margin-left: 1px; }

/* ---------- side ---------- */
.apc-room__side { display: grid; grid-template-columns: minmax(0, 1fr); grid-template-rows: auto auto minmax(0, 1fr); min-height: 0; margin: 0 12px 12px 0; border-radius: 16px; background: var(--apc-room-panel); box-shadow: inset 0 0 0 1px var(--apc-room-line); overflow: hidden; }
.apc-room__me { display: grid; grid-template-columns: auto minmax(0, 1fr); gap: 4px 10px; align-items: center; padding: 14px 14px 12px; border-bottom: 1px solid var(--apc-room-line); }
