const target = $('.apc-room__target');
const ear = $('.apc-room__ear');
const feed = $('.apc-room__feed');
const meCard = $('.apc-room__me');
const zoneChip = $('.apc-room__zone');
const nCount = $('.apc-room__n');
const toast = $('.apc-room__toast');
const ini = (n) => n.split(' ').map((w) => w[0]).join('').slice(0, 2);
const later = (fn, ms) => setTimeout(() => { if (root.isConnected) fn(); }, ms);

/* ---------------- floor plan ---------------- */
plan.innerHTML = `
  <rect class="apc-room__stage" x="380" y="26" width="240" height="124" rx="16"/>
  <text class="apc-room__zlabel apc-room__zlabel--stage" x="398" y="50">Stage · heard by all</text>
  <rect class="apc-room__quiet" x="30" y="388" width="232" height="204" rx="18"/>
  <text class="apc-room__zlabel apc-room__zlabel--quiet" x="46" y="412">Quiet library</text>
  <rect class="apc-room__shelf" x="38" y="430" width="14" height="150" rx="3"/>
  <rect class="apc-room__shelf" x="60" y="572" width="150" height="12" rx="3"/>
  <rect class="apc-room__sofa" x="176" y="470" width="58" height="52" rx="16"/>
  <rect class="apc-room__hearth" x="70" y="18" width="110" height="30" rx="5"/>
  <ellipse class="apc-room__fire" cx="125" cy="40" rx="30" ry="10"/>
  <rect class="apc-room__rug" x="62" y="84" width="268" height="206" rx="34"/>
  <text class="apc-room__zlabel" x="80" y="110">Fireplace lounge</text>
  <rect class="apc-room__sofa" x="80" y="124" width="40" height="120" rx="14"/>
  <rect class="apc-room__sofa" x="130" y="262" width="150" height="34" rx="14"/>
  <circle class="apc-room__table" cx="198" cy="190" r="32"/>
  <line class="apc-room__window" x1="700" y1="12" x2="770" y2="12"/>
  <line class="apc-room__window" x1="790" y1="12" x2="860" y2="12"/>
  <line class="apc-room__window" x1="880" y1="12" x2="950" y2="12"/>
  <rect class="apc-room__rug" x="676" y="60" width="276" height="236" rx="30"/>
  <text class="apc-room__zlabel" x="694" y="86">Window bar</text>
  <rect class="apc-room__table" x="696" y="98" width="236" height="26" rx="9"/>
  <circle class="apc-room__table" cx="812" cy="196" r="24"/>
  <circle class="apc-room__table" cx="900" cy="256" r="22"/>
  <rect class="apc-room__rug" x="304" y="378" width="392" height="190" rx="30"/>
  <text class="apc-room__zlabel" x="322" y="402">Long table</text>
  <rect class="apc-room__table" x="352" y="434" width="300" height="56" rx="14"/>
  <circle class="apc-room__plant" cx="975" cy="590" r="20"/>
  <circle class="apc-room__plant" cx="360" cy="40" r="16"/>
  <circle class="apc-room__plant" cx="645" cy="40" r="16"/>
  <circle class="apc-room__plant" cx="975" cy="350" r="15"/>`;

/* ---------------- people ---------------- */
const ME = PEOPLE.find((p) => p.me);
const others = PEOPLE.filter((p) => !p.me);
PEOPLE.forEach((p) => { p.lv = 0; p.vol = p.me ? 1 : 0; p.tx = null; p.ty = null; p.speaking = false; });
layer.innerHTML = PEOPLE.map((p) => `<button class="apc-room__p" type="button" data-id="${p.id}" ${p.me ? 'data-me' : ''} style="--h:${p.h}" aria-label="${esc(p.me ? 'You, Jules Park. Drag to walk.' : `${p.name}, ${p.role}. Walk over.`)}"><span class="apc-room__halo"></span><span class="apc-room__face">${ini(p.name)}</span><span class="apc-room__label">${esc(p.me ? 'You' : p.name.split(' ')[0])}</span></button>`).join('');
PEOPLE.forEach((p) => { p.el = $(`.apc-room__p[data-id="${p.id}"]`, layer); });
links.innerHTML = '<circle class="apc-room__reach" r="300"/>' + others.map((p) => `<line data-id="${p.id}" opacity="0"/>`).join('');
const reach = $('.apc-room__reach', links);
others.forEach((p) => { p.line = $(`line[data-id="${p.id}"]`, links); });

let scale = 1;
const ro = new ResizeObserver(() => {
  if (!root.isConnected) { ro.disconnect(); return; }
  scale = floor.clientWidth / FW;
  PEOPLE.forEach((p) => { p.px = null; });
  draw(true);
});
ro.observe(floor);

/* ---------------- hearing ---------------- */
function volumeOf(p) {
  const zp = zoneOf(p.x, p.y).id, zm = zoneOf(ME.x, ME.y).id;
  if ((zm === 'library') !== (zp === 'library')) return 0;
  if (zp === 'stage' && zm !== 'library') return 1;
  const d = Math.hypot(p.x - ME.x, p.y - ME.y);
  if (d >= CUT1) return 0;
  let v = 1 / (1 + (d / R0) ** 2);
  if (d > CUT0) v *= 1 - (d - CUT0) / (CUT1 - CUT0);
  return v;
}
const where = (p, v) => (zoneOf(p.x, p.y).id === 'stage' ? 'on stage' : v > 0.45 ? 'right here' : v > 0.2 ? 'nearby' : 'across the room');

/* ---------------- conversations ---------------- */
const groups = Object.entries(TALK).map(([id, g]) => ({ id, ...g, i: 0, until: 0, next: 800 + Math.random() * 2000, speaker: null }));
let clock = 0;
function stepTalk(dt) {
  clock += dt;
  groups.forEach((g) => {
    if (g.speaker && clock >= g.until) { g.speaker.speaking = false; g.speaker = null; g.next = clock + g.gap[0] + Math.random() * (g.gap[1] - g.gap[0]); }
    if (!g.speaker && clock >= g.next) {
      const [who, text] = g.lines[g.i % g.lines.length];
      g.i++;
      const p = others.find((x) => x.id === who);
      p.speaking = true;
      g.speaker = p;
      g.until = clock + 900 + text.split(' ').length * 330;
      caption(p, text);
    }
  });
  PEOPLE.forEach((p) => {
    const talking = p.me ? S.talking && !S.muted : p.speaking;
    const t = talking ? 0.35 + 0.65 * Math.abs(Math.sin(clock / 80 + p.h) * Math.sin(clock / 29 + p.h)) : 0;
    p.lv += (t - p.lv) * (t > p.lv ? 0.45 : 0.15);
  });
}
function caption(p, text) {
  const v = volumeOf(p);
  if (v < 0.06) { S.feedOut++; return; }
  const stage = zoneOf(p.x, p.y).id === 'stage';
  const li = document.createElement('li');
  li.className = 'apc-room__cap';
  if (stage) li.setAttribute('data-stage', '');
  li.style.setProperty('--vol', v.toFixed(2));
  li.style.setProperty('--h', p.h);
  li.innerHTML = `<header><b>${esc(p.name)}</b><span>${where(p, v)} · ${Math.round(v * 100)}%</span></header><p>${esc(text)}</p>`;
  const empty = $('.apc-room__empty', feed);
  if (empty) empty.remove();
  feed.prepend(li);
  while (feed.children.length > 8) feed.lastElementChild.remove();
}

/* ---------------- movement ---------------- */
const clampX = (x) => Math.max(24, Math.min(FW - 24, x));
const clampY = (y) => Math.max(24, Math.min(FH - 24, y));
function walkTo(p, x, y) { p.tx = clampX(x); p.ty = clampY(y); if (p.me) showTarget(); }
function showTarget() {
  if (ME.tx == null) { target.removeAttribute('data-on'); return; }
  target.style.transform = `translate(${ME.tx * scale}px, ${ME.ty * scale}px)`;
  target.setAttribute('data-on', '');
}
function stepMove(dt) {
  const s = dt / 1000;
  let kx = 0, ky = 0;
  if (S.keys.has('left')) kx -= 1;
  if (S.keys.has('right')) kx += 1;
  if (S.keys.has('up')) ky -= 1;
  if (S.keys.has('down')) ky += 1;
  if (kx || ky) {
    const n = Math.hypot(kx, ky);
    ME.x = clampX(ME.x + (kx / n) * 230 * s);
    ME.y = clampY(ME.y + (ky / n) * 230 * s);
    ME.tx = null; showTarget();
  }
  PEOPLE.forEach((p) => {
    if (p.tx == null) return;
    const dx = p.tx - p.x, dy = p.ty - p.y, d = Math.hypot(dx, dy);
    if (d < 1.5) { p.x = p.tx; p.y = p.ty; p.tx = null; if (p.me) showTarget(); return; }
    const v = Math.min(p.me ? 300 : 120, d * 5) * s;
    p.x += (dx / d) * Math.min(v, d);
    p.y += (dy / d) * Math.min(v, d);
  });
}

/* ---------------- drawing ---------------- */
let lastPanel = 0, lastOrder = '';
function draw(force) {
  PEOPLE.forEach((p) => {
    if (!p.me) {
      const v = volumeOf(p);
      p.vol = v;
      const far = v < 0.06;
      if (far !== p.far) { p.far = far; p.el.toggleAttribute('data-far', far); }
      const op = far ? 0 : Math.min(0.9, 0.12 + v);
      p.line.setAttribute('x1', ME.x); p.line.setAttribute('y1', ME.y);
      p.line.setAttribute('x2', p.x); p.line.setAttribute('y2', p.y);
      p.line.setAttribute('opacity', op.toFixed(2));
    }
    if (force || p.px !== p.x || p.py !== p.y) {
      p.el.style.transform = `translate(${(p.x * scale).toFixed(1)}px, ${(p.y * scale).toFixed(1)}px)`;
      p.px = p.x; p.py = p.y;
    }
    p.el.style.setProperty('--lv', p.lv.toFixed(3));
    p.el.style.setProperty('--vol', p.vol.toFixed(3));
  });
  reach.setAttribute('cx', ME.x);
  reach.setAttribute('cy', ME.y);
  const z = zoneOf(ME.x, ME.y);
  if (z.id !== S.zone) zoneChanged(z);
}
function zoneChanged(z) {
  const first = S.zone == null;
  S.zone = z.id;
  zoneChip.textContent = z.name;
  zoneChip.dataset.z = z.id;
  reach.style.display = z.id === 'stage' || z.id === 'library' ? 'none' : '';
  renderMe();
  if (first) return;
  if (z.id === 'library') say('Quiet library — only people inside can hear you, and you can’t hear the room');
  else if (z.id === 'stage') say('On stage — everyone in the hall can hear you');
}
function panel(now) {
  if (now - lastPanel < 200) return;
  lastPanel = now;
  const list = [...others].sort((a, b) => b.vol - a.vol);
  const order = list.map((p) => p.id + (p.vol < 0.06 ? '-' : '')).join();
  const audible = list.filter((p) => p.vol >= 0.06);
  nCount.textContent = audible.length;
  if (order !== lastOrder) {
    const before = new Map($$('.apc-room__row', ear).map((r) => [r.dataset.id, r.getBoundingClientRect().top]));
    lastOrder = order;
    const far = list.filter((p) => p.vol < 0.06);
    ear.innerHTML = (audible.length ? '' : '<li class="apc-room__empty">Nobody in earshot. Walk towards a group to join in.</li>')
      + audible.map(rowHTML).join('')
      + (far.length ? `<li class="apc-room__sub">Out of earshot · ${far.length}</li>` + far.map(rowHTML).join('') : '');
    if (!RM.matches) $$('.apc-room__row', ear).forEach((r) => {
      const o = before.get(r.dataset.id);
      if (o == null) return;
      const d = o - r.getBoundingClientRect().top;
      if (Math.abs(d) > 0.5) r.animate([{ transform: `translateY(${d}px)` }, { transform: 'none' }], { duration: 480, easing: SPRING });
    });
  }
  $$('.apc-room__row', ear).forEach((r) => {
    const p = others.find((x) => x.id === r.dataset.id);
    r.style.setProperty('--vol', p.vol.toFixed(3));
    r.style.setProperty('--lv', p.lv.toFixed(2));
    const sm = $('small', r);
    const txt = p.vol < 0.06 ? zoneOf(p.x, p.y).name : `${Math.round(p.vol * 100)}%`;
    if (sm.textContent !== txt) sm.textContent = txt;
  });
}
const rowHTML = (p) => `<li><button class="apc-room__row" type="button" data-id="${p.id}" data-walk="${p.id}" ${p.vol < 0.06 ? 'data-far' : ''} ${zoneOf(p.x, p.y).id === 'stage' ? 'data-stage' : ''} style="--h:${p.h}" aria-label="${esc(p.name)}, ${p.vol < 0.06 ? 'out of earshot' : Math.round(p.vol * 100) + ' percent volume'}. Walk over."><span class="apc-room__face">${ini(p.name)}</span><b>${esc(p.name)}</b><small></small><span class="apc-room__meter"><i></i></span></button></li>`;
function renderMe() {
  const onStage = S.zone === 'stage';
  meCard.innerHTML = `<span class="apc-room__face" style="--h:${ME.h}">${ini(ME.name)}</span><div><b>Jules Park (you)</b><small>${esc(zoneOf(ME.x, ME.y).name)} · ${S.muted ? 'muted' : 'mic on'}</small></div>
    <div class="apc-room__acts"><button class="apc-room__btn" type="button" data-act="mute" aria-pressed="${S.muted}" aria-keyshortcuts="M">${ic(S.muted ? 'micoff' : 'mic')}<span>${S.muted ? 'Unmute' : 'Mute'}</span><kbd>M</kbd></button>
    <button class="apc-room__btn" type="button" data-act="stage" data-stage="${onStage ? 'on' : 'off'}">${ic('stage')}<span>${onStage ? 'Leave stage' : 'Go to stage'}</span></button></div>`;
  ME.el.toggleAttribute('data-muted', S.muted);
}
let toastT = 0;
function say(t) {
  toast.textContent = t;
  toast.setAttribute('data-show', '');
  clearTimeout(toastT);
  toastT = setTimeout(() => { if (root.isConnected) toast.removeAttribute('data-show'); }, 2600);
}

/* ---------------- loop ---------------- */
let raf = 0, last = 0;
function frame(t) {
  if (!root.isConnected) return;
  raf = 0;
  if (!S.visible || document.hidden) return;
  const dt = Math.min(64, t - (last || t));
  last = t;
  stepTalk(dt);
  stepMove(dt);
  draw(false);
  panel(t);
  raf = requestAnimationFrame(frame);
}
function run() { if (!raf && S.visible) { last = 0; raf = requestAnimationFrame(frame); } }
const io = new IntersectionObserver((en) => {
  if (!root.isConnected) { io.disconnect(); return; }
  S.visible = en[en.length - 1].isIntersecting;
  run();
});
io.observe(root);
const onVis = () => { if (!root.isConnected) { root.ownerDocument.removeEventListener('visibilitychange', onVis); return; } if (!document.hidden) run(); };
root.ownerDocument.addEventListener('visibilitychange', onVis);

/* Lin fetches pizza and comes back; the room keeps moving around you. */
later(() => walkTo(others.find((p) => p.id === 'lin'), 560, 540), 16000);
later(() => walkTo(others.find((p) => p.id === 'lin'), 862, 208), 42000);

/* ---------------- input ---------------- */
const toUnits = (e) => { const r = floor.getBoundingClientRect(); return { x: (e.clientX - r.left) / r.width * FW, y: (e.clientY - r.top) / r.height * FH }; };
floor.addEventListener('pointerdown', (e) => {
  if (e.button !== 0) return;
  const meBtn = e.target.closest('[data-me]');
  if (meBtn) {
    e.preventDefault();
    const u = toUnits(e);
    S.drag = { id: e.pointerId, ox: ME.x - u.x, oy: ME.y - u.y };
    floor.setPointerCapture(e.pointerId);
    ME.tx = null; showTarget();
    floor.focus({ preventScroll: true });
    return;
  }
  S.down = { x: e.clientX, y: e.clientY, onPerson: !!e.target.closest('.apc-room__p') };
});
floor.addEventListener('pointermove', (e) => {
  if (!S.drag || e.pointerId !== S.drag.id) return;
  const u = toUnits(e);
  ME.x = clampX(u.x + S.drag.ox);
  ME.y = clampY(u.y + S.drag.oy);
});
floor.addEventListener('pointerup', (e) => {
  if (S.drag && e.pointerId === S.drag.id) { S.drag = null; return; }
  const d = S.down;
  S.down = null;
  if (!d || d.onPerson || Math.hypot(e.clientX - d.x, e.clientY - d.y) > 6) return;
  const u = toUnits(e);
  walkTo(ME, u.x, u.y);
  floor.focus({ preventScroll: true });
});
floor.addEventListener('pointercancel', () => { S.drag = null; S.down = null; });
function walkToward(p) {
  const dx = ME.x - p.x, dy = ME.y - p.y, d = Math.hypot(dx, dy) || 1;
  walkTo(ME, p.x + (dx / d) * 62, p.y + (dy / d) * 62);
}
root.addEventListener('click', (e) => {
  const w = e.target.closest('[data-walk]');
  if (w) { const p = others.find((x) => x.id === w.dataset.walk); if (p) { walkToward(p); say(`Walking over to ${p.name.split(' ')[0]}`); } return; }
  const person = e.target.closest('.apc-room__p:not([data-me])');
  if (person) { const p = others.find((x) => x.id === person.dataset.id); walkToward(p); return; }
  const tab = e.target.closest('[role="tab"]');
  if (tab) { S.tab = tab.dataset.tab; root.dataset.tab = S.tab; $$('[role="tab"]').forEach((t) => t.setAttribute('aria-selected', t === tab)); if (S.tab === 'feed' && !feed.children.length) feed.innerHTML = `<li class="apc-room__empty">Captions appear here for anyone you can hear.${S.feedOut ? ` ${S.feedOut} line${S.feedOut === 1 ? '' : 's'} so far were out of earshot.` : ''}</li>`; return; }
  const a = e.target.closest('[data-act]');
  if (!a) return;
  if (a.dataset.act === 'mute') { S.muted = !S.muted; renderMe(); $('[data-act="mute"]', meCard).focus(); say(S.muted ? 'You’re muted' : 'Mic on — hold Space to talk'); }
  if (a.dataset.act === 'stage') {
    if (S.zone === 'stage') walkTo(ME, 500, 220); else walkTo(ME, 470 + Math.random() * 60, 110);
    floor.focus({ preventScroll: true });
  }
});
const KEYMAP = { ArrowLeft: 'left', a: 'left', ArrowRight: 'right', d: 'right', ArrowUp: 'up', w: 'up', ArrowDown: 'down', s: 'down' };
root.addEventListener('keydown', (e) => {
  if (e.metaKey || e.ctrlKey || e.altKey) return;
  const inFloor = !!e.target.closest('.apc-room__floor');
  const k = KEYMAP[e.key] || KEYMAP[e.key.toLowerCase()];
  if (k && inFloor) { e.preventDefault(); S.keys.add(k); return; }
  if (e.key === ' ' && (inFloor || e.target === root)) {
    e.preventDefault();
    if (e.repeat) return;
    if (S.muted) say('You’re muted — press M to unmute'); else S.talking = true;
    return;
  }
  if (e.key.toLowerCase() === 'm' && e.target.tagName !== 'INPUT') { e.preventDefault(); S.muted = !S.muted; renderMe(); say(S.muted ? 'You’re muted' : 'Mic on — hold Space to talk'); }
  if (e.key === 'Escape' && ME.tx != null) { ME.tx = null; showTarget(); }
});
root.addEventListener('keyup', (e) => {
  const k = KEYMAP[e.key] || KEYMAP[e.key.toLowerCase()];
  if (k) S.keys.delete(k);
  if (e.key === ' ') S.talking = false;
});
floor.addEventListener('blur', () => { S.keys.clear(); S.talking = false; });

renderMe();
draw(true);
run();

