/* Community forum. Re-theme with --apc-forum-bg, -ink, -accent and -like (and -h for height). */
.apc-forum {
  --apc-forum-bg: oklch(0.975 0.011 88);
  --apc-forum-ink: oklch(0.245 0.02 230);
  --apc-forum-accent: oklch(0.52 0.09 196);
  --apc-forum-like: oklch(0.6 0.19 16);

  --apc-forum-paper: color-mix(in oklab, white 55%, var(--apc-forum-bg));
  --apc-forum-sunk: color-mix(in oklab, var(--apc-forum-ink) 4%, var(--apc-forum-bg));
  --apc-forum-line: color-mix(in oklch, var(--apc-forum-ink) 11%, transparent);
  --apc-forum-line2: color-mix(in oklch, var(--apc-forum-ink) 18%, transparent);
  --apc-forum-muted: color-mix(in oklab, var(--apc-forum-ink) 66%, var(--apc-forum-bg));
  --apc-forum-faint: color-mix(in oklab, var(--apc-forum-ink) 45%, var(--apc-forum-bg));
  --apc-forum-hover: color-mix(in oklch, var(--apc-forum-ink) 5%, transparent);
  --apc-forum-tint: color-mix(in oklab, var(--apc-forum-accent) 10%, var(--apc-forum-paper));
  --apc-forum-deep: color-mix(in oklab, var(--apc-forum-accent) 75%, var(--apc-forum-ink));
  --apc-forum-ok: oklch(0.58 0.13 152);
  --apc-forum-ease: cubic-bezier(.2, .75, .2, 1);
  --apc-forum-out: cubic-bezier(.3, .7, 0, 1);
  --apc-forum-spring: linear(0, 0.07 2.6%, 0.28 6.6%, 0.67 13.4%, 0.94 20%, 1.06 27%, 1.08 33%, 1.05 41%, 1.01 52%, 0.997 66%, 1);

  position: relative;
  isolation: isolate;
  width: 100%;
  height: var(--apc-forum-h, 680px);
  container-type: inline-size;
  overflow: hidden;
  overflow: clip;
  border-radius: 14px;
  background: var(--apc-forum-bg);
  color: var(--apc-forum-ink);
  font: 400 14.5px/1.55 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  -webkit-font-smoothing: antialiased;
  color-scheme: light;
  accent-color: var(--apc-forum-accent);
  box-shadow: inset 0 0 0 1px var(--apc-forum-line);
}
:where(.apc-forum) *, :where(.apc-forum) *::before, :where(.apc-forum) *::after { box-sizing: border-box; }
:where(.apc-forum) :is(button, input, textarea) { font: inherit; color: inherit; }
:where(.apc-forum) button { background: none; border: 0; padding: 0; cursor: pointer; }
:where(.apc-forum) :is(ul, ol) { list-style: none; margin: 0; padding: 0; }
:where(.apc-forum) :is(h2, p, pre, blockquote) { margin: 0; }
:where(.apc-forum) svg { width: 18px; height: 18px; fill: none; stroke: currentColor; stroke-width: 1.75; stroke-linecap: round; stroke-linejoin: round; flex: none; }
:where(.apc-forum) :focus-visible { outline: 2px solid var(--apc-forum-accent); outline-offset: 2px; border-radius: 6px; }
.apc-forum [hidden] { display: none !important; }
.apc-forum__kbd { display: inline-grid; place-items: center; min-width: 18px; height: 18px; padding: 0 4px; border-radius: 5px; font: 600 10.5px/1 ui-monospace, Menlo, monospace; color: var(--apc-forum-muted); background: var(--apc-forum-paper); box-shadow: inset 0 -1px 0 var(--apc-forum-line2), 0 0 0 1px var(--apc-forum-line2); }
.apc-forum__av { --s: 40px; display: inline-grid; place-items: center; width: var(--s); height: var(--s); border-radius: 50%; flex: none; font-size: calc(var(--s) * .36); font-weight: 700; color: oklch(0.36 0.08 var(--h)); background: oklch(0.89 0.06 var(--h)); }

.apc-forum__app { display: grid; height: 100%; grid-template-columns: 370px minmax(0, 1fr); grid-template-areas: "index topic"; }
.apc-forum__index { grid-area: index; }
.apc-forum__topic { grid-area: topic; }

/* ---------- topic index ---------- */
.apc-forum__index { display: grid; grid-template-columns: minmax(0, 1fr); grid-template-rows: auto minmax(0, 1fr); min-height: 0; border-right: 1px solid var(--apc-forum-line); background: var(--apc-forum-sunk); }
.apc-forum__ihead { display: grid; gap: 10px; padding: 16px 14px 10px; border-bottom: 1px solid var(--apc-forum-line); }
.apc-forum__brand { display: flex; align-items: center; gap: 10px; }
.apc-forum__brand div { display: grid; line-height: 1.2; }
.apc-forum__brand b { font-size: 17px; font-weight: 800; letter-spacing: -0.025em; }
.apc-forum__brand small { font-size: 12px; color: var(--apc-forum-faint); font-variant-numeric: tabular-nums; }
.apc-forum__logo { display: grid; place-items: center; width: 34px; height: 34px; border-radius: 10px; color: var(--apc-forum-paper); background: var(--apc-forum-deep); flex: none; }
.apc-forum__logo svg { width: 20px; height: 20px; stroke-width: 1.8; }
.apc-forum__search { display: flex; align-items: center; gap: 8px; height: 34px; padding: 0 10px; border-radius: 9px; background: var(--apc-forum-paper); box-shadow: 0 0 0 1px var(--apc-forum-line2); color: var(--apc-forum-faint); }
.apc-forum__search:focus-within { box-shadow: 0 0 0 1.5px var(--apc-forum-accent); }
.apc-forum__search svg { width: 15px; height: 15px; }
.apc-forum__search input { flex: 1; min-width: 0; border: 0; outline: none; background: none; font-size: 13.5px; }
.apc-forum__sorts { display: flex; gap: 14px; border-bottom: 1px solid var(--apc-forum-line); margin: 0 -14px; padding: 0 14px; }
.apc-forum__sorts button { position: relative; height: 32px; font-size: 13px; font-weight: 650; color: var(--apc-forum-muted); }
.apc-forum__sorts button[aria-selected="true"] { color: var(--apc-forum-ink); }
.apc-forum__sorts button[aria-selected="true"]::after { content: ""; position: absolute; left: 0; right: 0; bottom: -1px; height: 2px; border-radius: 2px; background: var(--apc-forum-accent); animation: apc-forum-grow .35s var(--apc-forum-out) both; }
.apc-forum__cats { display: flex; gap: 6px; overflow-x: auto; scrollbar-width: none; margin: 0 -14px; padding: 0 14px 2px; }
.apc-forum__cats button { display: inline-flex; align-items: center; gap: 6px; height: 26px; padding: 0 9px; border-radius: 99px; font-size: 12px; font-weight: 650; white-space: nowrap; color: var(--apc-forum-muted); box-shadow: inset 0 0 0 1px var(--apc-forum-line2); transition: background-color .18s, color .18s; }
.apc-forum__cats button::before { content: ""; width: 8px; height: 8px; border-radius: 2px; background: var(--c, var(--apc-forum-faint)); }
.apc-forum__cats button[aria-pressed="true"] { color: var(--apc-forum-paper); background: var(--apc-forum-ink); box-shadow: none; }
.apc-forum__topics { overflow: auto; padding: 6px; scrollbar-width: thin; overscroll-behavior: contain; }
.apc-forum__trow {
  position: relative; display: grid; grid-template-columns: minmax(0, 1fr) auto; gap: 4px 10px; width: 100%; padding: 11px 12px; border-radius: 11px; text-align: left;
  transition: background-color .18s, box-shadow .18s; animation: apc-forum-in .4s var(--apc-forum-out) both; animation-delay: calc(var(--i) * 35ms);
}
.apc-forum__trow:hover { background: var(--apc-forum-hover); }
.apc-forum__trow[aria-current="true"] { background: var(--apc-forum-paper); box-shadow: 0 0 0 1px var(--apc-forum-line2), 0 2px 8px -4px var(--apc-forum-line2); }
.apc-forum__ttitle { grid-column: 1 / -1; display: flex; gap: 6px; align-items: flex-start; font-size: 14.5px; font-weight: 680; line-height: 1.35; letter-spacing: -0.008em; text-wrap: pretty; }
.apc-forum__ttitle svg { width: 16px; height: 16px; margin-top: 1px; }
.apc-forum__ttitle .apc-forum__solvedic { color: var(--apc-forum-ok); }
.apc-forum__ttitle .apc-forum__pinic { color: var(--apc-forum-faint); }
.apc-forum__trow[data-read] .apc-forum__ttitle { color: var(--apc-forum-muted); font-weight: 600; }
.apc-forum__tmeta { display: flex; align-items: center; flex-wrap: wrap; gap: 4px 8px; min-width: 0; font-size: 12px; color: var(--apc-forum-faint); }
.apc-forum__cat { display: inline-flex; align-items: center; gap: 5px; font-weight: 650; color: var(--apc-forum-muted); }
.apc-forum__cat::before { content: ""; width: 8px; height: 8px; border-radius: 2px; background: var(--c); }
.apc-forum__tstats { display: flex; align-items: center; gap: 10px; font-size: 12px; color: var(--apc-forum-faint); font-variant-numeric: tabular-nums; white-space: nowrap; justify-self: end; }
.apc-forum__tstats b { color: var(--apc-forum-ink); font-weight: 700; }
.apc-forum__new { position: absolute; top: 10px; right: 10px; height: 20px; padding: 0 7px; border-radius: 10px; display: grid; place-items: center; font-size: 11px; font-weight: 750; font-variant-numeric: tabular-nums; color: var(--apc-forum-paper); background: var(--apc-forum-accent); animation: apc-forum-pop .45s var(--apc-forum-spring) both; }
.apc-forum__trow:has(.apc-forum__new) .apc-forum__ttitle { padding-right: 56px; }
.apc-forum__trow mark, .apc-forum__thead mark { background: color-mix(in oklch, var(--apc-forum-accent) 22%, transparent); color: inherit; border-radius: 3px; }
.apc-forum__none { padding: 30px 14px; text-align: center; font-size: 13.5px; color: var(--apc-forum-faint); text-wrap: balance; }

/* ---------- topic ---------- */
.apc-forum__topic { position: relative; display: grid; grid-template-columns: minmax(0, 1fr) 118px; grid-template-rows: minmax(0, 1fr) auto; grid-template-areas: "scroll tl" "comp tl"; min-width: 0; min-height: 0; background: var(--apc-forum-paper); }
.apc-forum__scroll { grid-area: scroll; position: relative; overflow: auto; overscroll-behavior: contain; scrollbar-width: thin; outline: none; scroll-padding-top: 56px; }
.apc-forum__mini { position: sticky; top: 0; z-index: 6; height: 0; }
.apc-forum__minibar {
  position: absolute; left: 0; right: 0; top: 0; display: flex; align-items: baseline; gap: 10px; height: 48px; padding: 14px 24px 0; overflow: hidden;
  background: color-mix(in oklch, var(--apc-forum-paper) 88%, transparent); backdrop-filter: blur(10px); border-bottom: 1px solid var(--apc-forum-line);
  opacity: 0; translate: 0 -100%; pointer-events: none;
}
.apc-forum__minibar b { font-size: 14px; font-weight: 720; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.apc-forum__minibar span { font-size: 12px; color: var(--apc-forum-faint); white-space: nowrap; }
.apc-forum[data-mini] .apc-forum__minibar { opacity: 1; translate: 0 0; transition: opacity .2s, translate .3s var(--apc-forum-out); }
@supports (animation-timeline: scroll()) {
  .apc-forum__minibar { animation: apc-forum-mini linear both; animation-timeline: scroll(nearest block); animation-range: 70px 150px; }
  .apc-forum[data-mini] .apc-forum__minibar { transition: none; }
}
.apc-forum__thead { width: min(720px, 100%); margin: 0 auto; padding: 26px clamp(16px, 3cqi, 30px) 8px; }
.apc-forum__thead .apc-forum__back { display: none; align-items: center; gap: 4px; margin: -8px 0 10px -6px; height: 30px; padding: 0 8px 0 4px; border-radius: 8px; font-size: 13px; font-weight: 650; color: var(--apc-forum-muted); }
.apc-forum__thead .apc-forum__back:hover { background: var(--apc-forum-hover); }
.apc-forum__thead h2 { font-size: clamp(20px, 2.4cqi, 27px); font-weight: 790; letter-spacing: -0.03em; line-height: 1.18; text-wrap: balance; }
.apc-forum__thead p { display: flex; flex-wrap: wrap; align-items: center; gap: 6px 10px; margin-top: 10px; font-size: 12.5px; color: var(--apc-forum-faint); }
.apc-forum__tag { padding: 1px 7px; border-radius: 5px; font-size: 11.5px; font-weight: 600; color: var(--apc-forum-muted); background: var(--apc-forum-sunk); box-shadow: inset 0 0 0 1px var(--apc-forum-line); }
.apc-forum__posts { width: min(720px, 100%); margin: 0 auto; padding: 4px clamp(16px, 3cqi, 30px) 0; }
.apc-forum__post {
  position: relative; display: grid; grid-template-columns: 44px minmax(0, 1fr); column-gap: 14px; padding: 18px 0 14px; border-top: 1px solid var(--apc-forum-line); outline: none;
}
.apc-forum__post:first-child { border-top: 0; }
.apc-forum__post .apc-forum__av { --s: 44px; }
.apc-forum__post[data-unread]::before { content: ""; position: absolute; left: -14px; top: 22px; width: 4px; height: 26px; border-radius: 4px; background: var(--apc-forum-accent); transition: opacity .8s .4s, scale .8s .4s var(--apc-forum-ease); }
.apc-forum__post[data-unread][data-seen]::before { opacity: 0; scale: 1 .3; }
.apc-forum__post:focus-visible { box-shadow: inset 3px 0 var(--apc-forum-accent); border-radius: 0; }
.apc-forum__post[data-flash] .apc-forum__pbody { animation: apc-forum-flash 1.6s var(--apc-forum-ease); }
.apc-forum__phead { display: flex; flex-wrap: wrap; align-items: baseline; gap: 4px 8px; font-size: 13.5px; }
.apc-forum__phead b { font-weight: 720; }
.apc-forum__flair { padding: 0 6px; border-radius: 5px; font-size: 11px; font-weight: 700; color: var(--apc-forum-deep); background: var(--apc-forum-tint); }
.apc-forum__flair[data-staff] { color: var(--apc-forum-paper); background: var(--apc-forum-deep); }
.apc-forum__phead time { margin-left: auto; font-size: 12px; color: var(--apc-forum-faint); font-variant-numeric: tabular-nums; }
.apc-forum__phead i { font-style: normal; font-size: 12px; color: var(--apc-forum-faint); font-variant-numeric: tabular-nums; }
.apc-forum__re { display: inline-flex; align-items: center; gap: 4px; font-size: 12px; color: var(--apc-forum-faint); }
.apc-forum__re svg { width: 13px; height: 13px; }
.apc-forum__content { display: grid; gap: 10px; margin-top: 6px; font-size: 15px; line-height: 1.65; overflow-wrap: anywhere; }
.apc-forum__content p { text-wrap: pretty; }
.apc-forum__content code { padding: 1px 5px; border-radius: 5px; font: 500 13px/1.4 ui-monospace, Menlo, monospace; background: var(--apc-forum-sunk); box-shadow: inset 0 0 0 1px var(--apc-forum-line); }
.apc-forum__content pre { overflow-x: auto; padding: 12px 14px; border-radius: 10px; font: 400 12.5px/1.6 ui-monospace, Menlo, monospace; color: oklch(0.92 0.01 220); background: oklch(0.25 0.02 230); }
.apc-forum__content pre code { padding: 0; background: none; box-shadow: none; color: inherit; font: inherit; }
.apc-forum__content ul { display: grid; gap: 4px; margin: 0; padding-left: 1.2em; list-style: disc; }
.apc-forum__content li::marker { color: var(--apc-forum-accent); }
.apc-forum__content blockquote { padding: 8px 12px; border-radius: 0 8px 8px 0; font-size: 14px; color: var(--apc-forum-muted); background: var(--apc-forum-sunk); box-shadow: inset 3px 0 var(--apc-forum-line2); }
.apc-forum__content .apc-forum__at { font-weight: 650; color: var(--apc-forum-deep); }
.apc-forum__solbox { display: grid; gap: 4px; margin-top: 4px; padding: 10px 14px; border-radius: 10px; background: color-mix(in oklab, var(--apc-forum-ok) 9%, var(--apc-forum-paper)); box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--apc-forum-ok) 30%, transparent); animation: apc-forum-in .45s var(--apc-forum-out) both; }
.apc-forum__solbox header { display: flex; align-items: center; gap: 6px; font-size: 12.5px; font-weight: 700; color: var(--apc-forum-ok); }
.apc-forum__solbox header svg { width: 16px; height: 16px; }
.apc-forum__solbox header button { margin-left: auto; font-size: 12.5px; font-weight: 650; color: var(--apc-forum-deep); }
.apc-forum__solbox header button:hover { text-decoration: underline; }
.apc-forum__solbox p { font-size: 13.5px; color: var(--apc-forum-muted); }
.apc-forum__post[data-solution] .apc-forum__pbody { position: relative; }
.apc-forum__soltag { display: inline-flex; align-items: center; gap: 4px; height: 20px; padding: 0 7px; border-radius: 6px; font-size: 11px; font-weight: 750; color: white; background: var(--apc-forum-ok); animation: apc-forum-pop .5s var(--apc-forum-spring) both; }
.apc-forum__soltag svg { width: 13px; height: 13px; stroke-width: 2.4; }
.apc-forum__acts { display: flex; align-items: center; justify-content: flex-end; gap: 2px; margin-top: 8px; }
.apc-forum__act { display: inline-flex; align-items: center; gap: 5px; height: 30px; padding: 0 9px; border-radius: 8px; font-size: 12.5px; font-weight: 650; color: var(--apc-forum-faint); font-variant-numeric: tabular-nums; transition: background-color .15s, color .15s; }
.apc-forum__act:hover { background: var(--apc-forum-hover); color: var(--apc-forum-ink); }
.apc-forum__act svg { width: 16px; height: 16px; }
.apc-forum__act[data-act="like"][aria-pressed="true"] { color: var(--apc-forum-like); }
.apc-forum__act[data-act="like"][aria-pressed="true"] svg { fill: currentColor; animation: apc-forum-heart .5s var(--apc-forum-spring); }
.apc-forum__act[data-act="solve"][aria-pressed="true"] { color: var(--apc-forum-ok); }
.apc-forum__act b { font-weight: 700; }
.apc-forum__divider { display: flex; align-items: center; gap: 10px; padding: 10px 0 2px; font-size: 11.5px; font-weight: 750; letter-spacing: .08em; text-transform: uppercase; color: var(--apc-forum-accent); }
.apc-forum__divider::before, .apc-forum__divider::after { content: ""; flex: 1; border-top: 1px solid color-mix(in oklch, var(--apc-forum-accent) 45%, transparent); }
.apc-forum__end { width: min(720px, 100%); margin: 0 auto; padding: 16px clamp(16px, 3cqi, 30px) 28px; font-size: 12.5px; color: var(--apc-forum-faint); text-align: center; }

@supports (animation-timeline: view()) {
  .apc-forum__post { animation: apc-forum-rise linear both; animation-timeline: view(); animation-range: entry 0% entry 30%; }
}

/* timeline scrubber */
.apc-forum__tl { grid-area: tl; display: grid; grid-template-rows: auto minmax(0, 1fr) auto auto; justify-items: start; gap: 8px; padding: 26px 16px 18px 6px; min-height: 0; }
.apc-forum__tlend { font-size: 12px; font-weight: 650; color: var(--apc-forum-faint); font-variant-numeric: tabular-nums; display: inline-flex; align-items: center; gap: 4px; padding: 2px 4px; border-radius: 6px; margin-left: -4px; }
.apc-forum__tlend:hover { color: var(--apc-forum-ink); background: var(--apc-forum-hover); }
.apc-forum__tlend svg { width: 13px; height: 13px; }
.apc-forum__track { position: relative; width: 100%; min-height: 80px; cursor: pointer; touch-action: none; }
.apc-forum__track::before { content: ""; position: absolute; left: 3px; top: 0; bottom: 0; width: 2px; border-radius: 2px; background: var(--apc-forum-line2); }
.apc-forum__readfill { position: absolute; left: 3px; top: 0; width: 2px; height: 100%; border-radius: 2px; background: var(--apc-forum-accent); transform-origin: 0 0; scale: 1 var(--read, 0); transition: scale .4s var(--apc-forum-ease); }
.apc-forum__handle {
  position: absolute; left: 0; top: 0; display: grid; padding: 3px 0 3px 14px; outline: none; cursor: grab; touch-action: none;
  translate: 0 calc(var(--pos, 0) * (var(--th, 100px) - 46px)); transition: translate .18s var(--apc-forum-out);
}
.apc-forum__handle::before { content: ""; position: absolute; left: 0; top: 4px; bottom: 4px; width: 8px; border-radius: 4px; background: var(--apc-forum-accent); box-shadow: 0 0 0 3px var(--apc-forum-paper); transition: scale .25s var(--apc-forum-spring); }
.apc-forum__handle:hover::before, .apc-forum__handle:focus-visible::before, .apc-forum[data-scrub] .apc-forum__handle::before { scale: 1.25 1.1; }
.apc-forum__handle:focus-visible { outline: none; }
.apc-forum__handle:focus-visible b { text-decoration: underline 2px var(--apc-forum-accent); text-underline-offset: 3px; }
.apc-forum[data-scrub] .apc-forum__handle { transition: none; cursor: grabbing; }
.apc-forum__handle b { font-size: 14px; font-weight: 760; font-variant-numeric: tabular-nums; letter-spacing: -0.01em; white-space: nowrap; }
.apc-forum__handle small { font-size: 11.5px; color: var(--apc-forum-faint); white-space: nowrap; font-variant-numeric: tabular-nums; }
.apc-forum__tlkeys { display: inline-flex; align-items: center; gap: 3px; font-size: 11px; color: var(--apc-forum-faint); }
.apc-forum__pill { display: none; }

/* composer */
.apc-forum__composer { grid-area: comp; width: min(760px, 100%); margin: 0 auto; padding: 0 clamp(12px, 2cqi, 20px) 12px; }
.apc-forum__open { display: flex; align-items: center; gap: 10px; width: 100%; height: 44px; padding: 0 12px 0 14px; border-radius: 12px; font-size: 14px; color: var(--apc-forum-faint); background: var(--apc-forum-paper); box-shadow: 0 0 0 1px var(--apc-forum-line2), 0 8px 24px -16px color-mix(in oklch, var(--apc-forum-ink) 40%, transparent); transition: box-shadow .2s, color .2s; }
.apc-forum__open:hover { color: var(--apc-forum-ink); box-shadow: 0 0 0 1px color-mix(in oklch, var(--apc-forum-accent) 50%, transparent), 0 8px 24px -16px color-mix(in oklch, var(--apc-forum-accent) 50%, transparent); }
.apc-forum__open span { flex: 1; text-align: left; }
.apc-forum__open svg { width: 16px; height: 16px; color: var(--apc-forum-accent); }
.apc-forum__drawer { display: grid; grid-template-rows: 0fr; transition: grid-template-rows .45s var(--apc-forum-spring); }
.apc-forum__dinner { min-height: 0; overflow: hidden; }
.apc-forum__composer[data-open] .apc-forum__open { display: none; }
.apc-forum__composer[data-open] .apc-forum__drawer { grid-template-rows: 1fr; }
.apc-forum__composer[data-open] .apc-forum__dinner { padding: 2px; }
.apc-forum__composer[data-open] .apc-forum__dinner > * { animation: apc-forum-in .35s var(--apc-forum-out) both; }
.apc-forum__ctx { display: flex; align-items: center; gap: 6px; padding: 0 4px 6px; font-size: 12.5px; color: var(--apc-forum-muted); }
.apc-forum__ctx b { color: var(--apc-forum-ink); }
.apc-forum__ctx button { margin-left: auto; font-size: 12px; color: var(--apc-forum-faint); }
.apc-forum__ctx button:hover { color: var(--apc-forum-ink); }
.apc-forum__composer textarea { display: block; width: 100%; min-height: 96px; max-height: 200px; padding: 12px 14px; border: 0; border-radius: 12px; outline: none; resize: none; line-height: 1.55; background: var(--apc-forum-paper); box-shadow: 0 0 0 1.5px var(--apc-forum-accent), 0 0 0 5px color-mix(in oklch, var(--apc-forum-accent) 12%, transparent); field-sizing: content; }
.apc-forum__cbar { display: flex; align-items: center; gap: 8px; padding-top: 8px; }
.apc-forum__ckeys { flex: 1; display: flex; align-items: center; gap: 4px; font-size: 11.5px; color: var(--apc-forum-faint); white-space: nowrap; overflow: hidden; }
.apc-forum__ckeys .apc-forum__kbd:not(:first-child) { margin-left: 8px; }
.apc-forum__ghost { height: 34px; padding: 0 12px; border-radius: 9px; font-size: 13.5px; font-weight: 650; color: var(--apc-forum-muted); }
.apc-forum__ghost:hover { background: var(--apc-forum-hover); color: var(--apc-forum-ink); }
.apc-forum__post-btn { height: 34px; padding: 0 18px; border-radius: 9px; font-size: 13.5px; font-weight: 700; color: var(--apc-forum-paper); background: var(--apc-forum-deep); transition: opacity .2s, scale .3s var(--apc-forum-spring); }
.apc-forum__post-btn:disabled { opacity: .35; cursor: default; }
.apc-forum__post-btn:not(:disabled):active { scale: .94; }

.apc-forum__toast { position: absolute; left: 50%; bottom: 18px; z-index: 40; display: flex; align-items: center; gap: 8px; padding: 8px 14px; border-radius: 11px; font-size: 13px; font-weight: 600; white-space: nowrap; color: var(--apc-forum-paper); background: var(--apc-forum-ink); translate: -50% 14px; opacity: 0; pointer-events: none; transition: translate .45s var(--apc-forum-spring), opacity .2s; }
.apc-forum__toast[data-show] { translate: -50% 0; opacity: 1; }
.apc-forum__toast svg { width: 16px; height: 16px; color: var(--apc-forum-like); fill: currentColor; }

@keyframes apc-forum-rise { from { opacity: 0; translate: 0 26px; } }
@keyframes apc-forum-in { from { opacity: 0; translate: 0 8px; } }
@keyframes apc-forum-pop { from { opacity: 0; scale: .5; } }
@keyframes apc-forum-grow { from { scale: 0 1; } }
@keyframes apc-forum-heart { 30% { scale: 1.35; } 60% { scale: .9; } }
@keyframes apc-forum-flash { 0%, 30% { background: color-mix(in oklch, var(--apc-forum-accent) 12%, transparent); box-shadow: 0 0 0 8px color-mix(in oklch, var(--apc-forum-accent) 12%, transparent); } }
@keyframes apc-forum-mini { from { opacity: 0; translate: 0 -100%; } to { opacity: 1; translate: 0 0; } }
