    background: var(--apc-forum-paper); box-shadow: 0 0 0 1px var(--apc-forum-line2), 0 24px 50px -20px color-mix(in oklch, var(--apc-forum-ink) 50%, transparent);
    opacity: 0; translate: 16px 0; visibility: hidden; transition: opacity .2s, translate .35s var(--apc-forum-out), visibility 0s .35s;
