/* Store with an expanded support messenger. Re-theme with --apc-widget-bg, -ink, -brand and -fly (and -h for height). */
.apc-widget {
  --apc-widget-bg: oklch(0.972 0.01 95);
  --apc-widget-ink: oklch(0.2 0.012 95);
  --apc-widget-brand: oklch(0.88 0.17 96);
  --apc-widget-fly: oklch(0.66 0.17 42);

  --apc-widget-card: oklch(0.995 0.003 95);
  --apc-widget-sunk: color-mix(in oklab, var(--apc-widget-ink) 5%, var(--apc-widget-card));
  --apc-widget-line: color-mix(in oklch, var(--apc-widget-ink) 10%, transparent);
  --apc-widget-line2: color-mix(in oklch, var(--apc-widget-ink) 17%, transparent);
  --apc-widget-muted: color-mix(in oklab, var(--apc-widget-ink) 62%, var(--apc-widget-bg));
  --apc-widget-faint: color-mix(in oklab, var(--apc-widget-ink) 44%, var(--apc-widget-bg));
  --apc-widget-brandsoft: color-mix(in oklab, var(--apc-widget-brand) 30%, var(--apc-widget-card));
  --apc-widget-ok: oklch(0.6 0.14 150);
  --apc-widget-ease: cubic-bezier(.2, .75, .2, 1);
  --apc-widget-out: cubic-bezier(.32, .72, 0, 1);
  --apc-widget-spring: linear(0, 0.07 2.6%, 0.28 6.6%, 0.67 13.4%, 0.94 20%, 1.06 27%, 1.08 33%, 1.05 41%, 1.01 52%, 0.997 66%, 1);

  position: relative;
  isolation: isolate;
  width: 100%;
  height: var(--apc-widget-h, 680px);
  container-type: inline-size;
  overflow: hidden;
  overflow: clip;
  border-radius: 16px;
  background: var(--apc-widget-bg);
  color: var(--apc-widget-ink);
  font: 400 14px/1.5 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  -webkit-font-smoothing: antialiased;
  color-scheme: light;
  accent-color: var(--apc-widget-ink);
  box-shadow: inset 0 0 0 1px var(--apc-widget-line);
}
:where(.apc-widget) *, :where(.apc-widget) *::before, :where(.apc-widget) *::after { box-sizing: border-box; }
:where(.apc-widget) :is(button, input, textarea) { font: inherit; color: inherit; }
:where(.apc-widget) button { background: none; border: 0; padding: 0; cursor: pointer; }
:where(.apc-widget) :is(h2, h3, h4, p, ul, ol) { margin: 0; }
:where(.apc-widget) :is(ul, ol) { list-style: none; padding: 0; }
:where(.apc-widget svg:not(.apc-widget__tent)) { width: 18px; height: 18px; fill: none; stroke: currentColor; stroke-width: 1.75; stroke-linecap: round; stroke-linejoin: round; flex: none; }
:where(.apc-widget) :focus-visible { outline: 2px solid var(--apc-widget-ink); outline-offset: 2px; border-radius: 8px; }
.apc-widget [hidden] { display: none !important; }

/* ---------- the host store page ---------- */
.apc-widget__site { height: 100%; display: grid; grid-template-rows: auto minmax(0, 1fr); }
.apc-widget__nav { display: flex; align-items: center; gap: 12px; padding: 16px clamp(16px, 3cqi, 32px); border-bottom: 1px solid var(--apc-widget-line); }
.apc-widget__mark { display: grid; place-items: center; width: 30px; height: 30px; border-radius: 8px; background: var(--apc-widget-ink); color: var(--apc-widget-brand); }
.apc-widget__mark svg { width: 20px; height: 20px; stroke-width: 1.9; }
.apc-widget__logo { font-size: 15px; font-weight: 850; letter-spacing: .16em; }
.apc-widget__links { display: flex; gap: 22px; margin-left: 22px; font-size: 13.5px; color: var(--apc-widget-muted); }
.apc-widget__cart { position: relative; margin-left: auto; display: grid; place-items: center; width: 38px; height: 38px; border-radius: 10px; }
.apc-widget__cart:hover { background: var(--apc-widget-line); }
.apc-widget__cart b { position: absolute; top: 2px; right: 0; min-width: 17px; height: 17px; padding: 0 4px; border-radius: 9px; display: grid; place-items: center; font-size: 10.5px; font-weight: 800; color: var(--apc-widget-ink); background: var(--apc-widget-brand); font-variant-numeric: tabular-nums; }
.apc-widget__cart b[data-bump] { animation: apc-widget-pop .5s var(--apc-widget-spring); }
.apc-widget__product { display: grid; grid-template-columns: minmax(0, 1.1fr) minmax(0, 1fr); gap: clamp(20px, 4cqi, 48px); align-items: center; padding: clamp(16px, 3cqi, 36px) clamp(16px, 3cqi, 32px); padding-right: calc(min(380px, 100cqi - 40px) + 44px); min-height: 0; overflow: auto; }
.apc-widget__stage { position: relative; display: grid; place-items: center; aspect-ratio: 4 / 3; border-radius: 22px; background: radial-gradient(90% 80% at 50% 0%, color-mix(in oklab, var(--apc-widget-brand) 35%, white), color-mix(in oklab, var(--apc-widget-ink) 6%, var(--apc-widget-bg)) 75%); overflow: hidden; }
.apc-widget__tent { width: 82%; height: auto; overflow: visible; }
.apc-widget__tent .apc-widget__shadow { fill: color-mix(in oklch, var(--apc-widget-ink) 14%, transparent); }
.apc-widget__tent .apc-widget__fly { fill: var(--apc-widget-fly); transition: fill .5s var(--apc-widget-ease); }
.apc-widget__tent .apc-widget__flyhi { fill: color-mix(in oklab, var(--apc-widget-fly) 70%, white); transition: fill .5s var(--apc-widget-ease); }
.apc-widget__tent .apc-widget__door { fill: color-mix(in oklab, var(--apc-widget-fly) 45%, black); transition: fill .5s var(--apc-widget-ease); }
.apc-widget__tent .apc-widget__pole { fill: none; stroke: color-mix(in oklab, var(--apc-widget-ink) 80%, transparent); stroke-width: 3; stroke-linejoin: round; }
.apc-widget__tent .apc-widget__guy { stroke: color-mix(in oklch, var(--apc-widget-ink) 40%, transparent); stroke-width: 1.5; stroke-dasharray: 4 4; fill: none; }
.apc-widget__badge { position: absolute; left: 14px; top: 14px; padding: 4px 10px; border-radius: 99px; font-size: 12px; font-weight: 700; background: var(--apc-widget-card); box-shadow: 0 2px 8px -2px var(--apc-widget-line2); }
.apc-widget__info { display: grid; gap: 10px; align-content: start; }
.apc-widget__crumb { font-size: 12px; font-weight: 650; letter-spacing: .08em; text-transform: uppercase; color: var(--apc-widget-faint); }
.apc-widget__info h2 { font-size: clamp(26px, 3.6cqi, 40px); font-weight: 850; letter-spacing: -0.04em; line-height: 1; text-wrap: balance; }
.apc-widget__rating { display: flex; align-items: center; gap: 8px; font-size: 13px; color: var(--apc-widget-muted); font-variant-numeric: tabular-nums; }
.apc-widget__stars { display: inline-flex; gap: 1px; color: oklch(0.7 0.16 70); }
.apc-widget__stars svg { width: 14px; height: 14px; fill: currentColor; stroke: none; }
.apc-widget__price { font-size: 22px; font-weight: 800; letter-spacing: -0.02em; font-variant-numeric: tabular-nums; }
.apc-widget__desc { color: var(--apc-widget-muted); text-wrap: pretty; max-width: 42ch; }
.apc-widget__swatches { display: flex; gap: 8px; }
.apc-widget__swatches button { width: 30px; height: 30px; border-radius: 50%; background: var(--c); box-shadow: inset 0 0 0 1px color-mix(in oklch, black 15%, transparent); transition: box-shadow .2s, scale .3s var(--apc-widget-spring); }
.apc-widget__swatches button[aria-checked="true"] { box-shadow: 0 0 0 2px var(--apc-widget-bg), 0 0 0 4px var(--apc-widget-ink); }
.apc-widget__swatches button:hover { scale: 1.08; }
.apc-widget__buy { justify-self: start; height: 46px; padding: 0 26px; border-radius: 12px; font-size: 15px; font-weight: 750; color: var(--apc-widget-brand); background: var(--apc-widget-ink); transition: scale .3s var(--apc-widget-spring), background-color .2s; }
.apc-widget__buy:hover { background: color-mix(in oklab, var(--apc-widget-ink) 85%, var(--apc-widget-brand)); }
.apc-widget__buy:active { scale: .96; }
.apc-widget__ship { font-size: 12.5px; color: var(--apc-widget-faint); }

/* ---------- messenger: one element whose clip-path morphs between launcher and panel ---------- */
.apc-widget__panel {
  position: absolute; right: 20px; bottom: 20px; z-index: 10; width: min(380px, 100% - 40px); height: min(620px, 100% - 40px);
