    later(() => setTyping(true), delay);
    delay += 650 + Math.min(1100, text.length * 14);
    later(() => { setTyping(false); append({ k: c.mode === 'agent' ? 'agent' : 'bot', who: c.mode === 'agent' ? 'rafa' : null, text, t: hhmm() }); if (i === lines.length - 1 && extra) extra.forEach((x) => append(x)); }, delay);
    delay += 120;
  });
  later(() => { S.busy = false; if (chips) setChips(chips); }, delay + 80);
  return delay;
}
const route = (text) => {
  const t = text.toLowerCase();
  if (/person|human|agent|someone|talk/.test(t)) return 'person';
  if (/sm-47110|stove/.test(t)) return 'ret-stove';
  if (/sm-48213 ·|driftline 2p$/.test(t) && S.live.asked.ret) return 'ret-tent';
  if (/return|refund|send back/.test(t)) return 'return';
  if (/compare|3p/.test(t)) return 'compare';
  if (/size|sizing|tall|fit|pad|wide/.test(t)) return 'sizing';
  if (/change delivery|reschedul|neighbou?r/.test(t)) return 'delivery';
  if (/order|where|deliver|track|parcel/.test(t)) return 'order';
  if (/thank|that’s all|that's all|bye/.test(t)) return 'thanks';
  return 'fallback';
};
function userSays(text) {
  const c = S.live;
  append({ k: 'me', text, t: hhmm() });
  setChips([]);
  if (c.mode === 'queue') return;
  if (c.mode === 'agent') { agentReply(text); return; }
  const r = route(text);
  switch (r) {
    case 'order': botSay(['Let me check. I can see one open order on your account:'], ['That’s all, thanks', 'Change delivery', 'Talk to a person'], [{ k: 'card', card: 'order' }, { k: 'bot', text: 'It left our Rotterdam warehouse on Wednesday and is out for delivery now.', t: hhmm() }]); break;
    case 'return': c.asked.ret = true; botSay(['Returns are free within 60 days, even if you’ve pitched it. Which order is it?'], [`${ORDER.n} · Driftline 2P`, 'SM-47110 · Pocket stove']); break;
    case 'ret-tent': botSay(['Done — here’s your return label for the Driftline.'], ['Thanks!', 'Talk to a person'], [{ k: 'card', card: 'label', order: ORDER.n, amount: 389, item: 'Driftline 2P' }, { k: 'bot', text: 'Drop it at any Packpoint shop. The €389 refund reaches your card within 5 days of us receiving it.', t: hhmm() }]); break;
    case 'ret-stove': botSay(['Done — here’s your return label for the stove.'], ['Thanks!', 'Talk to a person'], [{ k: 'card', card: 'label', order: 'SM-47110', amount: 54, item: 'Pocket stove' }, { k: 'bot', text: 'Drop it at any Packpoint shop. The €54 refund reaches your card within 5 days of us receiving it.', t: hhmm() }]); break;
    case 'sizing': botSay(['The Driftline 2P floor is 215 × 130 cm and fits two sleeping pads up to 64 cm wide.', 'Taller than 1.90 m? The 3P gives you 230 cm of length.'], ['Compare 2P and 3P', 'Talk to a person']); break;
    case 'compare': botSay(['Here they are side by side:'], ['That’s all, thanks', 'Talk to a person'], [{ k: 'card', card: 'compare' }]); break;
    case 'delivery': botSay(['You can choose a new day or a neighbour in the courier’s tracking page. Or I can hand you to a person who’ll sort it.'], ['Talk to a person', 'That’s all, thanks']); break;
    case 'thanks': botSay(['Happy to help, Alex. Anything else?'], START); break;
    case 'person': handoff(); break;
    default: botSay(['I’m not sure about that one. Want me to bring in someone from the team?'], ['Talk to a person', 'Where’s my order?']);
  }
}
function handoff() {
  const c = S.live;
  c.mode = 'queue';
  refreshChatHead();
  append({ k: 'sys', text: 'Tern is bringing in the team' });
  const q = { k: 'card', card: 'queue', pos: 2, p: 0.1 };
  append(q);
  const patchQ = () => {
    const el = logEl() && $$('[data-queue]', logEl()).pop();
    if (!el) return;
    el.outerHTML = cardHTML(q);
    const now = $$('[data-queue]', logEl()).pop();
    if (now) now.style.animation = 'none';
  };
  later(() => { q.p = 0.55; patchQ(); }, 1800);
  later(() => { q.pos = 1; q.p = 0.75; patchQ(); }, 3600);
  later(() => { q.p = 1; patchQ(); }, 5600);
  later(() => {
    c.mode = 'agent';
    refreshChatHead();
    append({ k: 'sys', text: 'Rafa joined the conversation' });
    botSay(['Hi Alex, Rafa here. I can see order SM-48213 is out for delivery today — what can I do for you?'], ['That’s all, thanks']);
  }, 6400);
}
function agentReply(text) {
  const c = S.live;
  if (/that’s all|that's all|thanks|thank you|bye/i.test(text)) {
    const d = botSay(['Glad I could help — enjoy the first night in the Driftline!']);
    later(() => { c.mode = 'ended'; append({ k: 'sys', text: 'Rafa closed the conversation' }); append({ k: 'card', card: 'csat', score: 0 }); refreshChatHead(); }, d + 400);
    return;
  }
  c.agentTurn = (c.agentTurn || 0) + 1;
  const lines = c.agentTurn === 1
    ? ['Got it — give me one moment to check.', 'Done. I’ve added a note for the courier, and you’ll get a text with the delivery window.']
    : ['Noted, I’ve added that to your order notes.'];
  botSay(lines, ['That’s all, thanks']);
}
function refreshChatHead() {
  if (!(S.view && S.view.type === 'chat' && S.view.c === S.live)) return;
  const html = chatHTML(S.live);
  const tmp = document.createElement('template');
  tmp.innerHTML = html;
  $('.apc-widget__who', views).replaceWith($('.apc-widget__who', tmp.content));
  const oldTail = $('.apc-widget__view[data-v="chat"] > div:last-child', views);
  const newTail = $('.apc-widget__view > div:last-child', tmp.content);
  const keep = oldTail.querySelector('textarea');
  if (!(keep && newTail.querySelector('textarea'))) { oldTail.replaceWith(newTail); mountComposerOnly(); }
  else { keep.placeholder = S.live.mode === 'agent' ? 'Message Rafa…' : 'Ask Tern anything…'; }
  renderChips();
}
function mountComposerOnly() {
  const form = $('.apc-widget__compose', views);
  if (!form) return;
  const ta = $('textarea', form), btn = $('.apc-widget__send', form);
  ta.addEventListener('input', () => { btn.disabled = !ta.value.trim(); });
  ta.addEventListener('keydown', (e) => { if (e.key === 'Enter' && !e.shiftKey && !e.isComposing) { e.preventDefault(); form.requestSubmit(); } });
  form.addEventListener('submit', (e) => { e.preventDefault(); const v = ta.value.trim(); if (!v) return; ta.value = ''; btn.disabled = true; userSays(v); });
}
function openChat(from) {
  if (!S.live || S.live.mode === 'ended') newLive();
  push({ type: 'chat', c: S.live, from: from || S.tab });
}

/* ---------------- open / close ---------------- */
function setOpen(open) {
  S.open = open;
  root.toggleAttribute('data-open', open);
  body.inert = !open;
  launcher.setAttribute('aria-expanded', open);
  launcher.setAttribute('aria-label', open ? 'Close messenger' : S.unreadLaunch ? `Open messenger, ${S.unreadLaunch} new` : 'Open messenger');
  if (open) {
    S.unreadLaunch = 0; unreadEl.hidden = true;
    later(() => { const f = $('.apc-widget__compose textarea', views) || $('button, input', views); if (f) f.focus({ preventScroll: true }); }, 120);
  } else launcher.focus({ preventScroll: true });
}
let toastT = 0;
function say(t) {
  toast.textContent = t;
  toast.setAttribute('data-show', '');
  clearTimeout(toastT);
  toastT = setTimeout(() => { if (root.isConnected) toast.removeAttribute('data-show'); }, 2200);
}

/* ---------------- events ---------------- */
root.addEventListener('click', (e) => {
  const tab = e.target.closest('[data-tab]');
  if (tab) { goTab(tab.dataset.tab); return; }
  const chip = e.target.closest('[data-chip]');
  if (chip) { if (!S.busy) userSays(chip.dataset.chip); return; }
  const art = e.target.closest('[data-article]');
  if (art) { push({ type: 'article', id: art.dataset.article, from: S.tab }); return; }
  const rate = e.target.closest('[data-rate]');
  if (rate) {
    const m = S.live && S.live.log.find((x) => x.card === 'csat');
    if (m && !m.score) { m.score = +rate.dataset.rate; const el = $('[data-csat]', views); if (el) el.outerHTML = cardHTML(m); say('Thanks for rating the conversation'); }
    return;
  }
  const a = e.target.closest('[data-act]');
  if (!a) return;
  switch (a.dataset.act) {
    case 'toggle': setOpen(!S.open); break;
    case 'chat': openChat(); break;
    case 'newchat': S.live = null; openChat('messages'); break;
    case 'past': push({ type: 'chat', c: PAST, from: 'messages' }); break;
    case 'track': openChat('home'); if (!S.live.asked.order) { S.live.asked.order = true; later(() => { if (!S.busy) userSays('Where’s my order?'); else later(() => userSays('Where’s my order?'), 1600); }, 500); } break;
    case 'back': back(); break;
    case 'helpful': { const box = a.closest('[data-helpful]'); box.innerHTML = a.dataset.v === 'yes' ? '<span>Thanks! Glad it helped.</span>' : '<span>Sorry about that — tap “Message us” and we’ll help directly.</span>'; break; }
    case 'buy': S.cart++; { const b = $('.apc-widget__cart b'); b.textContent = S.cart; b.removeAttribute('data-bump'); void b.offsetWidth; b.setAttribute('data-bump', ''); $('.apc-widget__cart').setAttribute('aria-label', `Basket, ${S.cart} items`); } say(`Added Driftline 2P in ${COLORS[S.color].k} to your basket`); break;
    case 'cart': say(S.cart ? `Basket: ${S.cart} × Driftline 2P · €${S.cart * 389}` : 'Your basket is empty'); break;
  }
});
root.addEventListener('input', (e) => {
  if (!e.target.matches('[data-find]')) return;
  S.q = e.target.value;
  if (S.view || S.tab !== 'help') { goTab('help', true); return; }
  const res = $('[data-results]', views);
  if (res) res.innerHTML = helpList();
});
root.addEventListener('keydown', (e) => {
  const chip = e.target.closest && e.target.closest('[data-chip]');
  if (chip && (e.key === 'ArrowRight' || e.key === 'ArrowLeft')) {
    e.preventDefault();
    const all = $$('[data-chip]', views);
    const n = all[(all.indexOf(chip) + (e.key === 'ArrowRight' ? 1 : -1) + all.length) % all.length];
    all.forEach((x) => { x.tabIndex = x === n ? 0 : -1; });
    n.focus();
    return;
  }
  if (e.key === 'Escape' && S.open && e.target.closest && e.target.closest('.apc-widget__panel')) {
    e.preventDefault();
    if (!back()) setOpen(false);
  }
});

